// TDS DECLARATIONS, PROOFS AND MONTHLY TDS (owner, 14 Oct) — config/income-tax.json + Customisation `tds-settings`.
$taxDeclarations = new SmartPRS\Surface\TaxDeclarations($store, $customisation, __DIR__ . '/../config/income-tax.json', financialYearStart($customisation),
    static fn (array $e): bool => in_array('TDS', $statutoryApplicability->offHeads($e), true),
    static fn (array $e): array => $employeeExtras->forEmployment(SmartPRS\Surface\Employment::code($e)));
$register = new Register($store, $period, $structure, $statutory, $recoveries,
    (array) ((json_decode((string) file_get_contents(__DIR__ . '/../config/payroll-approval.json'), true) ?: [])['steps'] ?? []), $payCycles, new SmartPRS\Surface\Shifts($store), $componentRules,
    $statutoryApplicability, (new SmartPRS\Surface\PayrollInputs($store, __DIR__ . '/../config/payroll-inputs.json'))->withTax($taxDeclarations), $certificateHolds,
