  <div class="card"><p><?= (string) $obRow['status'] === SelfOnboarding::SUBMITTED
      ? 'Your details are with HR for verification. You will be contacted if anything needs correcting.'
      : 'This form is closed.' ?></p></div>
<?php else: ?>
  <div class="card">
    <form method="post" enctype="multipart/form-data">
      <input type="hidden" name="csrf" value="<?= e((string) $obRow['token']) ?>">
      <input type="hidden" name="t" value="<?= e((string) $obRow['token']) ?>">
<?php
    $obGrouped = [];
    foreach (array_merge($obFields, $obDocs) as $obF) { $obGrouped[(string) $obF['section']][] = $obF; }
    foreach ($obGrouped as $obTitle => $obSectionFields): ?>
      <h3><?= e((string) $obTitle) ?></h3>
      <div class="row">
<?php   foreach ($obSectionFields as $obF):
          $obValue = ($obF['storage'] ?? 'column') === 'column' ? (string) ($obData['columns'][(string) $obF['column']] ?? '') : (string) ($obData['extras'][(string) $obF['code']] ?? '');
          // A required field already answered is not re-required on the next
          // visit: the value is on file, and a browser cannot re-attach a file.
          $obField = $obValue !== '' && (string) $obF['type'] === 'Image/PDF/Doc' ? $obF + ['required' => false] : $obF; ?>
        <div><label for="ef-<?= e((string) $obF['code']) ?>"><?= e((string) $obF['label']) ?><?php if ($obF['required'] ?? false): ?> <span style="color:#dc2626">*</span><?php endif; ?></label>
          <?= employeeFieldControl($obField, $obValue, $obLookups) ?>
