    // THE INBOX BADGE IS THE INBOX PAGE'S OWN COUNT (owner, 6 Nov 2026: one leave pending, badge 0): requests, leave,
    // transfers and requisitions waiting on THIS person — the same partial the page and its export read.
    $navInbox = (static function () use ($requests, $modules, $access, $scope, $may, $session, $store, $transfers, $recruitment, $requisitionDecider): int {
        try {
            $params = [];
            include __DIR__ . '/../surface/partials/people-inbox-data.php';

            return count($ibMine) + count($ibLeaves) + count($ibTransfers) + count($ibRequisitions);
        } catch (\Throwable) {
            return 0; // a register not there yet counts as nothing waiting
        }
    })();
    $navBadges = [
        'inbox' => $navInbox,
        'approvals' => count($requests->open()),
        'modules' => count($modules->all()),
        'leave_approvals' => count(leaveQueueFor($store, $leave, $scope, $may, null, leaveSelfApproves((string) ($session->user()['role'] ?? '')))),
    ];
    // LEAVE APPROVALS is in the menu only for someone who can ever have
    // anything in it: a holder of leave decisions, or an employee somebody
    // reports to. A regular employee with no team never sees it.
    $navFlags = ['leave_approver' => $may('leave.request.decide') || hasDirectReports($store, $scope->own()) || leaveSelfApproves((string) ($session->user()['role'] ?? ''))];
    // WHO IS SIGNED IN, as a person rather than a login: the employee this
    // account is bound to (Users::bind — `users.employee_id`), so the avatar
    // shows their own photo and their own name's initials rather than two
    // letters lifted off their email. An account bound to nobody falls back to
    // the email, which is the same "sees nothing of its own" direction Session
    // already resolves an unbound actor to.
    $acctEmployee = ($session->user()['employee_id'] ?? null) !== null
        ? $store->find('employees', (string) $session->user()['employee_id'])
        : null;
    $acctName = trim((string) ($acctEmployee['name'] ?? ''));
    $acctPhoto = trim((string) ($acctEmployee['photo_path'] ?? ''));

    if ($acctName !== '') {
        $acctWords = preg_split('/\s+/', $acctName, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $initials = count($acctWords) >= 2
            ? strtoupper(mb_substr($acctWords[0], 0, 1) . mb_substr($acctWords[count($acctWords) - 1], 0, 1))
            : strtoupper(mb_substr($acctWords[0] ?? '', 0, 2));
    } else {
        $initials = strtoupper(substr((string) $session->user()['email'], 0, 2));
    }
?>
