<script>
// ACCOUNT MENU — SAME BEHAVIOUR AS PRS2's addLogout(): click the sidebar
// profile card, get a small popup anchored above it; click outside to close.
// A header (the SIGNED-IN account's own photo/initials, name, email — never
// anybody else's, there is nothing here that takes an id) above the same two
// rows PRS2's own menu has: Account settings (go('account-settings')) and
// Sign out.
window.acctMenuToggle = function (ev) {
  ev.stopPropagation();
  var open = document.getElementById('sp-acct-menu');
  if (open) { open.remove(); return; }
  var foot = document.getElementById('sidebar-footer');
  var m = document.createElement('div');
  m.id = 'sp-acct-menu';
  m.style.cssText = 'position:absolute;left:12px;right:12px;bottom:62px;background:#fff;border:1px solid rgba(15,23,42,0.12);border-radius:12px;box-shadow:0 12px 32px rgba(15,23,42,0.24);overflow:hidden;z-index:9000';
  m.innerHTML = '<div style="padding:14px;display:flex;align-items:center;gap:10px;background:#f8fafc;border-bottom:1px solid rgba(15,23,42,0.08)">'
    + '<div style="width:38px;height:38px;border-radius:9px;flex:none;overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;background:var(--accent,#f97316)">'
    + <?= json_encode($acctPhoto !== '' ? '<img src="' . e($acctPhoto) . '" alt="" style="width:100%;height:100%;object-fit:cover">' : e($initials), JSON_HEX_TAG | JSON_HEX_AMP) ?>
    + '</div><div style="min-width:0;overflow:hidden">'
    + '<div style="font-size:13px;font-weight:700;color:#0f172a;white-space:normal;overflow-wrap:anywhere">' + <?= json_encode($acctName !== '' ? $acctName : explode('@', (string) $session->user()['email'])[0], JSON_HEX_TAG | JSON_HEX_AMP) ?> + '</div>'
    + '<div style="font-size:11.5px;color:#64748b;white-space:normal;overflow-wrap:anywhere">' + <?= json_encode((string) $session->user()['email'], JSON_HEX_TAG | JSON_HEX_AMP) ?> + '</div>'
    + '</div></div>'
    + '<div class="sp-acct-row" style="padding:11px 14px;font-size:13px;color:#0f172a;cursor:pointer;display:flex;align-items:center;gap:9px;transition:background .12s"><i class="fas fa-user-gear" style="width:15px;color:#64748b"></i> Account settings</div>'
    + '<div class="sp-acct-row" style="padding:11px 14px;font-size:13px;color:#dc2626;cursor:pointer;display:flex;align-items:center;gap:9px;border-top:1px solid rgba(15,23,42,0.08);transition:background .12s"><i class="fas fa-right-from-bracket" style="width:15px"></i> Sign out</div>';
  var rows = m.querySelectorAll('.sp-acct-row');
  rows[0].onclick = function (e) {
    e.stopPropagation();
    window.location.href = '?r=account-settings';
  };
  rows[1].onclick = function (e) {
    e.stopPropagation();
    document.getElementById('sp-signout-form').submit();
  };
  foot.appendChild(m);
  setTimeout(function () {
    document.addEventListener('click', function closer() {
      var x = document.getElementById('sp-acct-menu');
      if (x) { x.remove(); }
      document.removeEventListener('click', closer);
    });
  }, 0);
};
</script>

<?php
    // THE SCREEN GUIDE, SmartPRS 2's (i): content from config/screen-help.json,
    // keyed by the route (or the module key on a module screen), mapped where
    // the two products name a screen differently, generic where nobody has
    // written one yet. Rendered here, so it needs no second request.
    $helpCfg = configWithDropIns(__DIR__ . '/../config/screen-help.json', ['screens', 'routes']);
    $helpKey = $route === 'm' ? (string) ($_GET['k'] ?? '') : $route;
    $helpKey = (string) ($helpCfg['routes'][$helpKey] ?? $helpKey);
    $help = $helpCfg['screens'][$helpKey] ?? ($helpCfg['fallback'] ?? []);
    $help = is_array($help) ? $help : [];

    // PROBATION REMINDERS REACH PEOPLE WHO NEVER OPEN THE BOARD (owner, 28 Sep:
    // "the Admin and HR Admins get notifications in their logins according to
    // the interval set"). The sweep used to run only when somebody visited
    // People → Probation — so the reminder that should have sent them there
    // only existed once they had already gone. Now the first page any signed-in
    // user opens each day runs it over every employee; queue() dedupes per
    // employee, milestone, end date and recipient, so running it again sends
    // nothing twice. Once per session per day keeps it off every request.
    if (($_SESSION['probation_swept_on'] ?? '') !== date('Y-m-d')) {
        try {
            $probation->remind($notifications, liveRows($store, 'employees'), date('Y-m-d'));
        } catch (\Throwable $probSweepError) {
            // a reminder sweep that fails must not take the page down with it; the board runs the same sweep and shows its error there
            error_log('Probation reminder sweep: ' . $probSweepError->getMessage());
        }

        $_SESSION['probation_swept_on'] = date('Y-m-d');
    }

    // PHONES WAITING FOR APPROVAL ARE TOLD (owner, 5 Nov 2026), also ones registered before the app told anybody: every
    // pending registration is announced once (same key as public/mobile.php, so never twice). Every 5 minutes per session.
    if (!$superConsole && ($_SESSION['md_swept_at'] ?? 0) < time() - 300) {
        $_SESSION['md_swept_at'] = time();
        try {
            foreach ($store->all('mobile_devices') as $mdP) {
                if ((string) ($mdP['status'] ?? '') !== 'pending' || trim((string) ($mdP['deleted_at'] ?? '')) !== '' || ($mdE = $store->find('employees', (string) ($mdP['employee_id'] ?? ''))) === null) { continue; }
                requestNotify($mdE, 'Mobile app approval', 'mobile-device', 'device:' . (string) $mdP['id'],
                    'Phone ' . (trim((string) ($mdP['device_name'] ?? '')) ?: 'unknown') . ' (phone code ' . (string) ($mdP['code'] ?? '') . ') is waiting for approval in Administration → Mobile Devices.');
            }
        } catch (\Throwable $mdSweepError) {
            error_log('Mobile device approval sweep: ' . $mdSweepError->getMessage()); // no devices table yet: nothing to tell
        }
    }

    // THE BELL: unread messages for this login — its own employee code and its
    // role (probation reminders are addressed to roles).
    $bellOwnRow = $scope->own() === null ? null : $store->find('employees', (string) $scope->own());
    $bellUnread = 0;
    // SUPER ADMIN SEES NO COMPANY NOTIFICATIONS (owner, 6 Nov 2026): no bell, no popup in /super — they belong to the companies.
    if (!$superConsole) try {
        $bellUnread = $notifications->unreadFor($bellOwnRow === null ? '' : Employment::code($bellOwnRow),
            [SmartPRS\Surface\Notifications::ROLE_PREFIX . (string) ($session->user()['role'] ?? '')]);
    } catch (\Throwable) {
        $bellUnread = 0; // no notification table yet reads as nothing unread
    }

    // NEW NOTIFICATIONS POP UP (owner, 5 Nov 2026: "the admin should get the NOTIFICATION popup every time any request is
    // generated"): the unread messages of the last 7 days for this login, newest first; each pops up once per browser.
    $bellPop = [];
    if (!$superConsole) try {
        $bellRoutes = (array) (((array) json_decode((string) @file_get_contents(__DIR__ . '/../config/notification-routes.json'), true))['routes'] ?? []);
        foreach ($notifications->queuedFor($bellOwnRow === null ? '' : Employment::code($bellOwnRow), PHP_INT_MAX,
            [SmartPRS\Surface\Notifications::ROLE_PREFIX . (string) ($session->user()['role'] ?? '')]) as $bellM) {
            if (trim((string) ($bellM['read_at'] ?? '')) !== '' || (string) ($bellM['created_at'] ?? '') < date('Y-m-d H:i:s', time() - 7 * 86400)) { continue; }
            $bellTo = SmartPRS\Surface\Notifications::routeFor($bellM, $bellRoutes);
            $bellPop[] = ['id' => (string) $bellM['id'], 'title' => (string) ($bellM['title'] ?? ''), 'body' => (string) ($bellM['body'] ?? ''),
                'at' => (string) ($bellM['created_at'] ?? ''), 'url' => $bellTo !== '' ? $bellTo : '?r=notifications']; // routeFor() already returns '?r=…' (6 Nov: was doubled)
        }
        usort($bellPop, static fn (array $a, array $b): int => strcmp($b['at'], $a['at']));
        $bellPop = array_slice($bellPop, 0, 20);
    } catch (\Throwable) {
        $bellPop = []; // no notification table yet: nothing to pop up
    }

    // INTERVIEW POPUP (owner, 21 Oct): rounds this login sits on the panel of, shown at their time.
    $ivPopups = [];

    try {
        $ivPopups = $bellOwnRow === null ? [] : SmartPRS\Surface\InterviewNotices::dueFor($store, Employment::code($bellOwnRow), time());
    } catch (\Throwable) {
        $ivPopups = []; // no interviews table yet: nothing to pop up
    }
?>
