<script>
(function () {
  var list = <?= json_encode($bellPop, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>, dlg = document.getElementById('nt-pop');
  var seen = function (id) { try { return localStorage.getItem('ntpop-' + id) === '1'; } catch (e) { return false; } };
  var fresh = list.filter(function (x) { return !seen(x.id); });
  if (!fresh.length) { return; }
  var esc = function (t) { var d = document.createElement('div'); d.textContent = t; return d.innerHTML; };
  document.getElementById('nt-pop-h').textContent = fresh.length === 1 ? 'New notification' : fresh.length + ' new notifications';
  document.getElementById('nt-pop-b').innerHTML = fresh.map(function (x) { return '<li style="margin:6px 0"><a href="' + esc(x.url) + '" data-nt="' + esc(x.id) + '" style="font-weight:700;color:var(--accent)">' + esc(x.title) + '</a><div class="note" style="margin:2px 0 0">' + esc(x.body) + '</div></li>'; }).join('');
  var done = function () { fresh.forEach(function (x) { try { localStorage.setItem('ntpop-' + x.id, '1'); } catch (e) {} }); };
  document.getElementById('nt-pop-ok').onclick = function () { done(); dlg.close(); };
  dlg.addEventListener('click', function (ev) { if (ev.target.closest('a')) { done(); } });
  var open = function () { if (document.querySelector('dialog[open]')) { setTimeout(open, 3000); return; } dlg.showModal(); };
  setTimeout(open, 400);
  try { if (window.Notification && Notification.permission === 'granted') { new Notification(fresh[0].title, {body: fresh[0].body}); } } catch (e) {}
})();
</script>
