<script>
(function () {
  var list = <?= json_encode($ivPopups, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>, dlg = document.getElementById('iv-pop'), key = null;
  function seen(k) { try { return localStorage.getItem(k) === '1'; } catch (e) { return false; } }
  function show(x) {
    var k = 'ivpop-' + x.id + '-' + x.at;
    if (seen(k)) { return; }
    if (dlg.open) { setTimeout(function () { show(x); }, 5000); return; }
    key = k;
    document.getElementById('iv-pop-t').textContent = x.title;
    document.getElementById('iv-pop-b').textContent = x.body;
    document.getElementById('iv-pop-go').href = x.url;
    dlg.showModal();
    try { if (window.Notification && Notification.permission === 'granted') { new Notification(x.title, {body: x.body}); } } catch (e) {}
  }
  document.getElementById('iv-pop-ok').onclick = function () { try { localStorage.setItem(key, '1'); } catch (e) {} dlg.close(); };
  document.getElementById('iv-pop-go').onclick = function () { try { localStorage.setItem(key, '1'); } catch (e) {} };
  list.forEach(function (x) { setTimeout(function () { show(x); }, Math.max(0, x.at * 1000 - Date.now())); });
})();
</script>
