<script>
/* The picker writes the same four attributes and the same inline accent the
   boot script at the top of the page reads back, so what you see after a
   click and what you see after a reload are produced by one description of
   the theme rather than two that have to be kept in step. */
(function(){
  var btn=document.getElementById('theme-btn'),panel=document.getElementById('theme-panel');
  if(!btn||!panel){return;}
  var d=document.documentElement,K='smartprs.theme.';
  function g(k){try{return localStorage.getItem(K+k)||'';}catch(e){return '';}}
  function put(k,v){try{v?localStorage.setItem(K+k,v):localStorage.removeItem(K+k);}catch(e){}}
  function attr(n,v){v?d.setAttribute(n,v):d.removeAttribute(n);}
  function paintAccent(v){
    if(/^#[0-9A-Fa-f]{6}$/.test(v)){
      d.style.setProperty('--accent',v);d.style.setProperty('--accent2',v);
      d.style.setProperty('--accent-soft','rgba('+parseInt(v.substr(1,2),16)+','
        +parseInt(v.substr(3,2),16)+','+parseInt(v.substr(5,2),16)+',.10)');
    }else{
      d.style.removeProperty('--accent');d.style.removeProperty('--accent2');
      d.style.removeProperty('--accent-soft');
    }
  }
  function applyMode(m){
    attr('data-mode',m==='auto'
      ?(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')
      :(m==='dark'?'dark':'light'));
  }
  function press(sel,key,fallback){
    var cur=g(key)||fallback;
    panel.querySelectorAll(sel).forEach(function(b){
      b.setAttribute('aria-pressed',String(b.getAttribute(sel.slice(1,-1))===cur));
    });
  }
  function mark(){
    press('[data-mode-set]','mode','auto');
    press('[data-preset]','preset','');
    press('[data-density-set]','density','');
    press('[data-scale-set]','scale','');
    var a=g('accent');
    if(/^#[0-9A-Fa-f]{6}$/.test(a)){document.getElementById('theme-accent').value=a;}
  }
  panel.addEventListener('click',function(e){
    var b=e.target.closest('button');
    if(!b||!panel.contains(b)){return;}
    if(b.hasAttribute('data-mode-set')){var m=b.getAttribute('data-mode-set');put('mode',m);applyMode(m);}
    else if(b.hasAttribute('data-preset')){var t=b.getAttribute('data-preset');put('preset',t);attr('data-theme',t);}
    else if(b.hasAttribute('data-density-set')){var n=b.getAttribute('data-density-set');put('density',n);attr('data-density',n);}
    else if(b.hasAttribute('data-scale-set')){var z=b.getAttribute('data-scale-set');put('scale',z);attr('data-scale',z);}
    else if(b.id==='theme-accent-clear'){put('accent','');paintAccent('');}
    else if(b.id==='theme-reset'){
      ['mode','preset','density','scale','accent'].forEach(function(k){put(k,'');});
      attr('data-theme','');attr('data-density','');attr('data-scale','');
      paintAccent('');applyMode('auto');
    }else{return;}
    mark();
  });
  document.getElementById('theme-accent').addEventListener('input',function(){
    put('accent',this.value);paintAccent(this.value);mark();
  });
  btn.addEventListener('click',function(e){
    e.stopPropagation();
    var open=panel.classList.toggle('open');
    btn.setAttribute('aria-expanded',String(open));
    if(open){mark();}
  });
  /* A panel that only closes by its own button is one people leave open over
     the screen they wanted to read. */
  document.addEventListener('click',function(e){
    if(panel.classList.contains('open')&&!panel.contains(e.target)&&e.target!==btn){
      panel.classList.remove('open');btn.setAttribute('aria-expanded','false');
    }
  });
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'&&panel.classList.contains('open')){
      panel.classList.remove('open');btn.setAttribute('aria-expanded','false');btn.focus();
    }
  });
})();
</script>
