    $uaYesterday = date('Y-m-d', strtotime('-1 day'));
    $uaSweep = is_array($_SESSION['ua_sweep'] ?? null) ? $_SESSION['ua_sweep'] : null;
    $uaRows = [];
    if ($uaSweep !== null) {
        $uaByCode = [];
        foreach ($ntScoped as $uaE) { $uaC = Employment::code($uaE); $uaC === '' || $uaByCode[$uaC] = $uaE; }
        $uaPass = null;
        if (array_filter($ntFilter) !== []) {
            $uaPass = [];
            foreach (orgFilterApply($store, $ntScoped, $ntFilter) as $uaE) { $uaPass[Employment::code($uaE)] = true; }
        }
        foreach ((array) ($uaSweep['escalated'] ?? []) as $uaHit) {
            $uaC = (string) ($uaHit['code'] ?? '');
            if (!isset($uaByCode[$uaC]) || ($uaPass !== null && !isset($uaPass[$uaC]))) { continue; }
            $uaRows[$uaC] = $uaHit + ['e' => $uaByCode[$uaC]]; // stages arrive in order, so the last one kept is the highest
        }
        uasort($uaRows, static fn (array $x, array $y): int => [(int) $y['run_days'], $x['code']] <=> [(int) $x['run_days'], $y['code']]);
    }
    $uaStageCounts = array_count_values(array_map(static fn (array $r): string => (string) $r['stage'], $uaRows));
