<?php elseif ($route === 'live-salary'): ?>
<?php
    // RUNNING-MONTH EARNINGS TILL TODAY. SmartPRS 2 read the latest payroll run's
    // payslips and called them "live". This asks the same engine the payslip uses
    // for the month so far: payable days settled from the 1st to today, prorated
    // over the month's declared days, through Platform\Payroll — so the figure
    // here and the payslip on the last day are one arithmetic, not two.
    $lsFrom = date('Y-m-01');
    $lsToday = date('Y-m-d');
    // THE CURRENT PAY CYCLE, NOT THE CALENDAR MONTH (owner, 23 Oct): each employee's own cycle from
    // Organization Configuration → Pay Cycle (21 Sep → 20 Oct, say) — the window today falls in — so
    // "earned so far" runs from that cycle's first day, prorated over that cycle's days. No cycle set:
    // the calendar month.
    $lsCycle = static function (array $e) use ($payCycles, $lsToday): array {
        $rule = $payCycles->for($e);
        if ($rule !== null) {
            foreach ([0, 1, -1] as $sh) {
                $m = date('Y-m', (int) strtotime(date('Y-m-01') . sprintf(' %+d month', $sh)));
                [$f, $t] = PayCycles::window($rule, $m);
                if ($lsToday >= $f && $lsToday <= $t) {
                    return ['month' => $m, 'from' => $f, 'to' => $t, 'name' => trim((string) ($rule['name'] ?? ''))];
                }
            }
        }
        return ['month' => date('Y-m'), 'from' => date('Y-m-01'), 'to' => date('Y-m-t'), 'name' => ''];
    };
    $lsShort = static fn (string $d): string => date("d M'y", (int) strtotime($d));
    $lsVisible = $may('payroll.view')
        ? $scope->only($store->all('employees'), $may('employee.list'))
        : array_values(array_filter([$scope->own() === null ? null : $store->find('employees', (string) $scope->own())]));
    $lsRows = [];
    $lsProblems = [];
    $lsBasis = $structure->contractedCostBasis(date('Y-m-t'));

    foreach (array_slice($lsVisible, 0, 200) as $lsE) {
        $lsCode = Employment::code($lsE);

        if ($lsCode === '') {
            continue;
        }

        try {
            $lsC = $lsCycle($lsE);
            $lsDerived = $period->forPeriod($lsCode, $lsC['from'], $lsToday, $calendar->shiftStart(), $calendar->shiftEnd());
            // The cycle's days, not the days elapsed: prorated over the whole pay cycle.
            $lsMonthDays = $calendar->prorationDays($lsC['from'], $lsC['to'], $lsE, (array) (orgNames($store)['designation_roles'] ?? []))['days'] ?? ((int) round((strtotime($lsC['to']) - strtotime($lsC['from'])) / 86400) + 1);
            $lsComponents = structureFor($lsE);
            $lsRun = new PayrollRun($lsC['month'], $lsComponents, [[
                'employment_id' => $lsCode,
                'gross' => monthlyGrossOf($lsE, $lsBasis, $lsComponents),
                'payable_days' => $lsDerived['payable'],
                'period_days' => $lsMonthDays,
            ]]);
            $lsSlip = $lsRun->payslips[0];
            $lsRows[] = ['e' => $lsE, 'code' => $lsCode, 'payable' => $lsDerived['payable']->toDecimalString(), 'month_days' => $lsMonthDays, 'slip' => $lsSlip, 'derived' => $lsDerived, 'cycle' => $lsC,
                'worked' => $lsDerived['worked_days'], 'paid_leave' => $lsDerived['paid_leave_days'], 'unpaid' => $lsDerived['unpaid_leave_days'],
                'attention' => $lsDerived['needing_attention'], 'gross' => $lsSlip->grossEarnings()->format(),
                'deductions' => $lsSlip->totalDeductions()->format(), 'net' => $lsSlip->netPay()->format(),
                'negative' => $lsSlip->netPay()->isNegative()];
        } catch (\Throwable $lsX) {
            $lsProblems[] = $lsCode . ': ' . $lsX->getMessage();
        }
    }
?>
<?php
    // ONE EMPLOYEE OR ALL — SmartPRS 2's picker, with "All Employees" first so the
