    $lsPick = (string) ($_GET['id'] ?? '');
    $lsOne = null;
    foreach ($lsRows as $lsR) { if ((string) $lsR['e']['id'] === $lsPick) { $lsOne = $lsR; } }
    if ($lsOne === null && count($lsRows) === 1 && !$may('payroll.view')) { $lsOne = $lsRows[0]; }
    $lsCycles = [];
    foreach ($lsRows as $lsR) { $lsCycles[$lsR['cycle']['from'] . '|' . $lsR['cycle']['to']] = $lsR['cycle']; }
    $lsSeen = $lsOne !== null ? [$lsOne['cycle']] : array_values($lsCycles);
    $lsCycleText = static fn (array $c): string => $lsShort($c['from']) . ' to ' . $lsShort($c['to']);
?>
  <div class="page-header">
    <div><h2>Live salary</h2><p><?php if (count($lsSeen) === 1): $lsC1 = $lsSeen[0]; ?>Current pay cycle: <b><?= e($lsCycleText($lsC1)) ?></b><?= $lsC1['name'] !== '' ? ' (' . e($lsC1['name']) . ')' : ' (calendar month)' ?> &middot; earned from <?= e(date('d-m-Y', strtotime($lsC1['from']))) ?> to today, <?= e(date('d-m-Y', strtotime($lsToday))) ?> &middot; salary month <?= e(date('F Y', strtotime($lsC1['month'] . '-01'))) ?><?php else: ?>Earned so far in each employee's <b>current pay cycle</b> (see the Pay cycle column) up to today, <?= e(date('d-m-Y', strtotime($lsToday))) ?><?php endif; ?> &middot; from the settled attendance, through the payroll engine</p></div>
