<?php $lsChoices = []; foreach ($lsRows as $lsR) { $lsChoices[(string) $lsR['e']['id']] = (string) $lsR['e']['name'] . ' (' . $lsR['code'] . ')'; } ?>
      <?= employeePicker('ls-pick', 'id', $lsChoices, $lsOne !== null ? (string) $lsOne['e']['id'] : '',
          'All Employees', false, 'onchange="this.form.submit()" style="min-width:240px"') ?></form>
<?php endif; ?>
  </div>
<?php if ($lsOne !== null): $lsS = $lsOne['slip']; $lsD = $lsOne['derived'];
    $lsCyc = $lsOne['cycle'];
    $lsElapsed = (int) round((strtotime($lsToday) - strtotime($lsCyc['from'])) / 86400) + 1;
    $lsDaysInMonth = (int) round((strtotime($lsCyc['to']) - strtotime($lsCyc['from'])) / 86400) + 1; ?>
  <div class="card" style="text-align:center;background:linear-gradient(135deg,#0f1d33,#1e3a5f);color:#fff">
    <div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;opacity:.75">Net salary earned till today &middot; <?= e((string) $lsOne['e']['name']) ?> (<?= e($lsOne['code']) ?>)</div>
    <div style="font-size:40px;font-weight:800;margin:6px 0"><?= e($lsOne['net']) ?></div>
    <div style="font-size:12.5px;opacity:.8"><?= e($lsOne['payable']) ?> payable of <?= $lsOne['month_days'] ?> days &middot; <?= intdiv($lsElapsed * 100, max(1, $lsDaysInMonth)) ?>% of the pay cycle <?= e($lsCycleText($lsCyc)) ?> elapsed &middot; <?= e($lsD['worked_days']) ?> worked + <?= e($lsD['paid_leave_days']) ?> paid leave<?= $lsD['unpaid_leave_days'] !== '0' ? ' · ' . e($lsD['unpaid_leave_days']) . ' LOP' : '' ?><?= $lsOne['attention'] > 0 ? ' · ' . $lsOne['attention'] . ' day(s) to regularise' : '' ?></div>
  </div>
