<?php foreach ($lsS->lines as $lsL): if ($lsL->kind === 'deduction') { continue; } ?>
      <div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--border)"><span><b style="color:#15803d;margin-right:8px">+</b><?= e($lsL->componentCode) ?> <span class="note"><?= e($lsL->trace) ?></span></span><b style="color:#15803d;font-family:var(--mono)"><?= e($lsL->amount->format()) ?></b></div>
<?php endforeach; ?>
      <div style="display:flex;justify-content:space-between;padding:11px 0 2px;font-weight:800;font-size:15px"><span>Total earnings</span><span style="color:#15803d"><?= e($lsOne['gross']) ?></span></div></div>
    <div class="card" style="flex:1;margin:0"><div style="font-weight:800;margin-bottom:6px;color:#b91c1c"><i class="fas fa-minus-circle"></i> Deductions</div>
<?php $lsHasDed = false; foreach ($lsS->lines as $lsL): if ($lsL->kind !== 'deduction') { continue; } $lsHasDed = true; ?>
      <div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--border)"><span><b style="color:#b91c1c;margin-right:8px">&minus;</b><?= e($lsL->componentCode) ?> <span class="note"><?= e($lsL->trace) ?></span></span><b style="color:#b91c1c;font-family:var(--mono)"><?= e($lsL->amount->format()) ?></b></div>
<?php endforeach; if (!$lsHasDed): ?><div class="note" style="padding:12px">No deductions yet</div><?php endif; ?>
      <div style="display:flex;justify-content:space-between;padding:11px 0 2px;font-weight:800;font-size:15px"><span>Total deductions</span><span style="color:#b91c1c"><?= e($lsOne['deductions']) ?></span></div></div>
  </div>
  <p class="note"><?= e($lsD['why']) ?><?php if ($may('payroll.run')): ?> <a href="?r=payroll&amp;id=<?= e((string) $lsOne['e']['id']) ?>&amp;from=<?= e($lsCyc['from']) ?>&amp;to=<?= e($lsToday) ?>">Full working &rarr;</a><?php endif; ?></p>
<?php endif; ?>
<?php if (!$may('payroll.view')): ?>
  <p class="note">You see your own running figure. Others' salaries need <code>payroll.view</code>.</p>
