<?php if ($lsProblems !== []): ?>
  <div class="problem"><?= count($lsProblems) ?> employee(s) could not be computed: <?= e(implode(' · ', array_slice($lsProblems, 0, 5))) ?></div>
<?php endif; ?>
<?php if ($lsOne === null && $lsRows !== []):
    // LIVE SALARY DASHBOARD (owner, 23 Oct): headcount and money so far, then the same split by company,
    // branch and department. Built from the rows below, so the cards and the table always agree.
    $lsMinor = static function ($money): int {
        $d = (string) $money->toDecimalString();
        $neg = str_starts_with($d, '-');
        [$i, $f] = array_pad(explode('.', ltrim($d, '-')), 2, '0');
        $m = (int) $i * 100 + (int) substr($f . '00', 0, 2);
        return $neg ? -$m : $m;
    };
    $lsFmt = static fn (int $m): string => SmartPRS\Platform\Support\Money::ofMinor($m)->format();
    $lsTot = ['n' => 0, 'gross' => 0, 'ded' => 0, 'net' => 0];
    $lsBy = ['company' => [], 'branch' => [], 'department' => []];
    $lsCoOf = [];
    foreach ($lsRows as $lsR) {
        $g = $lsMinor($lsR['slip']->grossEarnings()); $dd = $lsMinor($lsR['slip']->totalDeductions()); $nn = $lsMinor($lsR['slip']->netPay());
        $lsTot['n']++; $lsTot['gross'] += $g; $lsTot['ded'] += $dd; $lsTot['net'] += $nn;
        $co = orgValueOf($store, $lsR['e'], 'company') ?: 'No company';
        foreach (['company', 'branch', 'department'] as $k) {
            $v = $k === 'company' ? $co : (orgValueOf($store, $lsR['e'], $k) ?: 'Not set');
            $lsBy[$k][$v]['n'] = ($lsBy[$k][$v]['n'] ?? 0) + 1;
            $lsBy[$k][$v]['gross'] = ($lsBy[$k][$v]['gross'] ?? 0) + $g;
            $lsBy[$k][$v]['net'] = ($lsBy[$k][$v]['net'] ?? 0) + $nn;
            $k === 'branch' && $lsCoOf[$v] ??= $co;
        }
    }
    foreach ($lsBy as &$lsGrp) { uksort($lsGrp, 'strnatcasecmp'); } unset($lsGrp);
    $lsCoColor = [];
    foreach (array_keys($lsBy['company']) as $co) { $lsCoColor[$co] = $co === 'No company' ? 'var(--text3)' : companyColor($store, $co); }
    $lsSplit = static fn (string $metric): array => array_map(static fn (array $v): int => (int) $v[$metric], $lsBy['company']);
    $lsCards = [
        ['fa-users', 'Employees', number_format($lsTot['n']), $lsSplit('n'), 'var(--accent)', static fn (int $v): string => number_format($v)],
