  <script>
  function lsXlsx(){
    var t=document.getElementById('ls-table'); if(!t){return;}
    var csv=[].map.call(t.rows,function(r){return [].slice.call(r.cells,0,r.cells.length-1).map(function(c){return '"'+c.innerText.replace(/\s*\n\s*/g,' ').trim().replace(/"/g,'""')+'"';}).join(',');}).join('\r\n');
    var f=document.createElement('form'); f.method='post'; f.action='?r=live-salary';
    [['csrf',<?= json_encode((string) $session->token()) ?>],['action','csv-xlsx'],['name','live-salary-<?= e(date('d-m-Y')) ?>.csv'],['csv',csv]].forEach(function(kv){var i=document.createElement('input');i.type='hidden';i.name=kv[0];i.value=kv[1];f.appendChild(i);});
    document.body.appendChild(f); f.submit(); f.remove();
  }
  </script>
