<?php elseif ($route === 'ai-assistant'): ?>
<?php
    $aiQ = trim((string) ($_GET['q'] ?? ''));
    $aiVisible = $scope->only($store->all('employees'), $may('employee.list'));
    $aiOwn = $scope->own() === null ? null : $store->find('employees', (string) $scope->own());
    $aiToday = date('Y-m-d');
    $aiLink = static fn (string $label, string $href): array => ['label' => $label, 'href' => $href];
    $aiMuster = static fn (): array => $attendanceReport->muster($aiVisible, $aiToday, $aiToday, $calendar->shiftStart(), $calendar->shiftEnd(), $aiToday);
    $aiNames = static fn (array $rows): string => $rows === [] ? 'nobody' : implode(', ', array_map(static fn (array $r): string => $r['code'] . ' ' . $r['name'], array_slice($rows, 0, 25))) . (count($rows) > 25 ? ' and ' . (count($rows) - 25) . ' more' : '');
    $aiHandlers = [
        'absent_today' => static function () use ($aiMuster, $aiToday, $aiNames, $aiLink, $may): array {
            if (!$may('attendance.day.view')) { return ['answer' => 'You may not read attendance.']; }
            $rows = array_values(array_filter($aiMuster()['rows'], static fn (array $r): bool => ($r['cells'][$aiToday]['status'] ?? '') === 'ABSENT'));
            return ['answer' => count($rows) . ' absent today (' . $aiToday . ': no punch and no leave, by the published rules): ' . $aiNames($rows) . '.',
                'links' => [$aiLink('Daily attendance', '?r=daily-attendance'), $aiLink('Absence alerts', '?r=absence')]];
        },
        'on_leave_today' => static function () use ($aiMuster, $aiToday, $aiNames, $aiLink, $may): array {
            if (!$may('attendance.day.view')) { return ['answer' => 'You may not read attendance.']; }
            $rows = array_values(array_filter($aiMuster()['rows'], static fn (array $r): bool => in_array($r['cells'][$aiToday]['status'] ?? '', AttendanceReport::LEAVE_STATUSES, true)));
            return ['answer' => count($rows) . ' on approved leave today: ' . $aiNames($rows) . '.', 'links' => [$aiLink('Leave', '?r=leave')]];
        },
        'my_leave_balance' => static function () use ($aiOwn, $leave, $policy, $aiLink, $store): array {
            if ($aiOwn === null) { return ['answer' => 'Your account is not linked to an employee, so there is no balance to read.']; }
            $parts = [];
            foreach ($policy->typesFor(leaveScopeContext($store, $aiOwn)) as $t) {
                $code = (string) ($t['code'] ?? '');
                if ($code === '') { continue; }
                try {
                    $parts[] = $code . ' ' . $leave->balance((string) $aiOwn['id'], $code, new \DateTimeImmutable())->toDecimalString(1);
                } catch (\Throwable) {
                    // gate:allow-swallow a type with no ledger opened for this employee has no balance to print
                }
            }
            return ['answer' => 'Your balances as of today: ' . ($parts === [] ? 'no ledger opened yet' : implode(', ', $parts)) . '.', 'links' => [$aiLink('Leave', '?r=leave')]];
        },
        'pending_approvals' => static function () use ($requests, $modules, $may, $session, $aiLink): array {
            $me = (string) ($session->user()['id'] ?? ''); $mine = 0; $raised = 0;
            foreach ($requests->open() as $r) {
                if ((string) $r['raised_by_id'] === $me) { $raised++; continue; }
                $wf = $requests->workflow((string) $r['workflow']);
                $gate = $wf === null ? ['permission' => null] : $requests->permissionFor($wf, $modules);
                if ($gate['permission'] !== null && $may($gate['permission'])) { $mine++; }
            }
            return ['answer' => $mine . ' request(s) wait on you; ' . $raised . ' you raised wait on somebody else.', 'links' => [$aiLink('Approvals inbox', '?r=inbox')]];
        },
        'overdue_approvals' => static function () use ($sla, $may, $aiLink): array {
            if (!$may('request.view')) { return ['answer' => 'You may not read the request queue.']; }
            $c = $sla->review(new \DateTimeImmutable())['counts'];
            return ['answer' => $c['breached'] . ' approval(s) past their due-within, ' . $c['within'] . ' within it, ' . $c['no_deadline'] . ' with no deadline declared.', 'links' => [$aiLink('Escalation desk', '?r=escalation-desk')]];
        },
        'headcount' => static function () use ($aiVisible, $may, $aiLink): array {
            $by = [];
            foreach ($aiVisible as $e) { $k = trim((string) ($e['branch'] ?? '')) ?: '(no branch)'; $by[$k] = ($by[$k] ?? 0) + 1; }
            ksort($by);
            return ['answer' => count($aiVisible) . ' employee(s)' . ($may('employee.list') ? ' in your scope' : ' (your own)') . ': ' . implode(', ', array_map(static fn ($k, $v): string => "$k $v", array_keys($by), $by)) . '.', 'links' => [$aiLink('Directory', '?r=employees')]];
        },
        'find_employee' => static function (string $q) use ($aiVisible, $aiLink): array {
            $needle = strtolower(Assistant::subjectOf($q));
            $hits = array_values(array_filter($aiVisible, static fn (array $e): bool => $needle !== '' && (str_contains(strtolower(Employment::code($e)), $needle) || str_contains(strtolower((string) $e['name']), $needle))));
            if ($hits === []) { return ['answer' => "Nobody in your scope matches '{$needle}'."]; }
            $e = $hits[0];
            $d = array_filter(['designation' => (string) ($e['designation'] ?? ''), 'department' => (string) ($e['department'] ?? ''), 'branch' => (string) ($e['branch'] ?? ''), 'joined' => Employment::joinedOn($e)]);
            return ['answer' => Employment::code($e) . ' ' . $e['name'] . ' — ' . implode(', ', array_map(static fn ($k, $v): string => "$k $v", array_keys($d), $d)) . (count($hits) > 1 ? '. ' . (count($hits) - 1) . ' other match(es).' : '.'),
                'links' => [$aiLink('Open record', '?r=me&id=' . rawurlencode((string) $e['id']))]];
        },
        'probation_ending' => static function () use ($probation, $aiVisible, $aiToday, $aiLink): array {
            $board = $probation->board($aiVisible, $aiToday)['rows'];
            $soon = array_values(array_filter($board, static fn (array $r): bool => (string) ($r['end'] ?? '') !== '' && $r['end'] <= date('Y-m-d', strtotime('+30 days'))));
            return ['answer' => count($board) . ' on probation; ' . count($soon) . ' end within 30 days: ' . ($soon === [] ? 'none' : implode(', ', array_map(static fn (array $r): string => $r['code'] . ' (' . $r['end'] . ')', array_slice($soon, 0, 20)))) . '.', 'links' => [$aiLink('Probation', '?r=probation')]];
        },
        'transfers_pending' => static function () use ($transfers, $aiVisible, $aiLink): array {
            $ids = array_flip(array_map(static fn (array $e): string => (string) $e['id'], $aiVisible));
            $p = array_filter($transfers->all(Transfers::PENDING), static fn (array $t): bool => isset($ids[(string) $t['employee_id']]));
            $a = array_filter($transfers->all(Transfers::APPROVED), static fn (array $t): bool => isset($ids[(string) $t['employee_id']]));
            return ['answer' => count($p) . ' transfer(s) pending a decision, ' . count($a) . ' approved and waiting for their effective date.', 'links' => [$aiLink('Transfers', '?r=transfers')]];
        },
        'my_salary' => static fn (): array => ['answer' => 'Your running-month figure is on Live Salary — computed from your settled attendance so far, through the payroll engine.', 'links' => [$aiLink('Live salary', '?r=live-salary')]],
        'open_screen' => static function (string $q) use ($navigation, $may, $aiLink): array {
            $needle = strtolower(preg_replace('/^(open|go to|where is|show me|take me to|navigate to|how do i)\s+(the\s+)?/i', '', trim($q, " ?.!")) ?? '');
            $hits = [];
            foreach ($navigation->forViewer($may) as $sec) {
                foreach ($sec['items'] as $it) {
                    if ($needle !== '' && (str_contains(strtolower((string) $it['label']), $needle) || str_contains($needle, strtolower((string) $it['label'])))) {
                        $hits[] = $aiLink($sec['label'] . ' → ' . $it['label'], (string) $it['href']);
                    }
                }
            }
            return $hits === [] ? ['answer' => "No screen is called '{$needle}'. The full map is on How It Works.", 'links' => [$aiLink('How it works', '?r=how-it-works')]]
                : ['answer' => count($hits) . ' screen(s) match:', 'links' => $hits];
        },
        'help' => static fn (): array => ['answer' => 'I answer these, from this company\'s own records and within your permissions: ' . implode('; ', array_map(static fn (array $i): string => (string) $i['example'], $assistant->intents())) . '.'],
    ];
    $aiResult = $aiQ === '' ? null : $assistant->answer($aiQ, $aiHandlers);
?>
