<?php endforeach; ?>
      </tbody>
    </table>
    </div>
<?php if ($may((string) $wf['raise_permission'])): ?>
    <form method="post" style="margin-top:12px">
      <input type="hidden" name="csrf" value="<?= e($session->token()) ?>">
      <input type="hidden" name="action" value="raise-request">
      <input type="hidden" name="workflow" value="<?= e((string) $wf['key']) ?>">
      <div class="row">
        <div><label for="a_<?= e((string) $wf['key']) ?>"><?= isset($wf['amount_field'])
          ? e(ucfirst((string) $wf['amount_field'])) : 'Amount' ?></label>
          <input id="a_<?= e((string) $wf['key']) ?>" name="amount" type="number" step="0.01" value="0"></div>
        <div style="flex:3"><label for="n_<?= e((string) $wf['key']) ?>">What it is for</label>
          <input id="n_<?= e((string) $wf['key']) ?>" name="note"
            placeholder="Three days for a family function"></div>
