<?php foreach (array_slice($history, 0, 40) as $r): ?>
<?php $wf = $requests->workflow((string) $r['workflow']); ?>
      <tr>
        <td><?= e((string) ($wf['label'] ?? $r['workflow'])) ?>
          <span class="note"><?= e((string) $r['note']) ?></span></td>
        <td><?= e((string) $r['raised_by']) ?></td>
