<?php endif; ?>
<?php endif; ?>
<?php endif; ?>

<?php endif; ?>
<?php elseif ($route === 'dashboard'): ?>
<?php
    // Every figure here is produced by a REPORT, run through the same engine the
    // reports screen uses. SmartPRS 2's dashboard runs its own queries, so its
    // headcount and its report screen's headcount are two answers to one
    // question — and when they disagree, which they eventually do, neither can be
    // traced. Which tiles, and which report feeds each, is `config/dashboard.json`.
    // COMPANY-WIDE FIGURES FOR COMPANY-WIDE ROLES ONLY (28 Sep): an employee or
    // a manager reading their own line does not get the whole company's
    // headcount, cost and leave totals — the reports behind these tiles are
    // not narrowed to a reporting line.
    $dashAll = $scope->seesEveryone($may('employee.list'));
    $kpis = $dashAll ? $dashboard->kpis($may) : [];
    // TODAY'S ATTENDANCE (owner, 22 Oct 2026): Present (punched today), On leave (approved), Absent (neither).
    // Same muster as the Attendance Report, so the tiles and the report agree. An employee whose day is a
    // holiday or weekly off is not counted; when that is everyone, the three tiles show "-" (not 0).
    $dashDay = null;
    if ($dashAll && $may('attendance.day.view')) {
        try {
            $dashToday = date('Y-m-d');
            $dashPeople = array_values(array_filter(liveRows($store, 'employees'), static fn (array $e): bool => strtolower(trim((string) ($e['status'] ?? 'active'))) === 'active'));
            $dashDay = ['present' => 0, 'leave' => 0, 'absent' => 0, 'off' => 0, 'counted' => 0];
            foreach ($attendanceReport->muster($dashPeople, $dashToday, $dashToday, $calendar->shiftStart(), $calendar->shiftEnd(), $dashToday)['rows'] as $dashR) {
                $dashC = $dashR['cells'][$dashToday] ?? null;
                if ($dashC === null || $dashC['status'] === AttendanceReport::NOT_JOINED) { continue; }
                $dashSt = (string) $dashC['status'];
                if ($dashSt === AttendanceReport::NOT_YET) { // shift still under way: is today an off day for them?
                    $dashSt = (string) ($attendance->dayWithoutPunches($dashR['code'], $dashToday, $calendar->shiftStart(), $calendar->shiftEnd())['classification']['status'] ?? '');
                }
                if (in_array($dashSt, ['HOLIDAY', 'WEEKLY_OFF'], true) && (int) ($dashC['punches'] ?? 0) === 0) { $dashDay['off']++; continue; }
                $dashDay['counted']++;
                if (in_array($dashSt, AttendanceReport::LEAVE_STATUSES, true)) { $dashDay['leave']++; }
                elseif ((int) ($dashC['punches'] ?? 0) > 0) { $dashDay['present']++; }
                else { $dashDay['absent']++; }
            }
        } catch (\Throwable $e) {
            $dashDay = ['error' => $e->getMessage()];
        }
    }
    $panels = $dashAll ? $dashboard->panels($may) : [];
    $tint = ['orange' => 'var(--accent)', 'green' => 'var(--green)', 'blue' => 'var(--blue)',
        'amber' => 'var(--amber)', 'red' => 'var(--red)', 'purple' => 'var(--purple)'];
    // THE DASHBOARD'S OWN PROFESSIONAL PALETTE (owner, 24 Oct 2026): donut slices, legend dots and bars use a
    // muted navy / steel / teal / gold / slate / sage set (css .dash-panels --dp1…--dp6), not the theme's brights.
    $dashPal = ['var(--dp1)', 'var(--dp2)', 'var(--dp3)', 'var(--dp4)', 'var(--dp5)', 'var(--dp6)'];
    // TAKES THE REPORT'S OWN ANSWER, not a float made from it. Reports return an
    // exact decimal string for a money measure and an int for a count; routing that
    // through a float to reformat it undoes the exactness one line before display,
    // which is where a rupee total quietly becomes ...99 in front of a customer.
    $rupees = static fn (int|string $v): string
        => \SmartPRS\Platform\Support\Money::of((string) $v)->format();
?>
  <div class="page-header">
    <div>
      <h2>Welcome back, <?= e(explode('@', (string) $session->user()['email'])[0]) ?></h2>
      <p><?= e($company) ?> &middot; <?= e(date('l, d-m-Y')) ?></p>
    </div>
  </div>

<?php // LETTERS WAITING FOR YOUR ACKNOWLEDGEMENT (owner, 23 Oct).
      $dashAck = $scope->own() === null ? 0 : count(letterPendingAcks((string) $scope->own()));
      if ($dashAck > 0): ?>
  <div class="card" style="border-left:4px solid var(--red)"><b><i class="fas fa-signature" style="color:var(--red)"></i> <?= $dashAck ?> letter(s) waiting for your acknowledgement.</b>
    <a class="btn btn-sm btn-primary" style="margin-left:10px" href="?r=letters-mine">Open My Letters</a></div>
<?php endif; ?>
<?php if (!$dashAll): ?>
  <div class="card"><p class="note" style="margin:0">Company-wide figures are shown to company-wide roles. Your own
     attendance, leave and payslips are under <a href="?r=me">My Space</a><?= $scope->leadsTeam() ? ', and your team\'s under Leave Approvals and Attendance' : '' ?>.</p></div>
<?php endif; ?>
  <div class="kpi-strip dash-kpis">
<?php foreach ($kpis as $kpi): $kt = (string) ($kpi['tint'] ?? 'orange'); ?>
    <div class="kpi dk <?= e($kt) ?>">
      <div class="dk-top"><span class="dk-ic"><i class="fas <?= e((string) ($kpi['icon'] ?? 'fa-chart-simple')) ?>"></i></span><span class="dk-label"><?= e((string) $kpi['label']) ?></span></div>
<?php if ($kpi['locked']): ?>
      <div class="dk-val" style="color:var(--text3)"><i class="fas fa-lock" style="font-size:22px"></i></div>
      <div class="dk-foot"><span>not yours to see</span></div>
<?php elseif ($kpi['value'] === null): ?>
      <div class="dk-val" style="color:var(--red)">—</div>
      <div class="dk-foot" style="color:var(--red)"><span>no figure</span></div>
<?php else: ?>
      <div class="dk-val"><?= $kpi['money'] ? e($rupees($kpi['value'])) : number_format((float) $kpi['value']) ?></div>
      <div class="dk-foot"><span><?= e((string) ($kpi['sub'] ?? '')) ?></span></div>
<?php endif; ?>
    </div>
<?php endforeach; ?>
<?php if ($dashDay !== null): $dashHoliday = !isset($dashDay['error']) && $dashDay['counted'] === 0; ?>
<?php foreach ([['present', 'Present today', 'green', 'punched in today', 'daily-attendance', 'fa-fingerprint'], ['leave', 'On leave', 'blue', 'approved leave today', 'on-leave-today', 'fa-umbrella-beach'], ['absent', 'Absent', 'red', 'no punch, no approved leave', 'daily-attendance', 'fa-user-xmark']] as [$dk, $dl, $dt, $ds, $dr, $di]): ?>
    <a class="kpi dk <?= $dt ?>" href="?r=<?= $dr ?>">
      <div class="dk-top"><span class="dk-ic"><i class="fas <?= $di ?>"></i></span><span class="dk-label"><?= e($dl) ?></span></div>
      <div class="dk-val"><?= isset($dashDay['error']) ? '<span style="color:var(--red)">—</span>' : ($dashHoliday ? '-' : number_format((int) $dashDay[$dk])) ?></div>
      <div class="dk-foot"><span><?= e(isset($dashDay['error']) ? 'no figure' : ($dashHoliday ? 'holiday / weekly off today' : $ds)) ?></span><i class="fas fa-arrow-right"></i></div>
    </a>
<?php endforeach; ?>
<?php endif; ?>
  </div>
<?php if (isset($dashDay['error'])): ?><div class="problem"><b>Today's attendance could not be read.</b> <?= e((string) $dashDay['error']) ?></div><?php endif; ?>

<?php $broken = array_values(array_filter($kpis, static fn (array $k): bool
    => !$k['locked'] && $k['value'] === null)); ?>
<?php if ($broken !== []): ?>
  <div class="problem"><b><?= count($broken) ?> tile(s) have no figure to show.</b>
    <?= e((string) $broken[0]['why']) ?></div>
<?php endif; ?>

  <div class="dash-grid dash-panels">
<?php foreach ($panels as $panel): ?>
    <div class="card dp-<?= e((string) ($panel['width'] ?? 'narrow')) ?>" style="padding:0">
      <div class="card-header">
        <div>
          <h3 style="font-size:15px;font-weight:700"><?= e((string) $panel['label']) ?></h3>
          <p class="note" style="margin:0"><?= e((string) ($panel['question'] ?? '')) ?></p>
        </div>
        <div class="actions">
          <a href="?r=reports&amp;k=<?= e((string) $panel['report']) ?>" class="btn btn-sm"
            >Open the report <i class="fas fa-arrow-right"></i></a>
        </div>
      </div>
      <div style="padding:18px 22px">
<?php if ($panel['locked'] || ($panel['why'] ?? null) !== null): ?>
        <p class="note"><i class="fas fa-lock"></i> <?= e((string) $panel['why']) ?></p>
<?php elseif ($panel['rows'] === []): ?>
        <p class="note">Nothing recorded yet. That is an empty result, not a failure &mdash;
           <?= (int) ($panel['counted'] ?? 0) ?> row(s) were read.</p>
<?php elseif ($panel['money']): ?>
<?php // A BAR WIDTH, not money. The proportion a bar fills is a picture, and a
      // picture is allowed to be approximate — the FIGURE beside it is not, and it
      // is printed from the exact value.
      $top = max(array_map(static fn (array $r): float => (float) $r['value'], $panel['rows'])); ?>
<?php foreach (array_slice($panel['rows'], 0, 6) as $i => $row): ?>
        <div style="margin-bottom:14px">
          <div style="display:flex;justify-content:space-between;font-size:13px;
            font-family:var(--font2);margin-bottom:4px">
            <span style="font-weight:600"><?= e((string) $row['label']) ?></span>
            <span class="dash-val"><?= e($rupees($row['value'])) ?>
              <span class="dash-rows">&middot; <?= (int) $row['rows'] ?> row(s)</span></span>
          </div>
          <div class="progress-bar"><div class="progress-fill" style="width:<?=
            $top > 0 ? round((float) $row['value'] / $top * 100) : 0 ?>%;background:<?=
            e($dashPal[$i % count($dashPal)]) ?>"></div></div>
        </div>
<?php endforeach; ?>
<?php if (count($panel['rows']) > 6): ?>
        <p class="note">and <?= count($panel['rows']) - 6 ?> more on the report.</p>
<?php endif; ?>
<?php else: ?>
<?php // A DONUT SLICE, not a count. A category split reads faster as proportion of
      // a whole than as six separate bars — the FIGURE in the legend is still the
      // exact value. Slices are shares of the rows shown here, not of every row the
      // report has (ponytail: fine up to the 6 shown; the "+N more" note below still
      // says what is left off, same as the bar view did).
      $shown = array_slice($panel['rows'], 0, 6);
      $sliceTotal = array_sum(array_map(static fn (array $r): float => (float) $r['value'], $shown));
      $stops = []; $cursor = 0.0;
      foreach ($shown as $i => $row) {
          $share = $sliceTotal > 0 ? (float) $row['value'] / $sliceTotal * 100 : 0;
          $end = $sliceTotal > 0 ? $cursor + $share : 100;
          $stops[] = e($dashPal[$i % count($dashPal)]) . " {$cursor}% {$end}%";
          $cursor = $end;
      }
      if ($stops === []) { $stops[] = 'var(--border) 0% 100%'; }
?>
      <div style="display:flex;align-items:center;gap:22px;flex-wrap:wrap">
        <div class="donut" style="background:conic-gradient(<?= implode(',', $stops) ?>)">
          <div class="donut-hole"><span><?= number_format($sliceTotal) ?></span></div>
        </div>
