      <tr><th>Report</th><th>The question it answers</th><th>From</th></tr>
<?php foreach ($inGroup as $r): ?>
<?php $gate = $allowed($r); ?>
      <tr>
        <td><?= $gate['ok']
          ? '<a href="?r=reports&amp;k=' . e((string) $r['key']) . '"><b>'
