<?php elseif ($route === 'payslips-batch'): ?>
<?php
    // THE GRID A PAYROLL TEAM ACTUALLY WORKS FROM — one row per employee,
    // searchable, exportable, matching SmartPRS 2's Payslip Generator — with
    // the full one-page-per-employee PRINT COPY kept one click away
    // (&view=print) for whoever genuinely needs the whole month as a PDF.
    //
    // READ FROM THE CLOSED RUN, exactly like the single payslip: the same
    // Payslip::from() against the same stored run, so the grid, the print
    // view and the individual copy can never disagree. A second renderer for
    // "the printable version" is the second layout that always drifts, and
    // the day it drifts is the day an employee's filed copy stops matching
    // the register.
    $batchRuns = $register->runs(); // newest first
    // Defaults to the most recently closed run, like SmartPRS 2 — but a
    // ?period= of '' (the "— choose —" option, submitted deliberately) is
    // respected rather than overridden back to the latest.
    $batchPeriod = array_key_exists('period', $_GET)
        ? (string) $_GET['period'] : (string) ($batchRuns[0]['period'] ?? '');
    $batchRun = $batchPeriod === '' ? null : $register->find($batchPeriod);
    $batchRows = $batchRun === null ? [] : (array) ($batchRun['rows'] ?? []);
    $batchSlips = [];
    $batchRefused = [];
    $batchTotals = ['gross_minor' => 0, 'deductions_minor' => 0, 'net_minor' => 0];

    // ONLY THE ROWS THIS ACCOUNT MAY READ. This screen is the widest read in
    // the product — every salary in the tenant on one page — and it goes
    // through the same scope as every other list rather than trusting the
    // permission that opened the screen.
    $mayReadAll = $may('payroll.view');
    $visible = [];
    $batchFilter = orgFilter();
    $batchScoped = $scope->only($store->all('employees'), $mayReadAll);
    $batchOptions = orgFilterOptions($store, $batchScoped);
    $batchLookups = employeeLookups($store);
    $batchEmployeeOf = [];

    foreach ($batchScoped as $candidate) {
        $batchEmployeeOf[Employment::code($candidate)] = $candidate;
    }

    foreach (orgFilterApply($store, $batchScoped, $batchFilter) as $candidate) {
        $visible[Employment::code($candidate)] = true;
    }

    foreach (array_keys($batchRows) as $rowCode) {
        if (!isset($visible[(string) $rowCode])) {
            continue;
        }

        $one = Payslip::from($batchRun, $batchPeriod, (string) $rowCode);

        if (!$one['ok']) {
            // NAMED, NOT DROPPED. A batch that silently counts 397 of 400 is a
            // batch nobody counts, and the three missing are the three somebody
            // asks about in March.
            $batchRefused[(string) $rowCode] = (string) $one['why'];

            continue;
        }

        // gross/deductions AS MINOR UNITS, summed from this slip's own lines —
        // not reparsed off the formatted "₹..." strings — so the stat cards
        // below add up to the paisa against what each payslip states.
        $slip = $one['slip'];
        $slip['gross_minor'] = array_sum(array_column($slip['earnings'], 'minor'));
        $slip['deductions_minor'] = array_sum(array_column($slip['deductions'], 'minor'));
        $employeeRow = $batchEmployeeOf[$slip['code']] ?? null;
        $slip['company'] = $employeeRow !== null
            ? (string) ($batchLookups['companies'][(string) ($employeeRow['employer_company_id'] ?? '')] ?? '')
            : '';
        $batchTotals['gross_minor'] += $slip['gross_minor'];
        $batchTotals['deductions_minor'] += $slip['deductions_minor'];
        $batchTotals['net_minor'] += $slip['net_minor'];
        $batchSlips[] = $slip;
    }

    $batchView = ($_GET['view'] ?? '') === 'print' ? 'print' : 'grid';
    $batchQuery = '&period=' . urlencode($batchPeriod);

    foreach ($batchFilter as $qf => $qv) {
        if ($qv !== '') {
            $batchQuery .= '&f_' . $qf . '=' . urlencode($qv);
        }
    }
?>
  <div class="page-header no-print">
    <div><h2>Payslips</h2>
