        foreach ($batchOptions[$bf] ?? [] as $bo): ?><option<?= strcasecmp((string) $bo, $batchFilter[$bf]) === 0 ? ' selected' : '' ?>><?= e((string) $bo) ?></option><?php endforeach; ?></select></div>
