<?php else: ?>
<?php foreach ($batchSlips as $one): ?>
<?php
    // THE SAME SCOPED FORMAT THE SINGLE PAYSLIP SCREEN RESOLVES — filtered
    // here too now, so the batch printout can never show a component the
    // employee's own payslip screen would hide, or vice versa.
    $printFormat = null;
    $printEmployee = $batchEmployeeOf[$one['code']] ?? null;
    // AS CLOSED (28 Sep) — same as the single payslip.
    $printEmployee !== null && $printEmployee = array_merge($printEmployee, (array) ((($batchRun ?? [])['rows'] ?? [])[$one['code']]['as_closed'] ?? []));

    if ($printEmployee !== null) {
        $printFormat = $payslipFormats->forContext(payslipFormatContextFor($store, $batchLookups, $printEmployee));
    }

    $printEarnings = payslipLines((array) $one['earnings'], $printFormat);
    $printDeductions = payslipLines((array) $one['deductions'], $printFormat);

    // THE EMPLOYER'S OWN LOGO AND COLOUR, same lookup and same fallback as the
    // single payslip screen (see the block below `route === 'payslip'`) — a
    // batch of 400 is 400 documents, each still that employee's own company's
    // document, not a generic "SmartPRS" one.
    $printCompanyRow = $printEmployee !== null
        ? $store->find('companies', (string) ($printEmployee['employer_company_id'] ?? ''))
        : null;
    $printCompanyColor = trim((string) ($printCompanyRow['color'] ?? ''));
    $printCompanyColorOk = preg_match('/^#[0-9A-Fa-f]{6}$/', $printCompanyColor) === 1;
    $printCompanyLogo = trim((string) ($printCompanyRow['logo_path'] ?? ''));
    $printCompanyName = trim((string) ($printCompanyRow['legal_name'] ?? ''))
        ?: trim((string) ($printCompanyRow['name'] ?? ''))
        ?: ($one['company'] !== '' ? $one['company'] : $company);
?>
  <div class="card payslip-sheet" style="padding:0">
    <div class="card-header" style="background:<?= $printCompanyColorOk ? e($printCompanyColor) : 'var(--navy)' ?>;color:#fff;border-radius:14px 14px 0 0">
      <div style="display:flex;align-items:center;gap:10px">
<?php if ($printCompanyLogo !== '' && ($printFormat['show_logo'] ?? true)): ?>
        <img src="<?= e($printCompanyLogo) ?>" alt="" style="width:34px;height:34px;object-fit:contain;border-radius:6px;background:#fff;padding:2px">
<?php endif; ?>
        <div>
          <h3 style="font-size:16px;font-weight:800;color:#fff"><?= e($printCompanyName) ?></h3>
          <p style="font-size:12px;color:rgba(255,255,255,.6);margin:0">Payslip</p>
        </div>
      </div>
      <div class="actions"><span class="badge badge-gray"><?= e($batchPeriod) ?></span></div>
    </div>
    <div style="padding:20px 22px;border-bottom:1px solid var(--border)">
      <div class="row" style="margin:0">
        <div><span class="note">Employee</span><br><b><?= e((string) $one['name']) ?></b></div>
        <div><span class="note">Code</span><br><code><?= e((string) $one['code']) ?></code></div>
        <div><span class="note">Days paid</span><br><b><?= e((string) $one['payable_days']) ?></b>
          <span class="note">of <?= (int) $one['period_days'] ?></span>
<?php if (($psDays = payDaysBreakdown((array) ($one['days'] ?? []))) !== ''): ?><div class="note" style="font-size:11.5px"><?= e($psDays) ?></div><?php endif; ?></div>
        <div><span class="note">Status</span><br><?= $one['approved']
          ? '<span class="badge badge-green">approved</span>'
          : '<span class="badge badge-amber">draft &mdash; not approved</span>' ?></div>
      </div>
    </div>
    <div class="table-wrap">
    <table>
      <thead><tr><th>Component</th><th class="n">Amount</th></tr></thead>
      <tbody>
<?php foreach ($printEarnings['lines'] as $line): ?>
      <tr><td><?= e((string) ($line['label'] ?? $line['code'] ?? '')) ?></td>
          <td class="n"><?= e((string) ($line['amount'] ?? '')) ?></td></tr>
<?php endforeach; ?>
      <tr><td><b>Gross earnings</b></td>
          <td class="n"><b><?= e((string) $one['earnings_total']) ?></b></td></tr>
<?php foreach ($printDeductions['lines'] as $line): ?>
      <tr><td><?= e((string) ($line['label'] ?? $line['code'] ?? '')) ?></td>
          <td class="n">&minus; <?= e((string) ($line['amount'] ?? '')) ?></td></tr>
<?php endforeach; ?>
      <tr><td><b>Net pay</b></td><td class="n"><b><?= e((string) $one['net']) ?></b></td></tr>
<?php if (($one['employer'] ?? []) !== []): ?>
      <?php // BELOW THE NET, NEVER ABOVE IT AND NEVER SUBTRACTED. The company's
            // own contributions are the employee's to know about and nobody's to
            // deduct; printing them among the deductions (which is what this did)
            // made the lines disagree with the total. ?>
      <tr><td colspan="2" style="padding-top:14px"><span class="note">Paid by the company on your
          behalf &mdash; not deducted from your pay</span></td></tr>
<?php foreach ((array) $one['employer'] as $line): ?>
      <tr><td class="note"><?= e($componentRules->labelFor((string) $line['code'])) ?></td>
          <td class="n note"><?= e((string) $line['amount']) ?></td></tr>
<?php endforeach; ?>
      <tr><td class="note"><b>Total paid by the company</b></td>
          <td class="n note"><b><?= e((string) $one['employer_total']) ?></b></td></tr>
      <tr><td class="note"><b>Cost to the company</b> <span class="note">gross + the above</span></td>
          <td class="n note"><b><?= e((string) $one['company_cost']) ?></b></td></tr>
<?php endif; ?>
      </tbody>
    </table>
    </div>
<?php if (((int) ($printEarnings['hidden'] ?? 0) + (int) ($printDeductions['hidden'] ?? 0)) > 0): ?>
    <p class="note" style="padding:0 22px;margin:0"><?= (int) $printEarnings['hidden'] + (int) $printDeductions['hidden'] ?>
      component(s) are not on this employee's payslip format and are omitted above &mdash; still in
      the totals, never in the printed list.</p>
<?php endif; ?>
    <p class="note" style="padding:14px 22px 18px;margin:0"><b><?= e((string) $one['net_in_words']) ?></b>
      &middot; Read from the closed run for <?= e($batchPeriod) ?>, never recomputed &mdash; the copy
      issued and the copy on file are the same document.</p>
  </div>
<?php endforeach; ?>
<?php endif; ?>

<?php elseif ($route === 'payslip'): ?>
<?php
    $code = (string) ($_GET['code'] ?? '');
    // WHOSE PAYSLIP (owner, 28 Sep): a code typed into the address bar opens
    // only a payslip of somebody in this account's reach.
    if ($code !== '' && !$scope->covers((string) (employmentIdFor($store, $code) ?? ''), $may('employee.list'))) {
        $problem = $scope->why((string) (employmentIdFor($store, $code) ?? ''));
        $code = '';
    }
    $slipPeriod = (string) ($_GET['period'] ?? '');
    $available = $code === '' ? [] : Payslip::periodsIn($register->runs(), $code);
    $slipPeriod = $slipPeriod === '' ? (string) ($available[0] ?? '') : $slipPeriod;
    $result = $code === '' || $slipPeriod === ''
        ? null
        : Payslip::from($register->find($slipPeriod), $slipPeriod, $code);
    $slip = $result !== null && $result['ok'] ? $result['slip'] : null;
    $people = [];

    // A PICKER IS A LIST. Every one of these enumerated every employee in the
    // tenant — name and code, handed over — while the screen behind it refused a
    // colleague's row. The refusal was worth nothing with the directory printed
    // above it, and a scope sweep found all three the same way: the leak was
    // there whatever the parameter said, because it was not the parameter
    // leaking. `Scope::only()` narrows the list to the rows this account may
    // read, and returns it untouched for somebody who may read others.
    foreach ($scope->only($store->all('employees'), $may('payroll.view')) as $candidate) {
        $people[Employment::code($candidate)] = Employment::label($candidate);
    }

    ksort($people);

    // WHICH FORMAT THIS PERSON'S PAYSLIP IS PRINTED IN. Resolved from their own
    // company, branch, department, designation and code, by the same ladder the
    // salary component rules use — most specific wins, and a format that names a
    // branch does not apply to somebody in another one.
    $slipFormat = null;
    $slipFormatContext = [];

    $slipEmployeeLocation = '';

    if ($slip !== null) {
        $slipRow = null;

        foreach ($store->all('employees') as $candidate) {
            if (Employment::code($candidate) === $code) {
                $slipRow = $candidate;

                break;
            }
        }

        // AS CLOSED, NOT AS TODAY (28 Sep): the org and statutory identity the
        // run recorded for this person wins over their current record.
        $slipRow !== null && $slipRow = array_merge($slipRow, (array) (($register->find($slipPeriod)['rows'] ?? [])[$code]['as_closed'] ?? []));

        if ($slipRow !== null) {
            $slipLookups = employeeLookups($store);
            $slipFormatContext = payslipFormatContextFor($store, $slipLookups, $slipRow);
            $slipFormat = $payslipFormats->forContext($slipFormatContext);
            $slipEmployeeLocation = employeeLocationOf($slipLookups, $slipRow, $employeeExtras);
        }
    }

    // THE EMPLOYER'S OWN LOGO AND COLOUR — Organization Configuration → Companies
    // captures these per company precisely so a payslip prints as that company's
    // document, not SmartPRS's. Read here from the employee's actual employer row,
    // never from whichever company happens to theme the live application (that is
    // a single, separate, app-wide setting — see the Company Branding block).
    $slipCompanyRow = ($slipRow ?? null) !== null
        ? $store->find('companies', (string) ($slipRow['employer_company_id'] ?? ''))
        : null;
    $slipCompanyColor = trim((string) ($slipCompanyRow['color'] ?? ''));
    $slipCompanyColorOk = preg_match('/^#[0-9A-Fa-f]{6}$/', $slipCompanyColor) === 1;
    $slipCompanyLogo = trim((string) ($slipCompanyRow['logo_path'] ?? ''));
    $slipCompanyName = trim((string) ($slipCompanyRow['legal_name'] ?? ''))
