  // ONE PAGE (owner, 23 Oct): measure the sheet at A4 print width and shrink it to fit one page before printing.
  function psOnePagePrint(){
    var s=document.querySelector('.ps-one'); if(!s){return;}
    s.style.zoom=''; s.style.width='718px';            // 190mm at 96dpi
    var h=s.getBoundingClientRect().height, max=1040;   // 277mm usable height at 96dpi
    s.style.width=''; if(h>max){ s.style.zoom=(max/h).toFixed(3); }
    window.print(); setTimeout(function(){ s.style.zoom=''; }, 500);
  }
