<?php elseif ($route === 'compliance'): ?>
<?php
    // THE VIEWER'S SCOPE, like every other list: the checks run over the whole
    // tenant, and the rows shown (and counted) are the people this login may see —
    // an executive sees their own DRA date, a manager their team's, HR everybody's.
    $results = $compliance->runAll();
    $cwOwnerOf = static function (array $check, array $finding) use ($store): string {
        if ((string) $check['table'] === 'employees') {
            return (string) $finding['row_id'];
        }

        $row = $finding['row_id'] === '' ? null : $store->find((string) $check['table'], (string) $finding['row_id']);

        return (string) ($row[(string) ($check['subject_id'] ?? 'employee_id')] ?? '');
    };
    $cwChecks = [];

    foreach ($compliance->all() as $cwC) {
        $cwChecks[(string) $cwC['key']] = $cwC;
    }

    foreach ($results as &$cwR) {
        $cwCheck = $cwChecks[(string) $cwR['key']] ?? null;

        if ($cwCheck === null || !isset($cwR['findings'])) {
            continue;
        }

        $cwBefore = count($cwR['findings']);
        $cwR['findings'] = array_values(array_filter($cwR['findings'], static fn (array $f): bool => $scope->covers($cwOwnerOf($cwCheck, $f), $may('employee.list'))));

        if ($cwBefore !== count($cwR['findings'])) {
            // Counts follow the rows shown; what is hidden is still said out loud.
            $cwR['counts'] = array_fill_keys(array_keys((array) $cwR['counts']), 0);

            foreach ($cwR['findings'] as $f) {
                $cwR['counts'][$f['state']]++;
            }

            $cwR['hidden'] = $cwBefore - count($cwR['findings']);
        }
    }

    unset($cwR);
?>
  <div class="page-header"><div><h2>Compliance watch</h2>
    <p><?= e(Compliance::summary($results)) ?></p></div></div>
  <details class="why"><summary>Why a blank date is not &ldquo;compliant&rdquo;</summary>
    <p class="note">Four checks declared in <code>config/compliance.json</code>, each naming the
       table, the date column, how much warning is useful, and &mdash; in words &mdash; what it
       stops. A screen that reports a date without saying what the date prevents is a list nobody
       acts on.</p>
    <p class="note"><b>A row with no date recorded is reported as its own state, never as
       compliant.</b> Every compliance screen in every HR system reports two numbers, in date and
       expired, and a row with no date falls into neither &mdash; so it is silently counted as fine.
       An agency with two hundred agents and forty blank DRA dates reads &ldquo;160 in date, 0
       expired&rdquo; and believes it. The forty are what the audit finds.</p>
    <p class="note">Nothing here enforces anything. Refusing an allocation belongs at the point of
       the act, not on a dashboard &mdash; and a screen whose existence persuades people they are
       covered is worse than no screen.</p>
  </details>

<?php foreach ($results as $result): ?>
  <div class="card">
    <h2><?= e((string) $result['label']) ?>
      <span class="note"><?= e((string) $result['group']) ?> &middot;
        <?= (int) $result['lead_days'] ?> days' warning<?php
        if ($result['customised'] ?? false): ?> &middot; yours<?php endif; ?></span></h2>
<?php if ($result['error'] !== null): ?>
    <div class="problem"><b>This check did not run.</b> <?= e((string) $result['error']) ?></div>
<?php else: ?>
    <div class="row" style="gap:26px;margin-bottom:12px">
      <div><span class="note">Lapsed</span><br><b style="font-size:22px;color:var(--no)"><?=
        (int) $result['counts'][Compliance::LAPSED] ?></b></div>
      <div><span class="note">Expiring soon</span><br><b style="font-size:22px;color:var(--gold)"><?=
        (int) $result['counts'][Compliance::DUE] ?></b></div>
      <div><span class="note">No date recorded</span><br><b style="font-size:22px"><?=
        (int) $result['counts'][Compliance::UNKNOWN] ?></b></div>
      <div><span class="note">In date</span><br><b style="font-size:22px;color:var(--ok)"><?=
        (int) $result['counts'][Compliance::OK] ?></b></div>
    </div>
    <p class="note">Blocks <?= e((string) $result['blocks']) ?>.
      <?= e((string) $result['why']) ?></p>
<?php if (($result['hidden'] ?? 0) > 0): ?><p class="note"><?= (int) $result['hidden'] ?> row(s) outside your scope are not shown.</p><?php endif; ?>
<?php if ($result['findings'] === []): ?>
    <p class="note">Nothing to act on &mdash; and the check ran:
      <?= array_sum($result['counts']) ?> row(s) were read.</p>
<?php else: ?>
    <table>
      <tr><th>Who</th><th>State</th><th>Expiry</th><th>Days</th></tr>
<?php foreach ($result['findings'] as $finding): ?>
      <tr>
        <td><?= e((string) $finding['subject']) ?></td>
        <td><?php if ($finding['state'] === Compliance::LAPSED): ?><span class="no">lapsed</span>
          <?php elseif ($finding['state'] === Compliance::DUE): ?>expiring soon
          <?php else: ?><b>no date recorded</b><?php endif; ?></td>
        <td><?= $finding['expiry'] === '' ? '<span class="note">&mdash;</span>'
          : e((string) $finding['expiry']) ?></td>
        <td class="n"><?= $finding['days'] === null
          ? '<span class="note">not determined</span>'
          : ((int) $finding['days'] < 0
              ? e((string) abs((int) $finding['days'])) . ' days ago'
              : 'in ' . e((string) $finding['days']) . ' days') ?></td>
      </tr>
<?php endforeach; ?>
    </table>
<?php endif; ?>
<?php endif; ?>
  </div>
<?php endforeach; ?>

<?php elseif ($route === 'letters' && (string) ($_GET['e'] ?? '') !== '' && (string) $_GET['e'] !== 'all'
    && !$scope->covers((string) $_GET['e'], $may('employee.letters.view'))): ?>
