<?php foreach (['', 'text', 'textarea', 'number', 'date', 'time', 'datetime-local', 'email', 'tel',
    'checkbox'] as $type): ?>
            <option value="<?= e($type) ?>"<?= $type === (string) ($f['type'] ?? '')
