    <p class="note">The permission this module requires is declared against the module itself in
       <code>config/modules.json</code>, so a customer can hold one role to the employee list and
       another to salary &mdash; two things that are not the same permission, however similar they
       look on a menu.</p>
  </div>
<?php elseif ($module === null): ?>
  <div class="card"><h2>No such module</h2>
    <p class="note">Nothing in <code>config/modules.json</code> declares
       <code><?= e((string) ($_GET['k'] ?? '')) ?></code>. Go back to the <a href="?r=dashboard">Dashboard</a> and open it from the menu.</p></div>
<?php else: ?>
<?php
    // FIXED COMMISSION (owner, 3 Nov 2026): this month's entries of every Active Fixed Commission scheme are raised
    // before Commission Entries lists anything, so they are on the register (and its separate-payout dates) at once.
    if (!empty($module['commission_figures'])) {
        try {
            SmartPRS\Surface\Compensation::ensureFixed($store, date('Y-m'), (array) ((new SmartPRS\Surface\Compensation($store, __DIR__ . '/../config/compensation.json'))->config()['commission'] ?? []));
        } catch (\Throwable $fxE) {
            error_log('SmartPRS Fixed Commission entries not raised: ' . $fxE->getMessage()); // tolerated: the register still lists; payroll raises them again at close
        }
    }
    $q = trim((string) ($_GET['q'] ?? ''));
    $page = max(1, (int) ($_GET['p'] ?? 1));
    $result = $modules->rows($module, $q, $page);
    // PERIOD + ORGANISATION FILTERS ON A REGISTER (owner, 14 Oct: "a filter on the top to check
    // the records with date range, company … all filters as usual"). A module declaring
    // "filters": {"date": "<column>", "employee": "<column>"} gets the app's one filter bar —
    // Period, Company, Branch, Department, Role, Designation, Team, Employee — with its search box
    // in the same form. Rows narrow through the employee they belong to and the date column (a
    // YYYY-MM column compares by month). The page number is `pg` here: `p` is the period mode.
    // ponytail: reads the table whole and pages in PHP — right for a monthly register; push the
    // range into the store's WHERE if one ever holds hundreds of thousands of rows.
    $mfDecl = (array) ($module['filters'] ?? []);

    if ($mfDecl !== []) {
        $mfFilter = orgFilter();
        $mfPeriod = isset($_GET['p']) ? reportPeriod($_GET, financialYearStart($customisation), date('Y-m-d')) : null;
        $mfScoped = $scope->only(liveRows($store, 'employees'), $may('employee.list'));
        $mfOptions = orgFilterOptions($store, $mfScoped);
        $mfEmpCol = (string) ($mfDecl['employee'] ?? 'employee_id');
        $mfDateCol = (string) ($mfDecl['date'] ?? '');
        $mfIds = array_filter($mfFilter) === [] ? null
            : array_flip(array_map(static fn (array $e): string => (string) ($e['id'] ?? ''), orgFilterApply($store, $mfScoped, $mfFilter)));
        $page = max(1, (int) ($_GET['pg'] ?? 1));

        try {
            $mfRows = array_values(array_filter($store->all((string) $module['table']),
                static function (array $r) use ($modules, $module, $mfIds, $mfEmpCol, $mfDateCol, $mfPeriod, $q): bool {
                    if (isRetired($r) || !$modules->rowVisible($module, $r)) {
                        return false;
                    }

                    if ($mfIds !== null && !isset($mfIds[(string) ($r[$mfEmpCol] ?? '')])) {
                        return false;
                    }

                    if ($mfPeriod !== null && $mfDateCol !== '') {
                        $v = (string) ($r[$mfDateCol] ?? '');
                        $n = strlen($v) === 7 ? 7 : 10;

                        if ($v === '' || substr($v, 0, $n) < substr($mfPeriod['from'], 0, $n) || substr($v, 0, $n) > substr($mfPeriod['to'], 0, $n)) {
                            return false;
                        }
                    }

                    return $q === '' || array_filter((array) $module['search'], static fn ($c): bool
                        => stripos((string) ($r[(string) $c] ?? ''), $q) !== false) !== [];
                }));
            // Newest period first, then as entered.
            usort($mfRows, static fn (array $x, array $y): int
                => [(string) ($y[$mfDateCol] ?? ''), (int) ($x['id'] ?? 0)] <=> [(string) ($x[$mfDateCol] ?? ''), (int) ($y['id'] ?? 0)]);
            $mfPages = max(1, (int) ceil(count($mfRows) / 25));
            $page = min($page, $mfPages);
            $result = ['rows' => array_slice($mfRows, ($page - 1) * 25, 25), 'total' => count($mfRows), 'page' => $page,
                'pages' => $mfPages, 'columns' => $result['columns'], 'order' => $mfDateCol !== '' ? $mfDateCol . ' (newest first)' : 'id',
                'bounded' => true, 'why' => null];
        } catch (\Throwable $mfE) {
            $result['why'] = $mfE->getMessage();
        }

        // The query tail every page link carries, so paging keeps the filters.
        $mfTail = orgFilterQuery($mfFilter);

        foreach (array_keys(PERIOD_KEYS) as $mfK) {
            isset($_GET[$mfK]) && $mfTail .= '&amp;' . $mfK . '=' . e(rawurlencode((string) $_GET[$mfK]));
        }
    }
    $spec = $modules->fields($module);
    $editing = (string) ($_GET['edit'] ?? '');
    $current = $editing === '' ? null : $store->find((string) $module['table'], $editing);

    // THE EDIT FORM OBEYS THE SAME REACH AS THE LIST (owner, 28 Sep): an id
    // typed into the address bar does not open somebody else's record.
    if ($current !== null && !$modules->rowVisible($module, $current)) {
        $problem = 'That record belongs to somebody outside your reach.';
        $current = null;
        $editing = '';
    }

    // ONE COLOURED BOX PER RECORD (owner, 23 Sep, pointing at the New Loan
    // screen: "Each company details in each similar box type with proper color
    // coded format"). That shape is this application's own `fieldset.form-section`
    // + `legend` — a bordered box with a solid coloured tab on its top-left edge,
    // six tab/tint pairs cycling by position, in use on the Employee form since
    // 9 Sep. Reused rather than rebuilt.
    //
    // Declared per module in config/modules.json ("record_boxes": true), so
    // nothing else in the product changes shape.
    //
    // THE GUARD IS THE POINT. An earlier attempt at this hid the register table
    // and then drew no boxes, leaving the screen empty below the branding card.
    // Whatever the cause, the shape of the failure was "boxes replaced a table
    // and produced nothing", so the replacement now REQUIRES rows to replace it
    // with: no rows, no boxes, and the table renders its own empty state as it
    // always did. A screen cannot go blank this way.
    $moduleBoxes = (bool) ($module['record_boxes'] ?? false)
        && $may($modules->permission($module, 'edit'))
        && ($result['rows'] ?? []) !== [];

    // BOXES INSTEAD OF A TABLE, for a module that declares it (owner, 23 Sep:
    // "for Each company, have box type structure with ALL the relevant fields
    // within that box for that particular company. NO Other data outside the
    // box for any company").
    //
    // A LIST PLUS AN EDIT SCREEN IS TWO RENDERINGS OF THE SAME ROWS, which is
    // what he kept seeing twice. In boxes mode there is no list and no separate
    // edit screen: every record IS its own open form, so there is nothing to
    // open, nothing to close, and no `&edit=` in the address to survive a
    // refresh. The Add button appends one empty box.
    //
    // PROBATION, PREPARED HERE because in boxes mode it is rendered INSIDE each
    // company's box — the owner's "NO Other data outside the box for any
    // company" — and the box loop runs before the probation card below.
    //
    // Only until the migration: once the six are columns, Modules::fields()
    // returns them and they are ordinary fields in the form above, so none of
    // this renders at all.
    $prbModule = (string) ($probation->declared()['settings_module'] ?? '');
    $prbReady = $probation->companyColumnsExist();
    $prbMayEdit = $may('tenant.settings.update');
    $prbHere = $prbModule !== '' && (string) $module['key'] === $prbModule && $may('tenant.settings.view');

    $prbForm = function (array $cfg, string $companyId, bool $overridden) use ($session, $prbMayEdit): string {
        if (!$prbMayEdit) {
            return '<span class="note">' . e(probationDuration($cfg)) . ' &middot; milestones '
                . e(implode(', ', $cfg['reminder_days'])) . ' days</span>';
        }

        $h = '<form method="post" style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin:0">'
            . '<input type="hidden" name="csrf" value="' . e($session->token()) . '">'
            . '<input type="hidden" name="action" value="probation-config">'
            . '<input type="hidden" name="company" value="' . e($companyId) . '">'
            . '<div><label style="font-size:11px">Probation months</label>'
            . '<input name="default_months" type="number" min="1" max="36" value="'
            . (int) $cfg['default_months'] . '" style="width:84px;padding:4px 6px"></div>'
            . '<div><label style="font-size:11px">+ Days</label>'
            . '<input name="default_days" type="number" min="0" max="30" value="'
            . (int) ($cfg['default_days'] ?? 0) . '" style="width:74px;padding:4px 6px"></div>'
            . '<div><label style="font-size:11px">Reminder milestones (days before end)</label>'
            . '<input name="reminder_days" value="' . e(implode(', ', $cfg['reminder_days']))
            . '" style="width:170px;padding:4px 6px"></div>'
            . '<label class="note"><input type="checkbox" name="notify_hr" value="1"'
            . (($cfg['notify_hr'] ?? true) ? ' checked' : '') . '> Tell HR (Admin / HR Admin — Probation &rarr; Who is told)</label>'
            . '<label class="note"><input type="checkbox" name="notify_manager" value="1"'
            . (($cfg['notify_manager'] ?? false) ? ' checked' : '') . '> Tell the manager</label>'
            . '<label class="note"><input type="checkbox" name="congratulate_employee" value="1"'
            . (($cfg['congratulate_employee'] ?? false) ? ' checked' : '') . '> Congratulate</label>'
            . '<button class="go" style="padding:5px 12px" type="submit">Save probation</button></form>';

        // ITS OWN FORM, not a second button named `action` inside the one above:
        // both would be sent and the server keeps whichever it reads last.
        if ($companyId !== '' && $overridden) {
            $h .= '<form method="post" style="display:inline-block;margin:6px 0 0">'
                . '<input type="hidden" name="csrf" value="' . e($session->token()) . '">'
                . '<input type="hidden" name="action" value="probation-config-clear">'
                . '<input type="hidden" name="company" value="' . e($companyId) . '">'
                . '<button class="btn btn-outline btn-sm" type="submit">Follow the default</button></form>';
        }

        return $h;
    };
?>
