              if ($field['name'] === $c && $field['lookup'] !== []) {
                  foreach ($field['lookup'] as $option) {
                      if ($option['id'] === (string) $shown) {
                          $shown = $option['label'];

                          break 2;
                      }
                  }
                  // NOT IN THE LIST (owner, 21 Oct: BGV showed "150"): an inactive / exited employee or a retired
                  // org row is still named — "CODE · Name" — from its own record, as the edit form already does.
                  if ((string) ($field['lookup_bounds']['table'] ?? '') !== '' && ctype_digit((string) $shown)) {
                      try { $mlRow = $store->find((string) $field['lookup_bounds']['table'], (string) $shown); } catch (\Throwable) { $mlRow = null; /* the id stays shown */ }
                      $mlRow !== null && $shown = isset($mlRow['emp_code']) ? Employment::label($mlRow) : ((string) ($mlRow['name'] ?? '') ?: $shown);
                  }
                  break;
              }
          }
?>
<?php
          $text = $shown === null ? '' : (string) $shown;

          // A FLAG COLUMN reads as a word, not a bit: is_active 1 → active.
          if (str_starts_with($c, 'is_') && in_array($text, ['0', '1'], true)) {
              $text = $text === '1' ? substr($c, 3) : 'not ' . substr($c, 3);
          }

          // LISTS READ LIKE SMARTPRS 2: full text wrapped, never cut with an
          // ellipsis, and a checkbox shows Yes / No, not 1 / 0.
          if (in_array($text, ['0', '1'], true)) {
              foreach ($spec['fields'] ?? [] as $ff) {
                  if ($ff['name'] === $c && $ff['type'] === 'checkbox') { $text = $text === '1' ? 'Yes' : 'No'; }
              }
          }

          $tint = $look['badges'][$c][mb_strtolower($text)] ?? ($text === 'active' ? 'green' : null);
?>
        <td>
<?php if (in_array($c, $spec['locked'], true)): ?>
          <span class="note" title="Needs a permission you do not hold"><i
            class="fas fa-lock"></i></span>
<?php elseif ($text === ''): ?>
<?php   $emptyMeans = '&mdash;'; foreach ($spec['fields'] ?? [] as $ef) { if ($ef['name'] === $c && ($ef['empty'] ?? '') === 'ALL') { $emptyMeans = 'ALL'; } } ?>
          <span class="note"><?= $emptyMeans ?></span>
<?php elseif ($c === $look['avatar']): ?>
          <div style="display:flex;align-items:center;gap:10px">
            <div class="avatar-sm" style="background:<?=
              e($tints[$rowIndex % count($tints)]) ?>"><?= e(mb_strtoupper(mb_substr($text, 0, 2))) ?></div>
            <div><b><?= e($text) ?></b><?php
              if ($look['subtitle'] !== null && (string) ($row[$look['subtitle']] ?? '') !== ''): ?>
              <br><span class="note"><?= e(
                (string) $row[$look['subtitle']]) ?></span><?php endif; ?></div>
          </div>
<?php elseif ($tint !== null): ?>
          <span class="badge badge-<?= e($tint) ?>"><?= e($text) ?></span>
<?php elseif (in_array($c, $look['money'], true) && is_numeric($text)): ?>
          <span style="font-family:var(--mono);font-weight:600"><?= e(
            \SmartPRS\Platform\Support\Money::of(Amount::of($text)->toDecimalString())
              ->format()) ?></span>
<?php else: ?>
          <?= e(capDecimals($text)) ?>
<?php endif; ?>
        </td>
<?php endforeach; ?>
        <td style="text-align:right;white-space:nowrap"><a class="btn btn-sm"
          href="?r=<?= e($rawRoute) ?>&amp;k=<?= e((string) $module['key']) ?>&amp;edit=<?=
          e((string) $row['id']) ?>"><i class="fas fa-pen"></i> Edit</a>
<?php if ($may($modules->permission($module, 'edit'))): ?>
          <form method="post" style="display:inline" onsubmit="return confirm('Remove this row? It is kept in history and stops being offered.')">
            <input type="hidden" name="csrf" value="<?= e($session->token()) ?>"><input type="hidden" name="action" value="module-delete">
            <input type="hidden" name="k" value="<?= e((string) $module['key']) ?>"><input type="hidden" name="id" value="<?= e((string) $row['id']) ?>">
            <button class="btn btn-sm" style="background:#fff;color:#b91c1c;border:1px solid #fecaca"><i class="fas fa-trash"></i> Delete</button></form>
<?php endif; ?></td>
      </tr>
<?php endforeach; ?>
      </tbody>
    </table>
    </div>
<?php if ((int) $result['pages'] > 1): ?>
    <p style="padding:14px 22px;border-top:1px solid var(--border);margin:0">
<?php for ($i = 1; $i <= (int) $result['pages'] && $i <= 20; $i++): ?>
      <a class="btn" style="<?= $i === (int) $result['page']
        ? 'background:var(--accent);color:#fff;border:0' : '' ?>"
        href="?r=<?= e($rawRoute) ?>&amp;k=<?= e((string) $module['key']) ?>&amp;q=<?= e($q) ?><?= $mfDecl === [] ? '&amp;p=' . $i : '&amp;pg=' . $i . $mfTail ?>"><?= $i ?></a>
<?php endfor; ?>
<?php if ((int) $result['pages'] > 20): ?><span class="note">…and
  <?= (int) $result['pages'] - 20 ?> more</span><?php endif; ?>
    </p>
<?php endif; ?>
<?php endif; ?>
  </div>
<?php endif; /* THE LIST CARD ENDS HERE, AND SO DOES "if (!$moduleBoxes)".
     It used to end 265 lines further down, past the Add/Edit form — so switching a
     module to boxes suppressed the table AND skipped every box, and the screen came
     back empty with no error to show for it. The table is what boxes mode replaces;
     the form below is what boxes mode RENDERS, once per record. */ ?>

<?php
    // WHICH RECORDS GET A FORM. In boxes mode: every row, each in its own
    // coloured box, always open — so there is no Edit to click, nothing to
    // close, and no `&edit=` in the address to survive a refresh. Otherwise the
    // single Add/Edit card, exactly as before.
    $boxRows = $moduleBoxes
        ? array_values($result['rows'])
        : (($current !== null || (string) ($_GET['add'] ?? '') === '1') ? [$current] : []);

    // Add appends one empty box rather than replacing the list.
    $moduleBoxes && (string) ($_GET['add'] ?? '') === '1' && $boxRows[] = null;
?>
<?php foreach ($boxRows as $current): ?>
  <div class="card"<?= $moduleBoxes ? ' style="padding:10px 14px 14px"' : '' ?>>
<?php if ($moduleBoxes): ?>
    <?php // THE RECORD IS THE BOX, and the box is the app's own form-section:
          // a bordered card with a solid coloured tab carrying the company's
          // NAME, the tab and tint cycling by position so two companies never
          // look the same. Exactly the New Loan screen's shape, from the same
          // stylesheet rules rather than a second set written here.
          //
          // The legend holds the name AND the record's controls, because in
          // this mode the form is always open: there is no Edit to click and
          // nothing to close, so Delete is the only control it needs. ?>
    <?php // DOUBLE LINE, ROUNDED (owner, 23 Sep: "Have proper double line rounded
          // square box around each of the company"). Width and style only — the
          // colour still comes from .form-section, so the company box matches the
