    <fieldset class="form-section" style="margin-top:8px;border-width:5px;border-style:double;border-radius:14px">
    <legend style="display:flex;align-items:center;gap:10px;flex-wrap:wrap"><?= $current === null
      ? 'New ' . e(singular((string) $module['label']))
      : e(trim((string) ($current['name'] ?? '')) !== ''
          ? (string) $current['name']
          : singular((string) $module['label']) . ' #' . (string) $current['id']) ?>
<?php if ($current !== null): ?>
      <form method="post" style="margin:0" onsubmit="return confirm('Remove this record? It is kept in history and stops being offered.')">
        <input type="hidden" name="csrf" value="<?= e($session->token()) ?>"><input type="hidden" name="action" value="module-delete">
        <input type="hidden" name="k" value="<?= e((string) $module['key']) ?>"><input type="hidden" name="id" value="<?= e((string) $current['id']) ?>">
        <button class="btn btn-sm" style="background:rgba(255,255,255,.15);color:#fff;border:1px solid rgba(255,255,255,.45);padding:2px 9px;font-size:11px"><i class="fas fa-trash"></i> Delete</button></form>
<?php endif; ?>
    </legend>
<?php endif; ?>
<?php if (!$moduleBoxes): ?>
    <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap">
      <h2<?= $moduleBoxes ? '' : ' id="add-row"' ?> style="margin:0"><?php
        if ($moduleBoxes) {
            echo $current === null
                ? 'New ' . e(singular((string) $module['label']))
                : e(trim((string) ($current['name'] ?? '')) !== ''
                    ? (string) $current['name']
                    : singular((string) $module['label']) . ' #' . (string) $current['id']);
        } else {
            echo $current === null
                ? 'Add ' . e(singular((string) $module['label']))
                : 'Edit ' . e(singular((string) $module['label'])) . ' #' . e((string) $current['id']);
