            <thead><tr><th style="padding:4px 6px">#</th><th style="padding:4px 6px"><?= ($f['upto_label'] ?? '') !== '' ? e((string) $f['upto_label']) : 'Up to (&#8377;)' ?></th><th style="padding:4px 6px">Rate (%)</th><th></th></tr></thead>
            <tbody>
<?php foreach ($mfBands as $mfI => $mfB): ?>
              <tr><td style="padding:2px 6px"><?= $mfI + 1 ?></td>
                <td style="padding:2px 4px"><input type="number" min="0" step="any" data-k="upto" value="<?= e(capDecimals((string) ($mfB['upto'] ?? ''))) ?>" placeholder="blank = above" style="width:100%;box-sizing:border-box"></td>
                <td style="padding:2px 4px"><input type="number" min="0" max="100" step="any" data-k="rate" value="<?= e(capDecimals((string) ($mfB['rate'] ?? ''))) ?>" style="width:100%;box-sizing:border-box"></td>
                <td style="padding:2px 4px"><button type="button" class="btn btn-outline" data-band-del title="Remove this band"><i class="fas fa-trash"></i></button></td></tr>
<?php endforeach; ?>
            </tbody>
          </table>
          <div style="margin:4px 0 2px"><button type="button" class="btn btn-outline" data-band-add <?= $f['readonly'] ? 'disabled' : '' ?>><i class="fas fa-plus"></i> Add band</button></div>
          <script>(function(){var h=document.getElementById('f_<?= e($f['name']) ?>'),w=h.parentNode,tb=w.querySelector('.bands-ed tbody');
            function sync(){var out=[];Array.prototype.forEach.call(tb.rows,function(r,i){r.cells[0].textContent=i+1;
              var u=r.querySelector('[data-k=upto]').value.trim(),v=r.querySelector('[data-k=rate]').value.trim();if(v!==''){out.push({upto:u,rate:v});}});
              h.value=out.length?JSON.stringify(out):'';}
            w.addEventListener('input',sync);
            w.addEventListener('click',function(ev){var b=ev.target.closest('button');if(!b){return;}
