<?php // SHOW-WHEN (28 Oct): a field declared with show_when appears only while the named field holds one of
      // its values — e.g. Payout Date only for a Separate payout, Slab bands only for "Slab". ?>
      <script>(function(){var fm=document.currentScript.closest('form');if(!fm){return;}
        var ws=fm.querySelectorAll('[data-show-when]');if(!ws.length){return;}
        function run(){ws.forEach(function(w){var c={};try{c=JSON.parse(w.getAttribute('data-show-when'));}catch(x){}
          var on=Object.keys(c).every(function(k){var el=fm.querySelector('[name="'+k+'"][type=checkbox]')||fm.querySelector('[name="'+k+'"]'),v=el?(el.type==='checkbox'?(el.checked?'1':'0'):el.value):'';
            return (c[k]||[]).some(function(o){return String(o).toLowerCase()===String(v).toLowerCase();});});
          w.style.display=on?'':'none';});
        // SET BY ANOTHER FIELD and LABELS THAT FOLLOW ANOTHER FIELD (29 Oct): Paid on = "Fixed amount typed" sets How it
        // pays to "typed amount" (an option offered only then); Rate reads "Rate (% …)" or "Flat amount (₹)".
        fm.querySelectorAll('[data-set-when]').forEach(function(w){var c={};try{c=JSON.parse(w.getAttribute('data-set-when'));}catch(x){}
          var me=fm.querySelector('[name="'+w.getAttribute('data-field')+'"]');if(!me){return;}var forced=null,targets=[];
          Object.keys(c).forEach(function(k){var el=fm.querySelector('[name="'+k+'"]'),v=el?el.value:'';Object.keys(c[k]).forEach(function(when){targets.push(c[k][when]);if(String(when).toLowerCase()===String(v).toLowerCase()){forced=c[k][when];}});});
          if(me.tagName==='SELECT'){[].forEach.call(me.options,function(o){if(targets.indexOf(o.value)>=0){o.hidden=forced===null;o.disabled=forced===null;}});}
          if(forced!==null){me.value=forced;}else if(targets.indexOf(me.value)>=0){me.value='';}});
        fm.querySelectorAll('[data-label-when]').forEach(function(w){var c={};try{c=JSON.parse(w.getAttribute('data-label-when'));}catch(x){}
          var lb=w.querySelector('label');if(!lb){return;}lb.dataset.base=lb.dataset.base||lb.childNodes[0].textContent;var txt=lb.dataset.base;
          Object.keys(c).forEach(function(k){var el=fm.querySelector('[name="'+k+'"]'),v=el?el.value:'';Object.keys(c[k]).forEach(function(when){if(String(when).toLowerCase()===String(v).toLowerCase()){txt=c[k][when];}});});
          lb.childNodes[0].textContent=txt;});
        // A BOX WHOSE FIELDS ARE ALL HIDDEN is hidden with them.
        fm.querySelectorAll('fieldset.form-section').forEach(function(f){var ds=f.querySelectorAll('.row > div');if(!ds.length){return;}f.style.display=[].some.call(ds,function(d){return d.style.display!=='none';})?'':'none';});}
        fm.addEventListener('change',function(){run();run();});run();run();})();</script>
      <script>(function(){var fm=document.currentScript.closest('form');if(!fm){return;}
        // % INCREASE, WORKED OUT (owner, 30 Oct): (new − old) / old × 100 in whole paise, as Modules::percentChange does on Save.
        fm.querySelectorAll('[data-percent-change]').forEach(function(t){var p=t.getAttribute('data-percent-change').split(','),
          o=fm.querySelector('[name="'+p[0]+'"]'),n=fm.querySelector('[name="'+p[1]+'"]');if(!o||!n){return;}
          var paise=function(v){v=String(v||'').replace(/,/g,'').trim();if(!/^-?\d+(\.\d+)?$/.test(v)){return null;}var s=v.split('.');return parseInt(s[0],10)*100+(s[0][0]==='-'?-1:1)*parseInt(((s[1]||'')+'00').slice(0,2),10);};
          var go=function(){var a=paise(o.value),b=paise(n.value);if(a===null||b===null||a<=0||String(n.value).trim()===''){t.value='';return;}
            var x=(b-a)*10000,h=Math.floor((Math.abs(x)*2+a)/(2*a));t.value=(x<0&&h>0?'-':'')+Math.floor(h/100)+'.'+String(h%100).padStart(2,'0');};
          o.addEventListener('input',go);n.addEventListener('input',go);go();});})();</script>
