<?php // TRY IT BEFORE SAVING (owner, 3 Nov 2026): type a simulated Target Achieved and see what this scheme pays — the
      // same arithmetic as Compensation::commission / schemeTds, in exact paise, from the values on the form right now. ?>
      <fieldset class="form-section" id="cs-sim" style="border:2px dashed #1F3A5F;border-radius:10px;padding:10px 14px;margin:12px 0">
        <legend style="font-weight:700;color:#1F3A5F;padding:0 6px">Try it — simulate before saving</legend>
        <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end">
          <div style="min-width:210px"><label for="cs-sim-in">Target achieved to simulate (₹)</label>
            <input type="number" min="0" step="any" id="cs-sim-in" placeholder="e.g. 600000" style="width:100%;box-sizing:border-box"></div>
          <div style="flex:1;min-width:280px"><div id="cs-sim-out" style="font-weight:600;color:#1e3a5f;line-height:1.5">Type a figure to see the commission, TDS and net payable.</div></div>
        </div>
        <p class="note" style="margin:6px 0 0">Nothing is saved — this only checks the setup.</p>
      </fieldset>
      <script>(function(){var box=document.getElementById('cs-sim'),fm=box.closest('form');if(!fm){return;}
        var inp=document.getElementById('cs-sim-in'),out=document.getElementById('cs-sim-out');
        function v(n){var e=fm.querySelector('[name="'+n+'"][type=checkbox]')||fm.querySelector('[name="'+n+'"]');return e?(e.type==='checkbox'?(e.checked?'1':''):String(e.value||'').trim()):'';}
        function paise(x){x=String(x||'').replace(/,/g,'').trim();if(!/^\d*(\.\d*)?$/.test(x)||x===''||x==='.'){return 0n;}var p=x.split('.');return BigInt(p[0]||'0')*100n+BigInt(((p[1]||'')+'00').slice(0,2));}
        function r4(x){x=String(x||'').trim();if(!/^\d*(\.\d*)?$/.test(x)||x===''){return 0n;}var p=x.split('.');return BigInt(p[0]||'0')*10000n+BigInt(((p[1]||'')+'0000').slice(0,4));}
        function pct(pa,rate){return (pa*r4(rate)+500000n)/1000000n;}
        function inr(pa){var s=pa.toString(),neg=s[0]==='-';s=neg?s.slice(1):s;s=s.padStart(3,'0');var w=s.slice(0,-2),f=s.slice(-2),l=w.slice(-3),r=w.slice(0,-3);
          return (neg?'-':'')+'₹'+(r?r.replace(/\B(?=(\d{2})+(?!\d))/g,',')+',':'')+l+'.'+f;}
        function two(h){return (h/100n)+'.'+String(h%100n).padStart(2,'0');}   // hundredths → "120.00"
        function run(){var t=v('rate_type'),col=paise(inp.value),g=0n,why='';
          if(t===''){out.textContent='Pick the Commission type first.';return;}
          if(t==='Fixed'){g=paise(v('rate_value'));why='Fixed commission for the month';}
          else{var tg=paise(v('target_amount'));if(inp.value===''){out.textContent='Type a figure to see the commission, TDS and net payable.';return;}
            if(tg===0n){out.textContent='Enter the Target per person first.';return;}
            var ach=col*10000n/tg,achT=two(ach)+'%',thr=v('threshold');
            if(thr!==''&&col*1000000n<r4(thr)*tg){out.textContent='Achievement '+achT+' is below the minimum '+thr+'% — nothing is paid.';return;}
            var pb=v('pay_on')==='excess'?(col>tg?col-tg:0n):col,pbT=v('pay_on')==='excess'?' on '+inr(pb)+' above the target':' on '+inr(pb);
            if(t==='Percent'){g=pct(pb,v('rate_value'));why='Achievement '+achT+' → '+(v('rate_value')||'0')+'%'+pbT;}
            else{var bands=[];try{bands=JSON.parse(v('slabs')||'[]');}catch(x){}
              bands=bands.filter(function(b){return String(b.rate||'')!=='';}).sort(function(a,b){return a.upto===''?1:(b.upto===''?-1:Number(r4(a.upto)-r4(b.upto)));});
              var band=null;bands.some(function(b){if(String(b.upto)===''||col*10000n<=paise(b.upto)*tg){band=b;return true;}return false;});
              if(!band){out.textContent='Achievement '+achT+' — no slab band covers it, so nothing is paid. Add a last band with Up to blank.';return;}
              g=pct(pb,band.rate);why='Achievement '+achT+' falls in the band '+(String(band.upto)===''?'above the last limit':'up to '+band.upto+'%')+' → '+band.rate+'%'+pbT;}}
          var tds=v('tds_applicable')==='1'?pct(g,v('tds_rate')||'0'):0n;
          out.innerHTML='';var a=document.createElement('div');a.textContent=why+'.';
          var b2=document.createElement('div');b2.style.fontSize='1.05em';b2.textContent='Commission '+inr(g)+'  −  TDS '+inr(tds)+(v('tds_applicable')==='1'?' ('+(v('tds_rate')||'0')+'%)':' (not applicable)')+'  =  Net payable '+inr(g-tds);
          out.appendChild(a);out.appendChild(b2);}
        inp.addEventListener('input',run);fm.addEventListener('input',function(){setTimeout(run,0);});fm.addEventListener('change',function(){setTimeout(run,0);});run();})();</script>
<?php endif; ?>
<?php if (!empty($module['commission_figures'])):
      // COMMISSION ENTRY, WORKED OUT ON SCREEN (owner, 29 Oct 2026). The same arithmetic Modules::save repeats on
      // Save (it is the one that counts): gross from the scheme, TDS by Salary Type, net = gross − TDS, in paise.
      // A Company / Branch chosen on a NEW entry greys the Employee out = every Commission-type employee there.
      $ceRulesJs = (array) ((new SmartPRS\Surface\Compensation($store, __DIR__ . '/../config/compensation.json'))->config()['commission'] ?? []);
      $ceSchemesJs = [];
      foreach (liveRows($store, 'incentive_schemes') as $ceS) {
          $ceSchemesJs[(string) $ceS['id']] = ['type' => strtolower(trim((string) ($ceS['rate_type'] ?? ''))), 'rate' => (string) ($ceS['rate_value'] ?? ''),
              'gated' => trim((string) ($ceS['threshold'] ?? '')) !== '' && trim((string) ($ceS['target_amount'] ?? '')) === '',
              'threshold' => (string) ($ceS['threshold'] ?? ''), 'target' => (string) ($ceS['target_amount'] ?? ''), 'min' => (string) ($ceS['min_collected'] ?? ''),
              'excess' => strtolower((string) ($ceS['pay_on'] ?? '')) === 'excess', 'tds' => (string) ($ceS['tds_rate'] ?? ''), 'slabs' => SmartPRS\Surface\Compensation::slabsOf($ceS),
              'purpose' => (string) ($ceS['purpose'] ?? ''), 'portfolio' => (string) ($ceS['portfolio'] ?? ''),
              'payout_method' => (string) ($ceS['payout_method'] ?? ''), 'pday' => (int) (trim((string) ($ceS['payout_day'] ?? '')) !== '' ? $ceS['payout_day'] : (preg_match('/^\d{4}-\d{2}-(\d{2})/', (string) ($ceS['payout_date'] ?? ''), $cePm) === 1 ? $cePm[1] : 0)),
              'poff' => strtolower(trim((string) ($ceS['payout_offset'] ?? ''))) === 'same' ? 0 : 1,
              // COMMISSION / INCENTIVE SETUP (30 Oct): the scheme decides TDS — see Compensation::schemeTds().
              'kind' => trim((string) ($ceS['scheme_kind'] ?? '')), 'tdsOn' => SmartPRS\Surface\Compensation::tdsApplicable($ceS),
              'tdsMode' => strtolower(trim((string) ($ceS['tds_mode'] ?? ''))) === 'flat' ? 'flat' : 'percent', 'tdsFlat' => (string) ($ceS['tds_flat'] ?? ''),
              // FIXED / BASED ON TARGET (owner, 3 Nov 2026)
              'fixedC' => SmartPRS\Surface\Compensation::isFixedCommission($ceS), 'targetC' => SmartPRS\Surface\Compensation::isTargetBased($ceS)];
      }
      $ceFlatJs = [];
      // WHO A FIXED COMMISSION SCHEME PAYS, and WHICH TARGET-BASED SCHEMES COVER WHOM (owner, 3 Nov 2026) — Active schemes
      // only; the month is checked on screen against Valid From / Till, and again on Save (Modules::save).
      $ceFixJs = [];
      $ceTgtJs = [];
      $ceRolesJs = (array) (orgNames($store)['designation_roles'] ?? []);
      $ceLiveSch = array_values(array_filter(liveRows($store, 'incentive_schemes'), static fn (array $s): bool
          => SmartPRS\Surface\Compensation::liveIn($s, '') && (SmartPRS\Surface\Compensation::isFixedCommission($s) || SmartPRS\Surface\Compensation::isTargetBased($s))));
      foreach (liveRows($store, 'employees') as $ceE) {
          SmartPRS\Surface\Compensation::flatTds($ceE, $ceRulesJs) && $ceFlatJs[(string) $ceE['id']] = 1;
          foreach ($ceLiveSch as $ceS) {
              if (!SmartPRS\Surface\Compensation::eligible($ceS, $ceE, $ceRolesJs)) {
                  continue;
              }
              SmartPRS\Surface\Compensation::isFixedCommission($ceS)
                  ? $ceFixJs[(string) $ceE['id']][] = ['n' => (string) ($ceS['name'] ?? ''), 'f' => substr((string) ($ceS['valid_from'] ?? ''), 0, 7), 't' => substr((string) ($ceS['valid_till'] ?? ''), 0, 7)]
                  : $ceTgtJs[(string) $ceE['id']][] = (string) $ceS['id'];
          }
      } ?>
      <p class="note" id="ce-tds-note" style="margin:6px 0 0;color:#1e3a5f;font-weight:600"></p>
      <script>(function(){var fm=document.currentScript.closest('form');if(!fm){return;}
        var S=<?= json_encode($ceSchemesJs, JSON_HEX_TAG | JSON_HEX_AMP) ?>,FLAT=<?= json_encode((object) $ceFlatJs) ?>,FIX=<?= json_encode((object) $ceFixJs, JSON_HEX_TAG | JSON_HEX_AMP) ?>,TGT=<?= json_encode((object) $ceTgtJs) ?>,DEF=<?= json_encode((string) ($ceRulesJs['default_tds_rate'] ?? '0')) ?>,
          isNew=<?= $current === null ? 'true' : 'false' ?>,SIMPLE='Simple claim — target / bonus / special incentive';
        function el(n){return fm.querySelector('[name="'+n+'"]');}
        var emp=el('employee_id'),co=el('employer_company_id'),br=el('branch_id'),sch=el('scheme_id'),ct=el('claim_type'),
          base=el('base_amount'),gross=el('gross_amount'),rate=el('tds_rate'),tds=el('tds_amount'),net=el('amount'),note=document.getElementById('ce-tds-note');
        // EXACT MONEY: a decimal string → paise (BigInt); a rate → 1/10000ths; product rounded half-up.
        function paise(v){v=String(v||'').trim();if(!/^\d*(\.\d*)?$/.test(v)||v===''||v==='.'){return 0n;}var p=v.split('.');return BigInt(p[0]||'0')*100n+BigInt(((p[1]||'')+'00').slice(0,2));}
        function r4(v){v=String(v||'').trim();if(!/^\d*(\.\d*)?$/.test(v)||v===''){return 0n;}var p=v.split('.');return BigInt(p[0]||'0')*10000n+BigInt(((p[1]||'')+'0000').slice(0,4));}
        function pct(pa,rate){var n=pa*r4(rate);return (n+500000n)/1000000n;}
        function money(pa){var s=pa<0n?'-':'';pa=pa<0n?-pa:pa;var r=(pa%100n).toString();return s+(pa/100n).toString()+'.'+(r.length<2?'0'+r:r);}
        function inr(pa){var s=money(pa),neg=s[0]==='-';s=neg?s.slice(1):s;var p=s.split('.'),w=p[0],l=w.slice(-3),r=w.slice(0,-3);
          return (neg?'-':'')+'₹'+(r?r.replace(/\B(?=(\d{2})+(?!\d))/g,',')+',':'')+l+'.'+p[1];}
        function ro(i,on){if(!i){return;}i.readOnly=on;i.style.background=on?'#eef2f7':'';i.tabIndex=on?-1:0;}
        function allMode(){return isNew&&emp&&emp.value===''&&((co&&co.value!=='')||(br&&br.value!==''));}
        function lockEmp(){if(!emp||!isNew){return;}
          // A Company / Branch chosen with the Employee left as ALL = every Commission-type employee there: the Employee is greyed
          // out. Picking an employee first fills its own Company / Branch and keeps the pick. Company and Branch back to ALL frees it.
          var on=((co&&co.value!=='')||(br&&br.value!==''))&&emp.value==='';
          emp.disabled=on;emp.style.background=on?'#e5e7eb':'';emp.style.color=on?'#6b7280':'';emp.style.cursor=on?'not-allowed':'';
          emp.title=on?'Every Commission-type employee of the chosen Company / Branch — set Company and Branch to ALL to pick one person':'';}
        function calc(){
          var sc=sch&&S[sch.value]?S[sch.value]:null,all=allMode(),flat=all||(emp&&FLAT[emp.value]===1),g;
          if(ct&&all){ct.value=SIMPLE;var co1=ct.querySelector('option[value^="Collection"]');co1&&(co1.disabled=true);}else if(ct){ct.querySelectorAll('option').forEach(function(o){o.disabled=false;});}
          var tb=!!(sc&&sc.targetC);
          // THE TARGET ACHIEVED DRIVES IT (owner, 3 Nov 2026): the commission is never typed when the scheme can work it out.
          var auto=sc&&!sc.gated&&(sc.type==='fixed'||((sc.type==='percent'||sc.type==='slab')&&base&&base.value!==''));
          if(auto&&tb&&paise(sc.target)===0n&&String(sc.threshold||'')===''){gross.value='0.00';}
          else if(auto){
            // The same order as Compensation::commission: target gate, minimum, then the rate on the whole or the excess.
            var col=paise(base&&base.value||''),ok1=true,above=0n;
            if(String(sc.threshold||'')!==''&&String(sc.target||'')!==''){ok1=col*1000000n>=r4(sc.threshold)*paise(sc.target);above=paise(sc.target);}
            if(sc.targetC&&String(sc.target||'')!==''){above=paise(sc.target);}   // target-based: one minimum (the %), excess = above the target
            if(ok1&&!sc.targetC&&String(sc.min||'')!==''&&paise(sc.min)>0n){ok1=col>=paise(sc.min);if(above===0n){above=paise(sc.min);}}
            var pb=sc.excess&&sc.type!=='fixed'?(col>above?col-above:0n):col;
            if(!ok1){g=0n;}
            else if(sc.type==='fixed'){g=paise(sc.rate);}
            else if(sc.type==='percent'){g=pct(pb,sc.rate);}
            else if(tb){ // TARGET-BASED (3 Nov): the band is picked by achievement % = achieved ÷ target × 100, exactly
              var tg=paise(sc.target),band=null;(sc.slabs||[]).some(function(x){if(x.upto===''||col*10000n<=paise(x.upto)*tg){band=x;return true;}return false;});g=band?pct(pb,band.rate):0n;}
            else{var b=pb,band=null;(sc.slabs||[]).some(function(x){if(x.upto===''||b<=paise(x.upto)){band=x;return true;}return false;});g=band?pct(b,band.rate):0n;}
            gross.value=money(g);}
          var typed=!sc||sc.type==='open'||sc.gated;   // only an "amount typed" scheme (or an old entry with no scheme) takes a typed figure
          if(!auto&&!typed){gross.value='';}
          ro(gross,!typed);g=paise(gross.value);
          // TDS FROM THE SCHEME (Commission / Incentive Setup): ticked = its Flat ₹ or %; not ticked = none. No TDS % box on the entry.
          var t,rv='0',sk=sc&&sc.kind;
          if(sk){if(!sc.tdsOn){t=0n;}else if(sc.tdsMode==='flat'){t=paise(sc.tdsFlat);t=t>g?g:t;}else{rv=sc.tds||'0';t=pct(g,rv);}}
          else{rv=flat?(sc&&sc.tds!==''?sc.tds:DEF):'0';t=flat?pct(g,rv):0n;}
          tds.value=money(t);net.value=money(g-t);ro(tds,true);ro(net,true);
          var rvT=money(r4(rv)/100n),paidT='';
          if(sc){var pdI=payIso(sc);paidT=/^separate/i.test(sc.payout_method||'')?(pdI?' Paid separately on '+pdI.slice(8,10)+'-'+pdI.slice(5,7)+'-'+pdI.slice(0,4)+'.':' Paid separately (pick the payroll month).'):' Paid with the salary.';
            paidT=(sc.purpose?' Purpose: '+sc.purpose+(sc.portfolio?' · '+sc.portfolio:'')+'.':'')+paidT;}
          if(note&&sk){note.textContent=sc.kind+' Setup scheme — '+(!sc.tdsOn?'TDS not applicable.':(sc.tdsMode==='flat'?'flat TDS ₹'+money(paise(sc.tdsFlat))+'.':'TDS '+rvT+'%.'))+paidT;}
          else if(note){note.textContent=all?'ALL: one entry for every active Commission-type employee of the chosen Company / Branch — flat TDS (194H) at the % above.'
            :(emp&&emp.value===''?'Pick the employee, or choose a Company / Branch for every Commission-type employee there.'
            :(flat?'Salary Type Commission — flat TDS (194H) at '+rvT+'%.':'Salary / Salary + Commission — no TDS here; the commission is added to the salary and taxed on the income-tax slabs in payroll.'))+paidT;}}
        // WHEN A SEPARATE PAYOUT IS PAID: the scheme's payout day in this entry's payroll month or the next (Compensation::payoutDate).
        function payIso(sc){var m=el('month');if(!sc||!sc.pday||!m||!/^\d{4}-\d{2}/.test(m.value)){return '';}
          var y=+m.value.slice(0,4),mo=+m.value.slice(5,7)-1+(+sc.poff||0);y+=Math.floor(mo/12);mo=((mo%12)+12)%12;
          var last=new Date(y,mo+1,0).getDate(),d=Math.min(sc.pday,last);return y+'-'+String(mo+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');}
        function fromScheme(){var sc=sch&&S[sch.value];if(!sc){return;}
          [['purpose',sc.purpose],['portfolio',sc.portfolio],['payout_method',sc.payout_method]].forEach(function(p){var i=el(p[0]);
            if(i&&i.value===''&&p[1]!==''){i.value=p[1];i.dispatchEvent(new Event('change',{bubbles:true}));}});
          rate&&(rate.value='');}
        // A SEPARATE PAYOUT'S DATE (29 Oct): the scheme's payout day in this entry's payroll month or the next — the
        // same as Compensation::payoutDate on Save; a date typed by hand is left alone.
        function payDate(){var sc=sch&&S[sch.value],pd=el('payout_date'),m=el('month'),pm=el('payout_method');
          if(!sc||!sc.pday||!pd||!m||!pm||!/^separate/i.test(pm.value)||!/^\d{4}-\d{2}/.test(m.value)||(pd.value!==''&&pd.dataset.auto!=='1')){return;}
          var y=+m.value.slice(0,4),mo=+m.value.slice(5,7)-1+(+sc.poff||0);y+=Math.floor(mo/12);mo=((mo%12)+12)%12;
          var last=new Date(y,mo+1,0).getDate(),d=Math.min(sc.pday,last),iso=y+'-'+String(mo+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
          if(pd.value!==iso){pd.value=iso;pd.dataset.auto='1';pd.dispatchEvent(new Event('input',{bubbles:true}));}}
        // A BOX WHOSE FIELDS ARE ALL HIDDEN (Collection evidence on a Simple claim) is hidden with them.
        function boxes(){fm.querySelectorAll('fieldset.form-section').forEach(function(f){var any=Array.prototype.some.call(f.querySelectorAll('.row > div'),function(d){return d.style.display!=='none';});f.style.display=any?'':'none';});}
        // FIXED COMMISSION / BASED ON TARGET (owner, 3 Nov 2026). An employee a Fixed Commission scheme pays (in the
        // payroll month) gets a popup and no amount; otherwise the target-based schemes covering them are offered and
        // "Target achieved" is asked for.
        var mon=el('month'),pop=null,popKey='',subs={forEach:function(cb){fm.querySelectorAll('button[type=submit]').forEach(cb);}};   // the Save button comes after this script: looked up each time
        function fixedFor(){var l=emp&&FIX[emp.value],m=mon?String(mon.value).slice(0,7):'';if(!l){return null;}
          for(var i=0;i<l.length;i++){if(!m||((l[i].f===''||m>=l[i].f)&&(l[i].t===''||m<=l[i].t))){return l[i];}}return null;}
        function showPop(msg){var at=(emp.closest('div[style]')||emp.parentNode);if(!pop){pop=document.createElement('div');
            pop.setAttribute('role','alert');pop.style.cssText='position:absolute;z-index:60;max-width:420px;background:#fff;border:2px solid #b91c1c;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.18);padding:10px 12px;color:#7f1d1d;font-weight:600';
            document.body.appendChild(pop);}
          var r=at.getBoundingClientRect();pop.style.left=(r.left+window.scrollX)+'px';pop.style.top=(r.bottom+window.scrollY+4)+'px';
          pop.innerHTML='';var t=document.createElement('div');t.textContent=msg;var ok=document.createElement('button');ok.type='button';ok.className='btn btn-outline';ok.textContent='OK';ok.style.marginTop='8px';
          ok.onclick=function(){pop.style.display='none';};pop.appendChild(t);pop.appendChild(ok);pop.style.display='';}
        function fixedGuard(){var fx=isNew?fixedFor():null,k=(emp?emp.value:'')+'|'+(mon?mon.value:'');
          [gross,rate,tds,net,base].forEach(function(i){if(!i){return;}if(fx){i.value='';ro(i,true);}});
          subs.forEach(function(b){b.disabled=!!fx;b.title=fx?'Covered by Fixed Commission — no custom entry':'';});
          if(fx&&k!==popKey){popKey=k;showPop('This employee is covered as part of Fixed Commission (scheme "'+fx.n+'"). No custom commission entry allowed.');}
          if(!fx){popKey='';pop&&(pop.style.display='none');}
          if(fx&&note){note.textContent='Covered by Fixed Commission "'+fx.n+'" — paid automatically every month; no custom entry.';}
          return !!fx;}
        function schemeList(){if(!sch){return;}var mine=emp&&TGT[emp.value]?TGT[emp.value]:[],picked=null;
          [].forEach.call(sch.options,function(o){var sc=S[o.value];if(!sc){return;}
            var off=!!sc.fixedC||(!!sc.targetC&&!!(emp&&emp.value)&&mine.indexOf(o.value)<0);o.hidden=off;o.disabled=off;});
          if(sch.value!==''&&sch.selectedOptions[0]&&sch.selectedOptions[0].disabled){sch.value='';}
          if(isNew&&sch.value===''&&mine.length===1){sch.value=mine[0];fromScheme();}}
        var baseBox=base?(base.closest('div[data-show-when]')||base.parentNode):null,baseLb=baseBox?baseBox.querySelector('label'):null,baseTxt=baseLb?baseLb.childNodes[0].textContent:'';
        function targetBox(){var sc=sch&&S[sch.value],tb=!!(sc&&sc.targetC);if(!baseBox){return;}
          // Target Achieved is asked for unless the scheme pays a fixed or a typed amount; an Incentive scheme on collections calls it that.
          baseBox.style.display=sc&&!tb&&(sc.type==='fixed'||sc.type==='open')?'none':'';
          if(baseLb){baseLb.childNodes[0].textContent=sc&&!tb&&sc.kind==='Incentive'?'Amount Collected (₹)':baseTxt;}
          if(tb&&note&&base.value!==''&&paise(sc.target)>0n){var a=paise(base.value)*10000n/paise(sc.target);
            note.textContent='Target '+inr(paise(sc.target))+' — achieved '+inr(paise(base.value))+' = '+(a/100n)+'.'+String(a%100n).padStart(2,'0')+'% achievement. '+note.textContent;}}
        // MANY EMPLOYEES = ONE FIGURE EACH (owner, 3 Nov 2026): with Employee = ALL and a scheme that works from the Target
        // Achieved, no lump sum is typed — the bulk sample for the scheme lists everyone, works each commission out, and is
        // uploaded (all or nothing, row + cell named). No scheme yet = a popup to select it before the sample downloads.
        window.ceSchemePop=function(at,msg){var p=document.getElementById('ce-pop2')||document.createElement('div');p.id='ce-pop2';p.setAttribute('role','alert');
          p.style.cssText='position:absolute;z-index:60;max-width:380px;background:#fff;border:2px solid #b91c1c;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.18);padding:10px 12px;color:#7f1d1d;font-weight:600';
          p.textContent=msg||'Select the scheme to download the sample file.';var ok=document.createElement('button');ok.type='button';ok.className='btn btn-outline';ok.textContent='OK';ok.style.cssText='display:block;margin-top:8px';
          ok.onclick=function(){p.style.display='none';};p.appendChild(ok);document.body.appendChild(p);var r=at.getBoundingClientRect();
          p.style.left=(r.left+window.scrollX)+'px';p.style.top=(r.bottom+window.scrollY+4)+'px';p.style.display='';};
        var workBox=gross?gross.closest('fieldset'):null,bulk=null;
        function manyMode(){return isNew&&emp&&emp.value==='';}   // Employee = ALL: no single Target Achieved (owner, 3 Nov)
        function bulkPanel(){if(!workBox){return;}var sc=sch&&S[sch.value],many=manyMode()&&(!sc||sc.type==='percent'||sc.type==='slab');
          if(!bulk){bulk=document.createElement('fieldset');bulk.className='form-section';bulk.id='ce-bulk';bulk.style.cssText='border:2px dashed #1F3A5F;border-radius:10px;padding:10px 14px';
            bulk.innerHTML='<legend style="font-weight:700;color:#1F3A5F;padding:0 6px">Many employees — enter each Target Achieved in the bulk sheet</legend>'
              +'<p style="margin:4px 0 8px">Employee is ALL — one Target Achieved cannot be typed for everyone. Pick one employee to enter theirs here, or download the sample for the scheme: it lists every employee the scheme is for (its Who it is for in Commission Setup) with the scheme\'s calculation built in. Fill each person\'s Target Achieved and upload it; if any cell is wrong nothing is imported and the row and cell are named.</p>'
              +'<button type="button" class="btn btn-outline" id="ce-bulk-dl"><i class="fas fa-file-excel"></i> Download bulk sample for this scheme</button> '
              +'<button type="button" class="btn btn-outline" id="ce-bulk-up"><i class="fas fa-upload"></i> Upload the filled sheet</button>';
            workBox.parentNode.insertBefore(bulk,workBox.nextSibling);
            document.getElementById('ce-bulk-dl').onclick=function(){var s2=sch&&S[sch.value];if(!s2){window.ceSchemePop(sch);sch.focus();return;}
              var hf=document.getElementById('ce-sample-form');if(!hf){return;}
              hf.querySelector('[name=scheme_id]').value=sch.value;hf.querySelector('[name=month]').value=(el('month')&&el('month').value)||hf.querySelector('[name=month]').value;
              hf.querySelector('[name=employer_company_id]').value=co?co.value:'';hf.querySelector('[name=branch_id]').value=br?br.value:'';hf.submit();};
            document.getElementById('ce-bulk-up').onclick=function(){var up=document.querySelector('#ce-import-form [name=sheet]');if(up){up.scrollIntoView({block:'center'});up.click();}};}
          bulk.style.display=many?'':'none';workBox.style.display=many?'none':'';
          subs.forEach(function(b){if(many){b.disabled=true;b.title='Many employees — use the bulk sample';}else if(b.title.indexOf('bulk sample')>=0){b.disabled=false;b.title='';}});}
        function all(){lockEmp();schemeList();calc();targetBox();fixedGuard();payDate();boxes();bulkPanel();}
        sch&&sch.addEventListener('change',function(){fromScheme();});
        fm.addEventListener('change',function(){setTimeout(all,0);});
        fm.addEventListener('input',function(ev){if(ev.target!==gross&&ev.target!==rate&&ev.target!==base){return;}calc();targetBox();fixedGuard();});
        fm.addEventListener('submit',function(ev){if(fixedGuard()){ev.preventDefault();return;}var s3=sch&&S[sch.value];if(manyMode()&&(!s3||s3.type==='percent'||s3.type==='slab')){ev.preventDefault();window.ceSchemePop(document.getElementById('ce-bulk-dl')||sch,'Many employees — download the bulk sample for the scheme, fill each Target Achieved and upload it.');return;}emp&&(emp.disabled=false);});
        all();setTimeout(all,0);})();</script>
