<?php
    // A PICKER IS A LIST. Every one of these enumerated every employee in the
    // tenant — name and code, handed over — while the screen behind it refused a
    // colleague's row. The refusal was worth nothing with the directory printed
    // above it, and a scope sweep found all three the same way: the leak was
    // there whatever the parameter said, because it was not the parameter
    // leaking. `Scope::only()` narrows the list to the rows this account may
    // read, and returns it untouched for somebody who may read others.
    $dirFilter = orgFilter();
    // ARCHIVED EMPLOYMENTS LIVE ON BACKED UP / OLD DATA, not here.
    $dirScoped = array_values(array_filter($scope->only($store->all('employees'), $may('employee.list')),
        static fn (array $e): bool => trim((string) ($e['archived_at'] ?? '')) === '' && trim((string) ($e['deleted_at'] ?? '')) === ''));
    // CATEGORY FILTERS (owner, 5 Nov 2026): Salary Type, Employee Type and Staff Type — any one picked
    // narrows the cards, the company / branch buttons and the list to that category. Label and list come from the
    // Employee fields register, plus any value already on file; a field not in use is not offered.
    $dirCat = [];
    $dirCatHtml = '';
    $dirCatQuery = '';
    $dirCatFields = [];
    foreach ($employeeFields->inUse() as $dcF) { $dirCatFields[(string) $dcF['code']] = $dcF; }
    // Employee Stage is NOT offered (owner, 5 Nov): nothing in SmartPRS3 reads it — a SmartPRS2 leftover that repeats Employee Type.
    foreach (['salary_type', 'employment_type', 'type'] as $dcCode) {
        if (!isset($dirCatFields[$dcCode])) { continue; }
        $dcF = $dirCatFields[$dcCode];
        $dcCol = (string) ($dcF['column'] ?? $dcCode);
        $dcOpts = [];
        // A FIELD WITH ITS OWN LIST OFFERS ONLY THAT LIST (owner, 5 Nov: Employee Type = its six options, never a stray saved value).
        foreach ((array) ($dcF['options'] ?? []) !== [] ? (array) $dcF['options'] : array_map(static fn (array $e): string => trim((string) ($e[$dcCol] ?? '')), $dirScoped) as $dcO) {
            ($dcO = trim((string) $dcO)) === '' || $dcOpts[strtolower($dcO)] ??= $dcO;
        }
        $dcPick = trim((string) ($_GET['c_' . $dcCode] ?? ''));
        $dcPick === '' || $dirCat[$dcCol] = $dcPick;
        $dcPick === '' || $dirCatQuery .= '&amp;c_' . $dcCode . '=' . e(rawurlencode($dcPick));
        $dirCatHtml .= '<div><label for="dc_' . $dcCode . '">' . e((string) $dcF['label']) . '</label><select id="dc_' . $dcCode . '" name="c_' . $dcCode . '"><option value="">ALL</option>';
        foreach ($dcOpts as $dcO) { $dirCatHtml .= '<option' . (strcasecmp($dcO, $dcPick) === 0 ? ' selected' : '') . '>' . e($dcO) . '</option>'; }
        $dirCatHtml .= '</select></div>';
    }
    foreach ($dirCat as $dcCol => $dcPick) {
        $dirScoped = array_values(array_filter($dirScoped, static fn (array $e): bool => strcasecmp(trim((string) ($e[$dcCol] ?? '')), $dcPick) === 0));
    }
    $dirOptions = orgFilterOptions($store, $dirScoped);
    $employments = orgFilterApply($store, $dirScoped, $dirFilter);
    // A BRANCH PICKED ALSO LISTS WHO HANDLES IT (owner, 26 Oct), after the people whose Home branch it is.
    $dirHandles = [];
    if ($dirFilter['branch'] !== '') {
        $dirBrIds = array_keys(array_filter((array) (employeeLookups($store)['branches'] ?? []), static fn ($n): bool => strcasecmp((string) $n, $dirFilter['branch']) === 0));
        $dirIn = array_flip(array_map(static fn (array $e): string => (string) $e['id'], $employments));
        foreach (orgFilterApply($store, $dirScoped, array_merge($dirFilter, ['branch' => ''])) as $dirE) {
            if (!isset($dirIn[(string) $dirE['id']]) && array_intersect(array_map('strval', $dirBrIds),
                branchAdminBranches((string) ($employeeExtras->forEmployment(Employment::code($dirE))['admin_branches'] ?? ''))) !== []) {
                $employments[] = $dirE;
                $dirHandles[Employment::code($dirE)] = true;
            }
        }
    }
    // TICKED EMPLOYEES (owner, 13 Oct): "View selected" narrows the list to the ticked rows.
    $dirSel = array_values(array_filter(array_map('trim', explode(',', (string) ($_GET['sel'] ?? '')))));
    if ($dirSel !== []) {
        $employments = array_values(array_filter($employments, static fn (array $e): bool => in_array(Employment::code($e), $dirSel, true)));
    }
    // BACK TO THE DIRECTORY from a profile: the other filters stay, the employee pick goes.
    $dirBack = '?r=employees' . orgFilterQuery(array_merge($dirFilter, ['employee' => ''])) . $dirCatQuery;
    // ONE EMPLOYEE IN VIEW = A PROFILE PAGE, sectioned like the form, instead of a row to scroll sideways.
    $dirNarrowed = $dirSel !== [] || array_filter($dirFilter) !== [] || $dirCat !== [];
    // …only when a PERSON was picked — the Employee box or ticked rows (owner, 5 Nov 2026). Any other filter (Staff Type,
    // Department…) or a company with a single employee shows the table; "Back to Directory" (which drops the pick) always
    // lands on the table instead of the same profile again.
    $dirSingle = ($dirFilter['employee'] !== '' || $dirSel !== []) && count($employments) === 1 ? array_values($employments)[0] : null;
    $tints = ['#f97316', '#3b82f6', '#10b981', '#8b5cf6', '#f59e0b', '#ef4444'];
    // THE STAFF-COST TOTAL, IN PAISE. It was a float accumulator: ₹4.2 crore
    // summed one contract at a time in binary, printed to the rupee on the page
    // header. Money::sum() over exact amounts instead — the figure a person
    // reconciles against their own spreadsheet has to be the figure, not a very
    // close one.
    $grossTotal = Money::zero();
    $departments = [];

    foreach ($employments as $employment) {
        $grossTotal = $grossTotal->plus(Money::of(Employment::ctc($employment)));

        if ((string) ($employment['department'] ?? '') !== '') {
            $departments[(string) $employment['department']] = true;
        }
    }
    // A REPORTING RING, NAMED. Scope denies the line through it rather than
    // crashing the page; this says which rows to fix.
    $dirRings = (new SmartPRS\Surface\ReportingLines($store))->cycles();
?>
<?php if ($dirRings !== [] && $may('employee.update')): ?>
  <div class="problem" style="margin-bottom:12px"><b>Reporting loop in the org chart.</b>
    Managers cannot see these people through their reporting line until it is fixed &mdash; edit one of them and change their Reporting manager:
    <?php foreach ($dirRings as $ring): ?><div>&bull; <?= implode(' &rarr; ', array_map('e', $ring['members'])) ?><?= count($ring['members']) === 1 ? ' (reports to themselves)' : '' ?></div><?php endforeach; ?>
  </div>
<?php endif; ?>

<?php
    // THE DIRECTORY'S NUMBERS (owner, 13 Oct): total, active, branches, departments (and the payroll
    // figure for those who may see it) — for whatever the filters below have selected.
    $dcActive = count(array_filter($employments, static fn (array $e): bool => in_array(strtolower(trim((string) ($e['status'] ?? 'active'))), ['active', ''], true)));
    $dcBranches = count(array_unique(array_filter(array_map(static fn (array $e): string => orgValueOf($store, $e, 'branch'), $employments))));
    $dcDepts = count(array_unique(array_filter(array_map(static fn (array $e): string => orgValueOf($store, $e, 'department'), $employments))));
    $dcCompanies = count(array_unique(array_filter(array_map(static fn (array $e): string => orgValueOf($store, $e, 'company'), $employments))));
    $dcTotal = count($employments);
    // BRAND COLOURED, FROM THE START (owner, 13 Oct): every card shows each company's share in that
    // company's own colour (Organization Configuration → Companies) — a split bar and a breakdown —
    // and its icon wears those colours. With one company picked, the card is that company's colour.
    $dcBy = [];
    foreach ($employments as $e) {
        $co = orgValueOf($store, $e, 'company') ?: 'No company';
        $dcBy[$co]['total'] = ($dcBy[$co]['total'] ?? 0) + 1;
        $dcBy[$co]['active'] = ($dcBy[$co]['active'] ?? 0) + (in_array(strtolower(trim((string) ($e['status'] ?? 'active'))), ['active', ''], true) ? 1 : 0);
        ($b = orgValueOf($store, $e, 'branch')) === '' || $dcBy[$co]['branches'][$b] = true;
        ($d = orgValueOf($store, $e, 'department')) === '' || $dcBy[$co]['depts'][$d] = true;
    }
    // BRANCHES AND DEPARTMENTS ARE WHAT ORGANIZATION SETUP HOLDS (owner, 5 Nov 2026: a branch added there still showed
    // 0 here, because these two cards counted only branches / departments that employees sit in). Now: every branch and
    // department set up, within the Company / Branch / Department picked — with or without staff in it.
    $dcOrg = orgNames($store);
    $dcIs = static fn (string $want, string $have): bool => $want === '' || strcasecmp($want, $have) === 0;
    $dcBrCo = [];
    foreach ($dcBy as $dcCoK => $dcV) { unset($dcBy[$dcCoK]['branches'], $dcBy[$dcCoK]['depts']); }
    foreach (liveRows($store, 'branches') as $dcB) {
        $dcCoN = (string) ($dcOrg['companies'][(string) ($dcB['employer_company_id'] ?? '')] ?? '');
        $dcBrCo[(string) $dcB['id']] = $dcCoN;
        $dcBN = trim((string) ($dcB['name'] ?? ''));
        if ($dcBN === '' || !$dcIs($dirFilter['company'], $dcCoN) || !$dcIs($dirFilter['branch'], $dcBN)) { continue; }
        $dcBy[$dcCoN ?: 'No company']['branches'][$dcBN] = true;
    }
    foreach (liveRows($store, 'departments') as $dcD) {
        $dcCoN = (string) ($dcOrg['companies'][(string) ($dcD['employer_company_id'] ?? '')] ?? '') ?: (string) ($dcBrCo[(string) ($dcD['branch_id'] ?? '')] ?? '');
        $dcDN = trim((string) ($dcD['name'] ?? ''));
        if ($dcDN === '' || !$dcIs($dirFilter['company'], $dcCoN) || !$dcIs($dirFilter['department'], $dcDN)
            || ($dirFilter['branch'] !== '' && (string) ($dcD['branch_id'] ?? '') !== '' && !$dcIs($dirFilter['branch'], (string) ($dcOrg['branches'][(string) $dcD['branch_id']] ?? '')))) { continue; }
        $dcBy[$dcCoN ?: 'No company']['depts'][$dcDN] = true;
    }
    $dcBranches = array_sum(array_map(static fn (array $v): int => count((array) ($v['branches'] ?? [])), $dcBy));
    $dcDepts = array_sum(array_map(static fn (array $v): int => count((array) ($v['depts'] ?? [])), $dcBy));
    // NEVER A "NO COMPANY" LINE (owner, 5 Nov 2026): a department set up for no particular company (blank = every company)
    // belongs, in a one-company setup, to that company; with several companies it counts in the total only.
    if (isset($dcBy['No company'])) {
        $dcCoNames = array_values(array_filter(array_map(static fn (array $c): string => trim((string) ($c['name'] ?? '')), liveRows($store, 'companies'))));
        if (count($dcCoNames) === 1) {
            foreach ($dcBy['No company'] as $dcK => $dcV) {
                $dcBy[$dcCoNames[0]][$dcK] = is_array($dcV) ? ((array) ($dcBy[$dcCoNames[0]][$dcK] ?? [])) + $dcV : (int) ($dcBy[$dcCoNames[0]][$dcK] ?? 0) + (int) $dcV;
            }
        }
        unset($dcBy['No company']);
    }
    uksort($dcBy, 'strnatcasecmp');
    $dcSplit = static fn (string $metric): array => array_map(static fn (array $v): int => is_array($v[$metric] ?? null) ? count($v[$metric]) : (int) ($v[$metric] ?? 0), $dcBy);
    $dcColors = array_map(static fn (string $co): string => companyColor($store, $co), array_combine(array_keys($dcBy), array_keys($dcBy)) ?: []);
    $dcIcBg = count($dcColors) > 1 ? 'linear-gradient(135deg,' . implode(',', array_values($dcColors)) . ')' : (array_values($dcColors)[0] ?? 'var(--accent)');
    $dcMain = count($dcColors) === 1 ? array_values($dcColors)[0] : 'var(--accent)';
    $dcCards = [
        ['fa-users', 'Total employees', number_format($dcTotal), $dcSplit('total'), 'var(--accent)'],
        ['fa-user-check', 'Active employees', number_format($dcActive), $dcSplit('active'), 'var(--green)'],
        ['fa-building', 'Branches', number_format($dcBranches), $dcSplit('branches'), 'var(--blue)'],
        ['fa-sitemap', 'Departments', number_format($dcDepts), $dcSplit('depts'), 'var(--purple)'],
    ];
    // payroll totals live on the Live Salary tab (owner, 13 Oct), not here.
?>
