      <div class="dc-leg"><?php foreach ($dcParts as $dcCo => $dcN): ?><div><i style="background:<?= $dcColors[$dcCo] ?>"></i><span><?= e((string) $dcCo) ?></span><b><?= $dcN ?></b></div><?php endforeach; ?></div>
