  <?php // CARDS FIRST, THEN THE FILTERS (owner, 13 Oct). ?>
<?php
    // COMPANY AND BRANCH AS BUTTONS (owner, 13 Oct): one click filters the cards and the table.
    // Branch buttons are the chosen company's branches; changing company clears the branch.
    $chHref = static fn (array $over): string => '?r=employees' . orgFilterQuery(array_merge($dirFilter, ['employee' => ''], $over)) . $dirCatQuery;
    $chCount = static function (string $k, ?string $company = null) use ($dirScoped, $store): array {
        $n = [];
        foreach ($dirScoped as $e) {
            if ($company !== null && $company !== '' && strcasecmp(orgValueOf($store, $e, 'company'), $company) !== 0) { continue; }
            $v = orgValueOf($store, $e, $k);
            $v === '' || $n[$v] = ($n[$v] ?? 0) + 1;
        }
        ksort($n, SORT_NATURAL | SORT_FLAG_CASE);
        return $n;
    };
    $chCo = $chCount('company');
    $chBr = $chCount('branch', $dirFilter['company']);
    // ONE COLOUR PER COMPANY, from the theme (owner, 13 Oct) — the same hues, in the same order, as
    // People → Hierarchy, so a company reads the same on both. A branch wears its company's colour.
    $chCoNames = array_keys($chCount('company'));
    $chCoColor = static fn (string $co): string => companyColor($store, $co);
    $chBrCo = [];
    foreach ($dirScoped as $chE) { $chB = orgValueOf($store, $chE, 'branch'); $chB === '' || $chBrCo[$chB] ??= orgValueOf($store, $chE, 'company'); }
    $chAllColor = $dirFilter['company'] !== '' ? $chCoColor((string) (array_values(array_filter($chCoNames, static fn ($n): bool => strcasecmp((string) $n, $dirFilter['company']) === 0))[0] ?? '')) : 'var(--text2)';
    $chCoTotal = count($dirScoped);
    $chBrTotal = array_sum($chBr);
?>
