<?php if ($dirSingle !== null):
    // ONE EMPLOYEE, ONE PAGE (owner, 13 Oct): every configured field, grouped by section like the
    // form, with the photo, the key facts and the actions on top — no sideways scrolling.
    $pe = $dirSingle;
    $peHeld = $employeeExtras->forEmployment(Employment::code($pe));
    $peLookups = employeeLookups($store);
    $peSections = [];
    foreach ($employeeFields->inUse() as $peF) {
        if (in_array((string) $peF['code'], ['emp_code', 'name', 'photo_path'], true) || (string) ($peF['type'] ?? '') === 'Image/PDF/Doc') { continue; }
        if ((string) $peF['code'] === 'ctc' && !$may('employee.salary.view')) { continue; }
        $peV = ($peF['storage'] ?? 'column') === 'extra' ? (string) ($peHeld[(string) $peF['code']] ?? '') : (string) ($pe[(string) ($peF['column'] ?? '')] ?? '');
        if ((string) $peF['code'] === 'role' && $peV === '') { $peV = orgValueOf($store, $pe, 'role'); }
        $peV = $statutoryApplicability->governmentAnswer($pe, (string) $peF['code']) ?: $peV;
        $peV = ($peF['control'] ?? '') === 'lookup' ? (string) ($peLookups[(string) $peF['lookup']][$peV] ?? $peV) : capDecimals(yesNoOf($peF, $peV));
        if ((string) $peF['code'] === 'branch_id' && ($peMore = otherBranchNames($peHeld, (array) ($peLookups['branches'] ?? []), (string) ($pe['branch_id'] ?? ''))) !== []) { $peV .= ' (home) + ' . implode(', ', $peMore); }
        if ((string) $peF['code'] === 'ctc' && $peV !== '') { $peV = Money::of(Employment::ctc($pe))->format(); }
        if ((string) ($peF['type'] ?? '') === 'Date' && preg_match('/^\d{4}-\d{2}-\d{2}/', $peV) === 1) { $peV = SmartPRS\Surface\Dates::dmy(substr($peV, 0, 10)); }
        $peSections[(string) ($peF['section'] ?? 'Other')][] = [(string) $peF['label'], $peV];
    }
    $pePhoto = trim((string) ($pe['photo_path'] ?? ''));
    $peActive = in_array(strtolower(trim((string) ($pe['status'] ?? 'active'))), ['active', ''], true);
?>
