    // THE FORM IS THE FIELD REGISTER. It used to be seven inputs written into
    // this file, so a customer who kept a father's name or a UAN could not
    // record one without a release. What is below is whatever this tenant ticked
    // on the Employee fields screen, grouped the way a personnel file is.
    $addFields = $employeeFields->inUse();
    $addLookups = employeeLookups($store);
    $grouped = [];
    // EDIT IS THE SAME FORM, PRE-FILLED. ?edit=<id> on the Directory opens it
    // with the record's values — the configured fields, not a generic column list.
    $editPick = (string) ($_GET['edit'] ?? $_GET['id'] ?? '');
    $editRow = $editPick === '' ? null : $store->find('employees', $editPick);
    $editRow = $editRow !== null && $scope->covers((string) $editRow['id'], $may('employee.list')) && $may('employee.update') ? $editRow : null;
    $editExtras = $editRow === null ? [] : $employeeExtras->forEmployment(Employment::code($editRow));
    $editValue = static function (array $f) use ($editRow, $editExtras, $store, $statutoryApplicability): string {
        if ($editRow === null) { return post('f_' . (string) $f['code']); }
        // PF / ESIC APPLICABLE FOLLOW THE GOVERNMENT RULE (owner, 16 Oct) — payroll reads the same answer.
        if (($gov = $statutoryApplicability->governmentAnswer($editRow, (string) $f['code'])) !== '') { return $gov; }
        // A REFUSED EDIT KEEPS WHAT WAS TYPED (13 Oct): re-showing the record as filed
        // threw away every change along with the reason it was refused.
        if (post('action') === 'update-employee' && isset($_POST['f_' . (string) $f['code']]) && trim(post('f_' . (string) $f['code'])) !== '') {
            return post('f_' . (string) $f['code']);
        }
        // NO MANAGER ON FILE BUT PEOPLE REPORT TO THEM: that is the top of the
        // organisation, so the form says so instead of demanding a pick again.
        if ((string) ($f['none_option']['value'] ?? '') !== '' && ($f['storage'] ?? 'column') === 'column'
            && trim((string) ($editRow[(string) $f['column']] ?? '')) === ''
            && hasDirectReports($store, (string) ($editRow['id'] ?? ''))) {
            return (string) $f['none_option']['value'];
        }
        return yesNoOf($f, ($f['storage'] ?? 'column') === 'column' ? (string) ($editRow[(string) $f['column']] ?? '') : (string) ($editExtras[(string) $f['code']] ?? ''));
    };

    foreach ($addFields as $addField) {
        $grouped[(string) $addField['section']][] = $addField;
    }
