      // cascade, the required check and the save are unchanged; the other ticked branches post as admin_branches[].
      $baChosen = $editRow === null ? array_map('strval', (array) ($_POST['admin_branches'] ?? []))
          : branchAdminBranches((string) ($editExtras['admin_branches'] ?? ''));
?>
      <input type="hidden" name="admin_branches_present" value="1">
      <style>
        .mb-hidden-select{position:absolute!important;opacity:0!important;pointer-events:none!important;width:1px!important;height:1px!important;min-width:0!important;max-width:1px!important}
        .mb-pick{position:relative}
        .mb-btn{width:100%;min-height:36px;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card,#fff);color:var(--text1);font:inherit;font-size:13px;cursor:pointer}
        .mb-btn::after{content:"▾";color:var(--text3)}
        .mb-panel{position:absolute;z-index:50;left:0;top:calc(100% + 4px);min-width:100%;max-height:280px;overflow:auto;background:var(--card,#fff);border:1px solid var(--border);border-radius:10px;box-shadow:0 12px 28px -12px rgba(15,23,42,.35);padding:6px}
        .mb-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:5px 8px;border-radius:6px;font-size:13px;white-space:nowrap}
        .mb-row:hover{background:var(--bg)}
        .mb-row label{display:flex;align-items:center;gap:7px;margin:0;font-weight:500;cursor:pointer}
        .mb-all{border-bottom:1px solid var(--border);margin-bottom:4px;padding-bottom:7px}
        .mb-home{font-size:11.5px;color:var(--text3)}
      </style>
      <script>
        (function () {
          var sel = document.getElementById('ef-branch_id');
          if (!sel) { return; }
          var held = <?= json_encode(array_values($baChosen), JSON_HEX_TAG | JSON_HEX_AMP) ?>, ticked = {}, busy = false;
          if (sel.value) { ticked[sel.value] = 1; }
          held.forEach(function (id) { ticked[id] = 1; });
          var box = document.createElement('div');
          box.className = 'mb-pick';
          box.innerHTML = '<button type="button" class="mb-btn"><span></span></button><div class="mb-panel" hidden></div><div class="mb-posted"></div>';
          sel.parentNode.insertBefore(box, sel.nextSibling);
          sel.classList.add('mb-hidden-select');
          sel.tabIndex = -1;
          var btn = box.querySelector('.mb-btn'), panel = box.querySelector('.mb-panel'), posted = box.querySelector('.mb-posted');
          var esc = function (t) { var d = document.createElement('div'); d.textContent = t; return d.innerHTML; };
          var opts = function () { return [].filter.call(sel.options, function (o) { return o.value !== '' && !o.hidden; }); };
          var draw = function () {
            if (busy) { return; }
            busy = true;
            var list = opts(), ids = list.map(function (o) { return o.value; });
            Object.keys(ticked).forEach(function (id) { if (ids.indexOf(id) < 0) { delete ticked[id]; } });   // the company changed
            var home = ticked[sel.value] ? sel.value : (ids.filter(function (i) { return ticked[i]; })[0] || '');
            if (sel.value !== home) { sel.value = home; sel.dispatchEvent(new Event('change', {bubbles: true})); }
            var on = list.filter(function (o) { return ticked[o.value]; }), name = function (o) { return o.textContent.trim(); };
            var others = on.filter(function (o) { return o.value !== home; }).map(name);
            btn.firstChild.textContent = home === '' ? 'Not set' : (on.length > 1 && on.length === list.length ? 'All Branches (home: ' + name(sel.options[sel.selectedIndex]) + ')'
              : name(sel.options[sel.selectedIndex]) + (others.length ? ' (home) + ' + others.join(', ') : ''));
            panel.innerHTML = '<div class="mb-row mb-all"><label><input type="checkbox" data-mb-all' + (list.length && on.length === list.length ? ' checked' : '') + '> <b>All Branches</b></label></div>'
              + list.map(function (o) {
                return '<div class="mb-row"><label><input type="checkbox" data-mb="' + esc(o.value) + '"' + (ticked[o.value] ? ' checked' : '') + '> ' + esc(name(o)) + '</label>'
                  + '<label class="mb-home"><input type="radio" name="mb_home_ui" data-mb-home="' + esc(o.value) + '"' + (o.value === home ? ' checked' : '') + (ticked[o.value] ? '' : ' disabled') + '> Home</label></div>';
              }).join('');
            posted.innerHTML = others.length ? on.filter(function (o) { return o.value !== home; }).map(function (o) { return '<input type="hidden" name="admin_branches[]" value="' + esc(o.value) + '">'; }).join('') : '';
            busy = false;
          };
          btn.addEventListener('click', function () { panel.hidden = !panel.hidden; });
          document.addEventListener('click', function (ev) { if (!box.contains(ev.target)) { panel.hidden = true; } });
          panel.addEventListener('change', function (ev) {
            var t = ev.target;
            ev.stopPropagation();
            if (t.hasAttribute('data-mb-all')) {
              opts().forEach(function (o) { t.checked ? ticked[o.value] = 1 : delete ticked[o.value]; });
            } else if (t.hasAttribute('data-mb')) {
              t.checked ? ticked[t.getAttribute('data-mb')] = 1 : delete ticked[t.getAttribute('data-mb')];
            } else if (t.hasAttribute('data-mb-home')) {
              sel.value = t.getAttribute('data-mb-home'); sel.dispatchEvent(new Event('change', {bubbles: true}));
            }
            draw();
          });
          // the org cascade narrows the list when Company changes: redraw after it has run
          (sel.form || document).addEventListener('change', function (ev) { if (ev.target !== sel && !panel.contains(ev.target)) { setTimeout(draw, 0); } });
          sel.addEventListener('invalid', function () { btn.style.borderColor = '#dc2626'; });
          draw();
        })();
      </script>
      <button class="go" type="submit"><i class="fas <?= $editRow === null ? 'fa-user-plus' : 'fa-check' ?>"></i> <?= $editRow === null ? 'Add New Employee' : 'Save Employee' ?></button>
<?php if ($editRow !== null): ?> <a class="btn btn-outline" href="?r=employees">Cancel</a><?php endif; ?>
