  <script>
    (function () {
      var form = document.getElementById('add-employment');
      var link = document.getElementById('add-employee-link');
      if (!form || !link) { return; }
      link.addEventListener('click', function () { form.open = true; });
      if (location.hash === '#add-employment') { form.open = true; }
    })();
    (function () {
      var head = document.getElementById('emp-form-head'), box = document.getElementById('add-employment');
      var code = document.getElementById('employee_code');
      if (!head || !box || !code) { return; }
      var float = document.getElementById('emp-form-float');
      var adding = <?= $editRow === null ? 'true' : 'false' ?>;
      // ADD: the pinned row's Code / Name boxes and the form's own, kept in step both ways.
      document.querySelectorAll('#emp-form-float [data-mirror]').forEach(function (m) {
        var real = document.getElementById(m.getAttribute('data-mirror'));
        if (!real) { return; }
        m.value = real.value;
        m.addEventListener('input', function () { real.value = m.value; });
        real.addEventListener('input', function () { m.value = real.value; });
      });
      // ADD pins once the Code / Name row has scrolled away; EDIT once its header has.
      var anchor = adding ? (code.closest('.row') || head) : head;
      // the buttons sit inside <summary>: act here so a click never folds the form
      document.querySelectorAll('[data-emp-save]').forEach(function (b) { b.addEventListener('click', function (ev) { ev.preventDefault(); document.getElementById('emp-form').requestSubmit(); }); });
      // CANCEL ASKS FIRST (owner, 5 Nov 2026): nothing typed is lost by a stray click.
      document.querySelectorAll('[data-emp-close]').forEach(function (a) { a.addEventListener('click', function (ev) { ev.preventDefault();
        if (!window.confirm(adding ? 'Cancel adding this employee?\n\nNothing you have typed in this form will be saved.' : 'Cancel editing this employee?\n\nChanges you have not saved will be lost.')) { return; }
        location.href = this.href; }); });
      // the line the pinned row hangs from: the bottom of the sticky figure cards, else of the top bar
      var limit = function () {
        var t = document.querySelector('.tiles-fixed') || document.querySelector('.topbar');
        return t ? Math.max(0, t.getBoundingClientRect().bottom) : 0;
      };
      var place = function () {
        if (!float) { return; }
        var r = box.getBoundingClientRect(), top = limit() + 6;
        var show = box.open && anchor.getBoundingClientRect().bottom < top && r.bottom > top + 60;
        float.style.display = show ? 'flex' : 'none';
        if (show) { float.style.top = top + 'px'; float.style.left = r.left + 'px'; float.style.width = r.width + 'px'; }
      };
      window.addEventListener('scroll', place, { passive: true, capture: true });
      window.addEventListener('resize', place);
      // CURSOR IN CODE (owner, 2 Nov): after the page's own deep-link jump, the header lands just under the cards.
      box.addEventListener('toggle', place);
      if (adding) { return; }
      window.addEventListener('load', function () {
        setTimeout(function () {
          box.open = true;
          for (var k = 0; k < 2; k++) { window.scrollBy(0, head.getBoundingClientRect().top - limit() - 8); }
          code.focus({ preventScroll: true });
          place();
        }, 0);
      });
    })();
  </script>
<?php endif; ?>

