<?php foreach ($apSteps as $apS): $apSigner = regStepSigner($apRun, $apS); ?>
          <td class="note"><?php if ($apSigner !== null): ?><?= e($apSigner['name']) ?><br><span style="font-size:11px"><?= e(substr($apSigner['at'], 0, 10)) ?></span><?php else: ?>&mdash;<?php endif; ?></td>
