<?php elseif (!$may('payroll.structure.publish')): ?>
  <div class="card" style="padding:0">
    <div class="table-wrap">
      <table>
        <thead><tr><th>Component</th><th>Calculation</th><th>Applies to</th><th class="n">Rate</th>
          <th>Detail</th></tr></thead>
        <tbody>
<?php   foreach ($ruleRows as $row): ?>
          <tr>
            <td><code><?= e((string) $row['component_code']) ?></code></td>
            <td><?= e((string) $row['calculation']) ?></td>
            <td class="note"><?= e(implode(' · ', array_filter([
                  (string) ($row['scope_company'] ?? ''), (string) (((array) $row['detail'])['scope_city'] ?? ''), (string) ($row['scope_branch'] ?? ''),
                  (string) ($row['scope_role'] ?? ''), (string) ($row['scope_team'] ?? ''),
                  (string) ($row['scope_designation'] ?? ''), (string) ($row['scope_employee'] ?? '')]))) ?: 'everybody' ?></td>
            <td class="n" style="font-family:var(--mono)"><?= (string) ($row['percent_value'] ?? '')
                  !== '' ? e((string) $row['percent_value']) . '%'
                  : (e((string) ($row['flat_amount'] ?? '')) ?: '—') ?></td>
            <td class="note" style="font-family:var(--mono);font-size:12px"><?=
                  e((string) (((array) $row['detail'])['formula_text'] ?? '')) ?: '—' ?></td>
          </tr>
<?php   endforeach; ?>
<?php   if ($ruleRows === []): ?>
          <tr><td colspan="5" class="note">No component rules are in force. That is not the same as
              "every component applies to everybody" — it means nothing here has been configured
              yet.</td></tr>
<?php   endif; ?>
        </tbody>
      </table>
