    font-style:italic;
    cursor:help;
    vertical-align:middle;
  }#pf-app .info-icon:hover, #pf-app .info-icon:focus-visible{ background:var(--accent); outline:none; }#pf-app /* ---------- context bar ---------- */
  .context-bar{
