    box-shadow:0 0 0 3px rgba(51,81,125,0.15);
  }#pf-app .field.company select{ min-width:130px; }#pf-app .field.branch select{ min-width:130px; }#pf-app .field.team select{ min-width:150px; }#pf-app .field.role select{ min-width:150px; }#pf-app .field.designation select{ min-width:150px; }#pf-app /* Highlight filled scope selectors so the active selection is obvious */
  select.sel-company, #pf-app select.sel-branch, #pf-app select.sel-team, #pf-app select.sel-role, #pf-app select.sel-designation{
    transition:background .12s ease, border-color .12s ease, color .12s ease;
  }#pf-app select.sel-company.is-filled{ background:var(--company-fill); border-color:var(--company-border); color:var(--company-text); font-weight:700; box-shadow:inset 0 0 0 1px currentColor; }#pf-app select.sel-branch.is-filled{ background:var(--branch-fill); border-color:var(--branch-border); color:var(--branch-text); font-weight:700; box-shadow:inset 0 0 0 1px currentColor; }#pf-app select.sel-team.is-filled{ background:var(--team-fill); border-color:var(--team-border); color:var(--team-text); font-weight:700; box-shadow:inset 0 0 0 1px currentColor; }#pf-app select.sel-role.is-filled{ background:var(--role-fill); border-color:var(--role-border); color:var(--role-text); font-weight:700; box-shadow:inset 0 0 0 1px currentColor; }#pf-app select.sel-designation.is-filled{ background:var(--designation-fill); border-color:var(--designation-border); color:var(--designation-text); font-weight:700; box-shadow:inset 0 0 0 1px currentColor; }#pf-app .jump-field select{ min-width:220px; font-weight:600; }#pf-app .context-match{
    margin-left:auto;
