  }#pf-app .new-format-btn:hover{ background:var(--add); color:#fff; }#pf-app .formats-list{
    display:flex;
    flex-direction:column;
    gap:6px;
  }#pf-app .format-row{
    display:flex;
    align-items:center;
    gap:8px;
