    border:1px solid var(--border-soft);
    border-radius:7px;
    cursor:pointer;
    background:var(--panel-bg);
    transition:border-color .12s ease, background .12s ease;
  }#pf-app .format-row:hover{ border-color:#B9C1CD; }#pf-app .format-row.active{
    border-color:var(--accent);
