  }#pf-app .editor-head-left{ display:flex; align-items:center; gap:10px; flex-wrap:wrap; flex:1; min-width:280px; }#pf-app .name-input{ font-weight:700; font-size:13px; min-width:220px; flex:1; }#pf-app .scope-row{
