  }#pf-app .btn:hover{ border-color:#B9C1CD; }#pf-app .btn.primary{ background:var(--accent); border-color:var(--accent); color:#fff; }#pf-app .btn.primary:hover{ background:var(--accent-dark); }#pf-app .btn.ghost{ border-style:dashed; color:var(--ink-soft); }#pf-app .btn.danger:hover{ border-color:var(--deduction); color:var(--deduction); background:var(--deduction-bg); }#pf-app /* ---------- component sections ---------- */
  .section-block{ margin-bottom:14px; }#pf-app .section-title{
