  }#pf-app .order-btn:hover:not(:disabled){ border-color:var(--accent); color:var(--accent); }#pf-app .order-btn:disabled{ opacity:.3; cursor:not-allowed; }#pf-app .totals-hint{
    display:flex;
    justify-content:space-between;
    font-size:11px;
    color:var(--ink-soft);
    padding:6px 8px 0;
