};
/* ===================== Data ===================== */

// THE COMPONENT LIBRARY, THE COMPANIES, THE BRANCHES, THE TEAMS AND THE
// DESIGNATIONS ARE NOT WRITTEN HERE ANY MORE. The artefact listed one customer's
// own — four company names, four branches — and a component library in
// JavaScript. Here they are this tenant's Organization Setup records and
// config/salary-components.json, injected by the page, so a branch added under
// Organization Setup appears in these dropdowns and a payslip cannot be designed
// around a component payroll does not have.
const COMPONENT_LIBRARY = window.__PF.library;
const COMPANY_OPTIONS = window.__PF.scopes.company;
const BRANCH_OPTIONS = window.__PF.scopes.branch;
const TEAM_OPTIONS = window.__PF.scopes.team;
const DESIGNATION_OPTIONS = window.__PF.scopes.designation;
const COMPANY_LABEL = window.__PF.companyLabels;
const COMPANY_LOGO = window.__PF.companyLogos;
const COMPANY_ADDRESS = window.__PF.companyAddresses;
const COMPANY_COLOR = window.__PF.companyColors;
// THE APPLICATION'S OWN BRANDING — Organization Configuration → Companies'
// own top card ("Company Branding"), one setting for everyone signed in,
// separate from any one company's row below it. This is what an "All
// companies" format previews and prints with (the owner's own words), never
// a guess at which company row happens to be listed first.
const APP_BRAND = window.__PF.appBrand;
// A BRANCH, TEAM/DEPARTMENT OR DESIGNATION EACH BELONG TO EXACTLY ONE
// COMPANY — so a format scoped to "All companies" but a specific one of
// these still has a real company to brand as. Name => company name.
const BRANCH_COMPANY = window.__PF.branchCompany;
const TEAM_COMPANY = window.__PF.teamCompany;
const DESIGNATION_COMPANY = window.__PF.designationCompany;
// THE ACTIVE EMPLOYEE DIRECTORY, injected by the page — see window.__PF.employees
// above. One person picked here both scopes the format (PayslipFormats already
// understood an "employee" scope; only this screen never offered it) and fills
// the preview with their own facts, never invented ones.
const EMPLOYEES = window.__PF.employees;
const EMPLOYEE_BY_CODE = {};
EMPLOYEES.forEach(e => { EMPLOYEE_BY_CODE[e.code] = e; });
// ROLE, FROM Role/Designation Setup (Organization Configuration) — not the
// administrator/manager/viewer access tier Roles & Permissions enforces.
const ROLE_OPTIONS = window.__PF.roles;
const ROLE_LABEL = window.__PF.roleLabels;
const DESIGNATION_ROLE = window.__PF.designationRoles;

/* ===================== Helpers ===================== */

function uid(prefix){ return prefix + '_' + Math.random().toString(36).slice(2, 9); }

function makeComponentState(section){
  const out = {};
  COMPONENT_LIBRARY[section].forEach((c, i) => { out[c.id] = { checked: false, order: i + 1, amount: c.amount }; });
  return out;
}

function cloneEditor(fmt){ return JSON.parse(JSON.stringify(fmt)); }

function currencyFmt(n){
  const num = Number(n) || 0;
  return num.toLocaleString('en-IN', { maximumFractionDigits: 0 });
}

const ONES = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten',
  'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
const TENS = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

function twoDigits(n){
  if (n < 20) return ONES[n];
  return (TENS[Math.floor(n / 10)] + (n % 10 ? ' ' + ONES[n % 10] : '')).trim();
}
function threeDigits(n){
  const h = Math.floor(n / 100);
  const rest = n % 100;
  let s = '';
  if (h) s += ONES[h] + ' Hundred';
  if (rest) s += (s ? ' ' : '') + twoDigits(rest);
  return s;
}
function numberToWordsIndian(num){
  num = Math.round(Math.abs(num));
  if (num === 0) return 'Zero';
  const crore = Math.floor(num / 10000000); num %= 10000000;
  const lakh = Math.floor(num / 100000); num %= 100000;
  const thousand = Math.floor(num / 1000); num %= 1000;
  const hundred = num;
  let parts = [];
  if (crore) parts.push(threeDigits(crore) + ' Crore');
  if (lakh) parts.push(threeDigits(lakh) + ' Lakh');
  if (thousand) parts.push(threeDigits(thousand) + ' Thousand');
  if (hundred) parts.push(threeDigits(hundred));
  return parts.join(' ');
}
function amountInWords(n){
  return 'Rupees ' + numberToWordsIndian(Math.round(Number(n) || 0)) + ' Only';
}

function buildOptions(sel, values, withAll){
  let html = '';
  if (withAll) html += `<option value="All">All</option>`;
  values.forEach(v => { html += `<option value="${v}">${v}</option>`; });
  sel.innerHTML = html;
}

function buildLabeledOptions(sel, values, labels, withAll){
  let html = '';
  if (withAll) html += `<option value="All">All</option>`;
  values.forEach(v => { html += `<option value="${v}">${escapeHtml(labels[v] || v)}</option>`; });
  sel.innerHTML = html;
}

// DESIGNATION NARROWS TO THE SELECTED ROLE — Role/Designation Setup's own
// Role field on each designation, never a second list kept in step by hand.
// 'All' role shows every designation, exactly as before Role existed here.
function designationOptionsFor(role){
  return role === 'All' ? DESIGNATION_OPTIONS : DESIGNATION_OPTIONS.filter(d => DESIGNATION_ROLE[d] === role);
}

function refreshDesignationOptions(sel, role, keep){
  const opts = designationOptionsFor(role);
  buildOptions(sel, opts, true);
  sel.value = opts.includes(keep) ? keep : 'All';
}

/* ===================== State ===================== */

function defaultEditor(company){
  return {
    id: null,
    name: 'New Format',
    company: company || COMPANY_OPTIONS[0],
    branch: 'All',
    team: 'All',
    role: 'All',
    designation: 'All',
    employee: '',
    showEmployerSection: false,
    showLogo: true,
    showPan: true,
    showUan: true,
    showDesignation: true,
    showDoj: true,
    showCompanyAddress: false,
    showLocation: false,
    earning: makeComponentState('earning'),
    deduction: makeComponentState('deduction'),
    employer: makeComponentState('employer'),
  };
}

function seedFormats(){
  // EMPTY, NOT SEEDED. The artefact shipped three example formats belonging to a
  // named customer; inventing formats for somebody else's tenant is how demo
  // data reaches production.
  return [];
}

const state = {
  employeeName: 'Employee Name',
  employeeId: 'EMP-0421',
  payPeriod: (function(){ const d = new Date(); return d.toLocaleString('en-IN', { month: 'long' }) + ' ' + d.getFullYear(); })(),
  formats: seedFormats(),
  editor: null,
  editingExistingId: null,
  // THE CTC (LPA) BOX WHEN NO SPECIFIC EMPLOYEE IS PICKED — remembered across
  // switching formats so it does not blank itself out every click.
  previewCtcLpa: '',
  // THE LAST CALCULATED VALUES FROM THE SERVER — component code => decimal
  // amount, keyed the same as the checked amount inputs, plus the totals and
  // grossMonthly used for the Private balance section. Null until a CTC
  // figure has actually been computed against.
  calculated: null,
};

/* ===================== Matching ===================== */

function fieldOk(fVal, ctxVal){ return fVal === 'All' || fVal === ctxVal; }
function fieldScore(fVal, ctxVal){ return (fVal !== 'All' && fVal === ctxVal) ? 1 : 0; }

function findMatchingFormat(context){
  let best = null, bestScore = -1;
  // EMPLOYEE IS 'All' WHEN UNSET, the same as every other scope field here —
  // f.employee is stored '' for "applies to everybody", so it is read the
  // same way fieldOk/fieldScore already read every other scope.
  const ctxEmployee = context.employee || 'All';
  state.formats.forEach(f => {
    const companyOk = fieldOk(f.company, context.company);
    const branchOk = fieldOk(f.branch, context.branch);
    const teamOk = fieldOk(f.team, context.team);
    const roleOk = fieldOk(f.role || 'All', context.role);
    const desigOk = fieldOk(f.designation, context.designation);
    const employeeOk = fieldOk(f.employee || 'All', ctxEmployee);
    if (!companyOk || !branchOk || !teamOk || !roleOk || !desigOk || !employeeOk) return;
    const score = fieldScore(f.company, context.company) * 100000
      + fieldScore(f.branch, context.branch) * 10000
      + fieldScore(f.team, context.team) * 1000
      + fieldScore(f.role || 'All', context.role) * 100
      + fieldScore(f.designation, context.designation) * 10
      + fieldScore(f.employee || 'All', ctxEmployee);
    if (score > bestScore){ bestScore = score; best = f; }
  });
  return best;
}

