/* ===================== Field highlight (light bg on selection) ===================== */

function syncHighlight(sel){
  const filled = sel.value && sel.value !== 'All';
  sel.classList.toggle('is-filled', !!filled);
}
function syncAllHighlights(){
  [editCompany, editBranch, editTeam, editRole, editDesignation].forEach(syncHighlight);
}

/* ===================== Persistent storage ===================== */

// SAVED ON THE SERVER, per tenant, versioned and audited — not in browser
// storage, which is one person's browser and nobody else's payslip.
function persistFormats(){
  const field = document.getElementById('pf-json');

  if (!field) { showToast('Read-only: saving a format needs payroll.structure.publish'); return; }

  field.value = JSON.stringify(state.formats);
  document.getElementById('pf-form').submit();
}

function loadPersistedFormats(){
  return window.__PF.formats && window.__PF.formats.length ? window.__PF.formats : null;
}

/* ===================== Live calculation (CTC → components) ===================== */

// THE ONE ENGINE PAYROLL ITSELF COMPUTES THROUGH, asked over the network —
// never re-derived here. A percentage, a slab, a formula component: none of
// it is reimplemented in JavaScript, because a second evaluator is a second
// answer (see PayslipCalculator's own doc-comment), and that is exactly as
// true of a preview as it is of a real close.
let calcTimer = null;
let calcSeq = 0;

function scheduleCalc(){
  clearTimeout(calcTimer);
  // ponytail: 80ms, not 0 — a real keystroke fires several of these in a
  // row, and this only coalesces them into one request instead of one per
  // character. 350ms read as a visible wait; 80ms does not.
  calcTimer = setTimeout(runCalc, 80);
}

// THE THREE EDITOR SECTIONS, RE-DRAWN — a live calculation answers for all
// three at once (earning, deduction, employer), so a fresh number in any of
// them means the LIVE HINT next to every box needs to catch up together.
function renderComponents(){
  renderComponentSection('earning', earningList, earningCount);
  renderComponentSection('deduction', deductionList, deductionCount);
  renderComponentSection('employer', employerList, employerCount);
}

function runCalc(){
  const ctcLpa = parseFloat(ctcLpaInput.value);
  const mySeq = ++calcSeq;

  if (!ctcLpa || ctcLpa <= 0){
    state.calculated = null;
    renderPayslip();
    renderComponents();
    return;
  }

  // WHOSE RULES THIS ASKS FOR — the real employee picked in the Employee
  // filter, or failing that this format's own scope (company/branch/team/
  // designation), so the server resolves the SAME company/branch-specific
  // rule Organization Configuration → Salary Structure actually publishes,
  // never the flat tenant-wide fallback while a scoped rule exists.
  const ed = state.editor;
  const body = new URLSearchParams({ csrf: window.__PF.csrf, action: 'calc-payslip-preview',
    ctc_lpa: String(ctcLpa), employee: ed.employee || '', company: ed.company || '',
    branch: ed.branch || '', team: ed.team || '', designation: ed.designation || '' });

  fetch(window.location.pathname + window.location.search, {
    method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body,
  })
    // TEXT FIRST, THEN PARSED — a response that is not clean JSON (a PHP
    // notice ahead of the echo, a redirect to the sign-in screen, a fatal
    // error page) used to fail silently in .catch() with nothing to go on.
    // Reading it as text first means the failure is something a person can
    // read, not just "the numbers stayed at zero and nobody knows why".
    .then(r => r.text().then(text => ({ status: r.status, text })))
    .then(({ status, text }) => {
      if (mySeq !== calcSeq) return; // a later keystroke already asked again

      let data;

      try {
        data = JSON.parse(text);
      } catch {
        state.calculated = null;
        showToast(`Calculation failed (HTTP ${status}): ${text.slice(0, 200).trim() || 'empty response'}`, true);
        renderPayslip();
        renderComponents();
        return;
      }

      state.calculated = data.ok ? data : null;
      if (!data.ok) showToast(data.why || 'Calculation failed for an unknown reason.', true);
      renderPayslip();
      renderComponents();
    })
    .catch(err => {
      if (mySeq !== calcSeq) return;
      state.calculated = null;
      showToast(`Could not reach the server to calculate: ${err.message}`, true);
      renderPayslip();
      renderComponents();
    });
}

/* ===================== Toast ===================== */

let toastTimer = null;
function showToast(msg, sticky){
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  // ponytail: a calculation failure needs to actually be read, not glimpsed
  // for 2 seconds — sticky stays up until the next toast replaces it.
  if (!sticky) toastTimer = setTimeout(() => toast.classList.remove('show'), 2000);
}

/* ===================== Load / switch editor ===================== */

function loadFormat(fmt){
  state.editor = cloneEditor(fmt);
  state.editingExistingId = fmt.id;
  renderEditor();
}

function newFormat(){
  // Starts on whatever company is already open (so switching between a
  // company's formats and adding one more stays on that company), everything
  // else blank — there is no second "context" scope to inherit from anymore,
  // "Applies to company…" below is the only place a format's scope is set.
  const company = (state.editor && state.editor.company) || COMPANY_OPTIONS[0] || '';
  const f = defaultEditor(company);
  f.name = 'New Format';
  state.editor = f;
  state.editingExistingId = null;
  renderEditor();
}

/* ===================== Render: match indicator ===================== */

// Checks the OPEN format's own draft scope ("Applies to company…" below)
// against every saved format — so a collision with an existing format shows
// up before Save is even clicked, not only from the exact-scope guard inside
// the Save button's own handler.
function renderMatchIndicator(){
  const match = state.editor ? findMatchingFormat(state.editor) : null;
  if (match){
    matchIndicator.innerHTML = `<span class="match-chip"><span class="dot"></span>Matched format: ${escapeHtml(match.name)}</span>`;
  } else {
    matchIndicator.innerHTML = `<span class="match-chip none"><span class="dot"></span>No format matches this scope yet</span>`;
  }
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
}

/* ===================== Render: formats list ===================== */

function renderFormatJumpDropdown(){
  const grouped = {};
  state.formats.forEach(f => { (grouped[f.company] = grouped[f.company] || []).push(f); });

  let html = `<option value="">Jump to a saved format…</option>`;
  COMPANY_OPTIONS.forEach(co => {
    const list = grouped[co];
    if (!list || !list.length) return;
    html += `<optgroup label="${escapeHtml(co)}">`;
    list.forEach(f => {
      const scopeBits = [f.branch, f.team, f.designation].filter(v => v !== 'All');
      const scopeLabel = scopeBits.length ? ` (${scopeBits.map(escapeHtml).join(' · ')})` : ' (All)';
      html += `<option value="${f.id}">${escapeHtml(f.name)}${scopeLabel}</option>`;
    });
    html += `</optgroup>`;
  });
  jumpFormat.innerHTML = html;
  jumpFormat.value = state.editingExistingId || '';
}

function goToFormat(id){
  const f = state.formats.find(x => x.id === id);
  if (!f) return;
  loadFormat(f);
  renderFormatsList();
  renderMatchIndicator();
  syncAllHighlights();
}

jumpFormat.addEventListener('change', () => {
  if (jumpFormat.value) goToFormat(jumpFormat.value);
});

function renderFormatsList(){
  renderFormatJumpDropdown();
  const company = state.editor ? state.editor.company : 'All';
  const listAllCompanies = company === 'All';
  formatsTitle.textContent = (listAllCompanies || !company) ? 'All formats' : `${company} formats`;
  const list = listAllCompanies ? state.formats.slice() : state.formats.filter(f => f.company === company);
  formatsSub.textContent = list.length
    ? `${list.length} format${list.length === 1 ? '' : 's'} saved${listAllCompanies ? '' : ' for ' + company}`
    : `No formats saved${listAllCompanies ? '' : ' for ' + company} yet`;

  const matched = state.editor ? findMatchingFormat(state.editor) : null;

  if (!list.length){
    formatsList.innerHTML = `<div class="empty-formats">No formats yet — click "New format" to create one${listAllCompanies ? '' : ' for ' + company}.</div>`;
    return;
  }

  formatsList.innerHTML = '';
  list.forEach(f => {
    const row = document.createElement('div');
    row.className = 'format-row' + (state.editor && state.editingExistingId === f.id ? ' active' : '');
    const scopeChips = [
      listAllCompanies ? (f.company !== 'All' ? `<span class="scope-chip company">${escapeHtml(f.company)}</span>` : `<span class="scope-chip all">All companies</span>`) : '',
      f.branch !== 'All' ? `<span class="scope-chip branch">${escapeHtml(f.branch)}</span>` : `<span class="scope-chip all">All branches</span>`,
      f.team !== 'All' ? `<span class="scope-chip team">${escapeHtml(f.team)}</span>` : '',
      f.role && f.role !== 'All' ? `<span class="scope-chip designation">${escapeHtml(ROLE_LABEL[f.role] || f.role)}</span>` : '',
      f.designation !== 'All' ? `<span class="scope-chip designation">${escapeHtml(f.designation)}</span>` : '',
      f.employee ? `<span class="scope-chip designation">${escapeHtml((EMPLOYEE_BY_CODE[f.employee] || {}).label || f.employee)}</span>` : '',
    ].filter(Boolean).join('');
    row.innerHTML = `
      <div style="flex:1; min-width:0;">
        <div class="fname">${escapeHtml(f.name)}${matched && matched.id === f.id ? ' <span class="matched-tag">● in use</span>' : ''}</div>
        <div class="format-scope">${scopeChips}</div>
      </div>
      <button class="format-del" title="Delete format">✕</button>
    `;
    row.addEventListener('click', (e) => {
      if (e.target.closest('.format-del')) return;
      loadFormat(f);
      renderFormatsList();
    });
    row.querySelector('.format-del').addEventListener('click', () => {
      if (!confirm(`Delete "${f.name}"?`)) return;
      state.formats = state.formats.filter(x => x.id !== f.id);
      if (state.editingExistingId === f.id) newFormat();
      renderFormatsList();
      renderMatchIndicator();
      renderPayslip();
      persistFormats();
    });
    formatsList.appendChild(row);
  });
}

/* ===================== Render: editor ===================== */

function renderEditor(){
  const ed = state.editor;
  editorName.value = ed.name;
  editCompany.value = ed.company;
  editBranch.value = ed.branch;
  editTeam.value = ed.team;
  editRole.value = ed.role || 'All';
  refreshDesignationOptions(editDesignation, editRole.value, ed.designation);
  editEmployee.value = ed.employee && EMPLOYEE_BY_CODE[ed.employee] ? ed.employee : '';
  showEmployerToggle.checked = ed.showEmployerSection;
  showLogoToggle.checked = ed.showLogo !== false;
  showDesignationToggle.checked = ed.showDesignation !== false;
  showPanToggle.checked = ed.showPan !== false;
  showUanToggle.checked = ed.showUan !== false;
  showDojToggle.checked = ed.showDoj !== false;
  showCompanyAddressToggle.checked = !!ed.showCompanyAddress;
  showLocationToggle.checked = !!ed.showLocation;
  deleteBtn.style.display = state.editingExistingId ? 'inline-flex' : 'none';
  renderComponentSection('earning', earningList, earningCount);
  renderComponentSection('deduction', deductionList, deductionCount);
  renderComponentSection('employer', employerList, employerCount);
  ctcLpaInput.value = ed.employee ? ((EMPLOYEE_BY_CODE[ed.employee] || {}).ctcLpa ?? '') : (state.previewCtcLpa || '');
  // A DIFFERENT FORMAT MEANS A DIFFERENT CTC — the last calculation belonged
  // to whichever format was open a moment ago, and showing it against this
  // one would be a number that looks current and is not.
  state.calculated = null;
  if (parseFloat(ctcLpaInput.value) > 0) scheduleCalc();
  renderPayslip();
  syncAllHighlights();
}

function sortedChecked(section){
  const ed = state.editor;
  return COMPONENT_LIBRARY[section]
    .filter(c => ed[section][c.id].checked)
    .sort((a, b) => ed[section][a.id].order - ed[section][b.id].order);
}

function renderComponentSection(section, container, countEl){
  const ed = state.editor;
  const checkedCount = COMPONENT_LIBRARY[section].filter(c => ed[section][c.id].checked).length;
  countEl.textContent = `${checkedCount} of ${COMPONENT_LIBRARY[section].length} shown`;

  container.innerHTML = '';
  COMPONENT_LIBRARY[section].forEach(c => {
    const st = ed[section][c.id];
    const row = document.createElement('div');
    row.className = 'component-row' + (st.checked ? ' checked' : '');

    const checkedList = sortedChecked(section);
    const idx = checkedList.findIndex(x => x.id === c.id);
    const displayOrder = idx >= 0 ? idx + 1 : null;
    const canUp = st.checked && idx > 0;
    const canDown = st.checked && idx >= 0 && idx < checkedList.length - 1;

    // THE BOX SHOWS WHAT THIS COMPONENT IS WORTH RIGHT NOW — the live figure
    // for whatever CTC/employee is on screen above, when there is one; the
    // format's own saved sample otherwise. It is still only DISPLAY: `st.amount`
    // (what "Save format" actually persists) is untouched by a live number and
    // changes only when somebody types into the box themselves — so this format
    // stays reusable for every employee it applies to, and looking at one
    // person's live figures here never bakes them in for everyone else.
    const liveCalc = state.calculated && state.calculated.components[c.id];
    const isLive = !!(liveCalc && liveCalc.section === section);
    const displayAmount = isLive ? Number(liveCalc.amount) : st.amount;
    const liveHint = isLive
      ? `<span class="live-hint" title="What the CTC (LPA) box above calculates for this component right now — shown here, not saved with the format until you type your own amount">live</span>`
      : '';

    row.innerHTML = `
      <input type="checkbox" ${st.checked ? 'checked' : ''}>
      <span class="cname-wrap"><span class="cname">${escapeHtml(c.name)}</span>${liveHint}</span>
      <span class="amount-wrap"><span>₹</span><input type="number" min="0" step="1" value="${displayAmount}" ${isLive ? 'title="Live calculated amount — type here to override it for this saved format"' : ''}></span>
      <span class="order-controls">
        ${st.checked ? `<span class="order-badge">${displayOrder}</span>` : ''}
        <button class="order-btn up" ${canUp ? '' : 'disabled'} title="Move up">▲</button>
        <button class="order-btn down" ${canDown ? '' : 'disabled'} title="Move down">▼</button>
      </span>
    `;

    row.querySelector('input[type=checkbox]').addEventListener('change', (e) => {
      st.checked = e.target.checked;
      if (st.checked){
        const maxOrder = Math.max(0, ...COMPONENT_LIBRARY[section].filter(x => ed[section][x.id].checked).map(x => ed[section][x.id].order));
        st.order = maxOrder + 1;
      }
      renderComponentSection(section, container, countEl);
      renderPayslip();
    });

    row.querySelector('input[type=number]').addEventListener('input', (e) => {
      st.amount = e.target.value === '' ? 0 : Number(e.target.value);
      renderPayslip();
    });

    const upBtn = row.querySelector('.order-btn.up');
    const downBtn = row.querySelector('.order-btn.down');
    upBtn.addEventListener('click', () => { swapOrder(section, c.id, -1); renderComponentSection(section, container, countEl); renderPayslip(); });
    downBtn.addEventListener('click', () => { swapOrder(section, c.id, 1); renderComponentSection(section, container, countEl); renderPayslip(); });

    container.appendChild(row);
  });
}

function swapOrder(section, id, dir){
  const ed = state.editor;
  const checkedList = sortedChecked(section);
  const idx = checkedList.findIndex(x => x.id === id);
  const swapIdx = idx + dir;
  if (idx < 0 || swapIdx < 0 || swapIdx >= checkedList.length) return;
  const a = checkedList[idx], b = checkedList[swapIdx];
  const tmp = ed[section][a.id].order;
  ed[section][a.id].order = ed[section][b.id].order;
  ed[section][b.id].order = tmp;
}

/* ===================== Render: payslip preview ===================== */

// THE COMPANY A PREVIEW BRANDS AS — a specific employee's own employer wins
// (that is exactly what the real payslip route reads it from); failing
// that, whichever company this format is scoped to; failing that ("All
// companies"), a specific branch, team/department or designation still
// pins exactly one company (each belongs to only one — the owner's own
// words: "for any specific branch, department, designation etc, it should
// take the respective company branding only"); only when NONE of that
// narrows it at all does this fall back to APP_BRAND, the generic Company
// Branding card.
function resolveCompanyKey(){
  const ed = state.editor;
  const emp = ed.employee ? EMPLOYEE_BY_CODE[ed.employee] : null;
  if (emp && emp.company && emp.company !== 'All') return emp.company;
  if (ed.company !== 'All') return ed.company;
  if (ed.branch !== 'All' && BRANCH_COMPANY[ed.branch]) return BRANCH_COMPANY[ed.branch];
  if (ed.team !== 'All' && TEAM_COMPANY[ed.team]) return TEAM_COMPANY[ed.team];
  if (ed.designation !== 'All' && DESIGNATION_COMPANY[ed.designation]) return DESIGNATION_COMPANY[ed.designation];
  return null;
}
function resolveCompanyLabel(){
  const key = resolveCompanyKey();
  return key ? (COMPANY_LABEL[key] || key) : (APP_BRAND.name || 'All Companies (generic template)');
}
function resolveBranchLabel(){
  const ed = state.editor;
  const emp = ed.employee ? EMPLOYEE_BY_CODE[ed.employee] : null;
  if (emp && emp.branch && emp.branch !== 'All') return emp.branch;
  return ed.branch !== 'All' ? ed.branch : 'All Branches';
}
function resolveCompanyShort(){
  const key = resolveCompanyKey();
  return key || 'All Companies';
}
function resolveCompanyLogo(){
  const key = resolveCompanyKey();
  return key ? (COMPANY_LOGO[key] || '') : (APP_BRAND.logo || '');
}
// THE SAME HEX THE REAL PAYSLIP PAINTS ITS HEADER WITH (companies.color) —
// item 7 — or, for "All companies" with nobody specific picked, the same hex
// the app's own sidebar wears (Organization Configuration → Companies' own
// "Company Branding" card, top of that page). No fallback colour beyond
// that: an unset/invalid hex means the preview falls back to the
// stylesheet's own header colour, exactly like the real payslip route's
// $slipCompanyColorOk does.
function resolveCompanyColor(){
  const key = resolveCompanyKey();
  return key ? (COMPANY_COLOR[key] || '') : (APP_BRAND.color || '');
}
function resolveCompanyAddress(){
  const key = resolveCompanyKey();
  // The generic Company Branding card has no address of its own to show.
  return key ? (COMPANY_ADDRESS[key] || '') : '';
}

// A CHECKED COMPONENT'S AMOUNT — the server's calculated figure (item 6,
// whenever a CTC has actually been computed against) over the designer's
// own manually-typed sample, never the other way around: a real number, once
// there is one to show, is always more accurate than a placeholder.
function displayAmount(section, code, fallback){
  const calc = state.calculated && state.calculated.components[code];
  return calc && calc.section === section ? Number(calc.amount) : Number(fallback || 0);
}

function renderPayslip(){
  const ed = state.editor;
  const emp = ed.employee ? EMPLOYEE_BY_CODE[ed.employee] : null;

  const earnLines = sortedChecked('earning').map(c => ({ name: c.name, amount: displayAmount('earning', c.id, ed.earning[c.id].amount) }));
  const dedLines = sortedChecked('deduction').map(c => ({ name: c.name, amount: displayAmount('deduction', c.id, ed.deduction[c.id].amount) }));
  const employerLines = ed.showEmployerSection ? sortedChecked('employer').map(c => ({ name: c.name, amount: displayAmount('employer', c.id, ed.employer[c.id].amount) })) : [];

  const totalEarn = earnLines.reduce((s, l) => s + Number(l.amount || 0), 0);
  const totalDed = dedLines.reduce((s, l) => s + Number(l.amount || 0), 0);
  const netPay = totalEarn - totalDed;

  const companyLabel = resolveCompanyLabel();
  const branchLabel = resolveBranchLabel();
  const companyShort = resolveCompanyShort();
  const companyColor = resolveCompanyColor();
  const companyAddress = ed.showCompanyAddress ? resolveCompanyAddress() : '';
  const logoPath = ed.showLogo !== false ? resolveCompanyLogo() : '';
  const employeeLocation = ed.showLocation ? (emp ? emp.location : branchLabel) : '';
  const displayName = emp ? (emp.name || emp.label) : state.employeeName;
  const displayId = emp ? emp.code : state.employeeId;
  const displayDesignation = emp ? emp.designation : ed.designation;
  const displayTeam = emp ? emp.team : ed.team;
  const displayBranch = emp ? emp.branch : ed.branch;
  const displayPan = emp ? (emp.pan || '—') : 'ABCDE1234F';
  const displayUan = emp ? (emp.uan || '—') : '123456789012';
  // SAMPLE VALUES ONLY WHEN NO REAL EMPLOYEE IS PICKED — PAN, UAN and date of
  // joining are per-employee facts; a specific Employee filter (item 5)
  // reads them off that employee's own record instead of a placeholder.
  const sampleDoj = (function(){ const d = new Date(); d.setFullYear(d.getFullYear() - 2); return String(d.getDate()).padStart(2, '0') + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + d.getFullYear(); })();
  const displayDoj = emp ? (emp.doj || '—') : sampleDoj;

  const earnRows = earnLines.length
    ? earnLines.map(l => `<div class="ps-line"><span>${escapeHtml(l.name)}</span><span class="amt">₹${currencyFmt(l.amount)}</span></div>`).join('')
    : `<div class="ps-empty-line">No earning components selected</div>`;

  const dedRows = dedLines.length
    ? dedLines.map(l => `<div class="ps-line"><span>${escapeHtml(l.name)}</span><span class="amt">₹${currencyFmt(l.amount)}</span></div>`).join('')
    : `<div class="ps-empty-line">No deduction components selected</div>`;

  const employerBlock = ed.showEmployerSection ? `
    <div class="ps-employer">
      <div class="ps-table-title">Employer contributions</div>
      ${employerLines.length ? employerLines.map(l => `<div class="ps-line"><span>${escapeHtml(l.name)}</span><span class="amt">₹${currencyFmt(l.amount)}</span></div>`).join('') : `<div class="ps-empty-line">No employer components selected</div>`}
      <div class="ps-employer-note">Cost to company only — not included in net pay.</div>
    </div>
  ` : '';

  const empRows = [
    `<div class="ps-emp-row"><span class="k">Employee Name</span><span class="v">${escapeHtml(displayName)}</span></div>`,
    `<div class="ps-emp-row"><span class="k">Employee ID</span><span class="v">${escapeHtml(displayId)}</span></div>`,
    ed.showDesignation !== false ? `<div class="ps-emp-row"><span class="k">Designation</span><span class="v">${escapeHtml(displayDesignation)}</span></div>` : '',
    `<div class="ps-emp-row"><span class="k">Team</span><span class="v">${escapeHtml(displayTeam)}</span></div>`,
    `<div class="ps-emp-row"><span class="k">Branch</span><span class="v">${escapeHtml(displayBranch)}</span></div>`,
    `<div class="ps-emp-row"><span class="k">Pay Period</span><span class="v">${escapeHtml(state.payPeriod)}</span></div>`,
    ed.showPan !== false ? `<div class="ps-emp-row"><span class="k">PAN</span><span class="v">${escapeHtml(displayPan)}</span></div>` : '',
    ed.showUan !== false ? `<div class="ps-emp-row"><span class="k">UAN</span><span class="v">${escapeHtml(displayUan)}</span></div>` : '',
    ed.showDoj !== false ? `<div class="ps-emp-row"><span class="k">Date of Joining</span><span class="v">${escapeHtml(displayDoj)}</span></div>` : '',
    employeeLocation ? `<div class="ps-emp-row"><span class="k">Employee Location</span><span class="v">${escapeHtml(employeeLocation)}</span></div>` : '',
  ].filter(Boolean).join('');

  payslipEl.innerHTML = `
    <div class="ps-letterhead"${companyColor ? ` style="border-bottom-color:${escapeHtml(companyColor)}"` : ''}>
      <div style="display:flex;align-items:center;gap:10px">
${logoPath ? `        <img src="${escapeHtml(logoPath)}" alt="" style="width:34px;height:34px;object-fit:contain;border-radius:6px;background:#fff">` : ''}
        <div>
          <div class="ps-company-name"${companyColor ? ` style="color:${escapeHtml(companyColor)}"` : ''}>${escapeHtml(companyLabel)}</div>
${companyAddress ? `          <div class="ps-company-addr">${escapeHtml(companyAddress)}</div>` : `          <div class="ps-company-addr">${escapeHtml(branchLabel)} Branch · ${escapeHtml(companyShort)}</div>`}
        </div>
      </div>
      <div>
        <div class="ps-payslip-tag">Payslip</div>
        <div class="ps-period">${escapeHtml(state.payPeriod)}</div>
      </div>
    </div>

    <div class="ps-emp-grid">
      ${empRows}
    </div>

    <div class="ps-tables">
      <div>
        <div class="ps-table-title earning">Earnings</div>
        ${earnRows}
        <div class="ps-subtotal"><span>Total Earnings</span><span class="amt">₹${currencyFmt(totalEarn)}</span></div>
      </div>
      <div>
        <div class="ps-table-title deduction">Deductions</div>
        ${dedRows}
        <div class="ps-subtotal"><span>Total Deductions</span><span class="amt">₹${currencyFmt(totalDed)}</span></div>
      </div>
    </div>

    <div class="ps-netpay"${companyColor ? ` style="background:${escapeHtml(companyColor)}1a;border-color:${escapeHtml(companyColor)}"` : ''}>
      <span class="label"${companyColor ? ` style="color:${escapeHtml(companyColor)}"` : ''}>Net Pay</span>
      <span class="value"${companyColor ? ` style="color:${escapeHtml(companyColor)}"` : ''}>₹${currencyFmt(netPay)}</span>
    </div>
    <div class="ps-words">${escapeHtml(amountInWords(netPay))}</div>

    ${employerBlock}

    <div class="ps-footer">This is a system-generated payslip and does not require a signature.</div>
  `;

  renderPrivateBalance(totalEarn);
}

/* ===================== Render: private balance (item 8) ===================== */

// EVERYTHING THE CTC ACTUALLY COMPUTES TO THAT THIS FORMAT DOES NOT PRINT —
// "the fields shown in the payslip may not exactly match the overall or net
// salary. That is fine. The remaining amount... should be shown Privately."
// Only exists once a real calculation has run (state.calculated); with no
// CTC entered there is nothing computed to reconcile against, so the section
// stays hidden rather than showing zeroes that look like an answer.
function renderPrivateBalance(shownEarnTotal){
  const calc = state.calculated;

  if (!calc){
    privateBalanceEl.style.display = 'none';
    privateBalanceEl.innerHTML = '';
    return;
  }

  const ed = state.editor;
  const shownCodes = new Set([
    ...COMPONENT_LIBRARY.earning.filter(c => ed.earning[c.id].checked).map(c => c.id),
    ...COMPONENT_LIBRARY.deduction.filter(c => ed.deduction[c.id].checked).map(c => c.id),
  ]);
  const nameOf = {};
  COMPONENT_LIBRARY.earning.concat(COMPONENT_LIBRARY.deduction, COMPONENT_LIBRARY.employer)
    .forEach(c => { nameOf[c.id] = c.name; });

  const hidden = Object.keys(calc.components)
    .filter(code => calc.components[code].section !== 'employer' && !shownCodes.has(code))
    .map(code => ({ code, name: nameOf[code] || code, section: calc.components[code].section,
      amount: Number(calc.components[code].amount) }));

  const hiddenEarn = hidden.filter(h => h.section === 'earning');
  const hiddenDed = hidden.filter(h => h.section === 'deduction');
  const hiddenEarnTotal = hiddenEarn.reduce((s, h) => s + h.amount, 0);
  const hiddenDedTotal = hiddenDed.reduce((s, h) => s + h.amount, 0);

  if (hidden.length === 0){
    privateBalanceEl.style.display = '';
    privateBalanceEl.innerHTML = `<div class="section-title" style="margin-bottom:6px"><h3 style="margin:0;font-size:11.5px;text-transform:uppercase;letter-spacing:.03em;color:var(--ink-faint)">Private: Balance amount sum up to CTC</h3></div>
      <div class="ps-empty-line">Every computed component is shown on this payslip — nothing is hidden from the CTC of ₹${currencyFmt(calc.grossMonthly)}/month.</div>`;
    return;
  }

  const rows = hidden.map(h => `<div class="ps-line"><span>${escapeHtml(h.name)} <span class="note" style="text-transform:capitalize">(${h.section}, not shown)</span></span><span class="amt">₹${currencyFmt(h.amount)}</span></div>`).join('');

  privateBalanceEl.style.display = '';
  privateBalanceEl.innerHTML = `
    <div class="section-title" style="margin-bottom:6px">
      <h3 style="margin:0;font-size:11.5px;text-transform:uppercase;letter-spacing:.03em;color:var(--ink-faint)">Private: Balance amount sum up to CTC</h3>
    </div>
    <p class="note" style="margin:0 0 8px">Computed from the CTC (LPA) box, not printed on the payslip above — for whoever is checking that the shown lines and this balance together account for the whole CTC.</p>
    ${rows}
    <div class="ps-subtotal"><span>Hidden earnings</span><span class="amt">₹${currencyFmt(hiddenEarnTotal)}</span></div>
    <div class="ps-subtotal"><span>Hidden deductions</span><span class="amt">₹${currencyFmt(hiddenDedTotal)}</span></div>
    <div class="ps-subtotal"><span>Shown earnings (from the payslip above)</span><span class="amt">₹${currencyFmt(shownEarnTotal)}</span></div>
    <div class="ps-netpay" style="margin-top:10px"><span class="label">Monthly gross from CTC</span><span class="value">₹${currencyFmt(calc.grossMonthly)}</span></div>
  `;
}

/* ===================== Editor field events ===================== */

editorName.addEventListener('input', () => { state.editor.name = editorName.value; renderFormatsList(); });
editCompany.addEventListener('change', () => { state.editor.company = editCompany.value; syncAllHighlights(); });
editBranch.addEventListener('change', () => { state.editor.branch = editBranch.value; syncAllHighlights(); });
editTeam.addEventListener('change', () => { state.editor.team = editTeam.value; syncAllHighlights(); });
editRole.addEventListener('change', () => {
  state.editor.role = editRole.value;
  refreshDesignationOptions(editDesignation, editRole.value, editDesignation.value);
  state.editor.designation = editDesignation.value;
  syncAllHighlights();
});
editDesignation.addEventListener('change', () => { state.editor.designation = editDesignation.value; syncAllHighlights(); });
// TYPED, NOT PICKED FROM A LIST — resolve whatever the box now holds against
// the datalist's own options (the same options the browser is filtering as
// the owner types) and take the code off the matching one. Anything that
// does not match a real employee means "All employees", same as clearing it.
// CLEAR THE BOX ON FOCUS — once an employee is picked, the box holds their
// full "AM-010 · Dinesh Nayak" label, and the browser filters the datalist
// against whatever text is ACTUALLY IN THE BOX, not against a selection —
// selecting the text (highlighting it) still leaves the browser matching one
// full name, so the dropdown kept offering only that one employee until a
// key was pressed. It read as frozen on whoever was already picked, with no
// way to even see there were other names to switch to. Emptying the box the
// moment it's clicked means the datalist has nothing to filter against, so
// every employee shows immediately — no typing required just to see the list.
// If nothing is picked before the box is left (blurred) with it still empty,
// the previous name is put back, so clicking in and straight back out is not
// mistaken for clearing the selection.
editEmployee.addEventListener('change', () => {
  const emp = EMPLOYEE_BY_CODE[editEmployee.value] || null;
  state.editor.employee = emp ? emp.code : '';

  // ONE PERSON'S OWN CTC FILLS THE BOX THE CALCULATION READS, THE MOMENT
  // THEY ARE PICKED — no waiting to leave the field, and no refresh: this
  // is the same 'input' handler that fires the instant a typed name
  // resolves to a real employee (typing the full match, or clicking the
  // browser's own datalist suggestion both fire it), so the CTC box and the
  // calculation it drives update together, live.
  if (emp) {
    ctcLpaInput.value = emp.ctcLpa || '';
    scheduleCalc();
  }

  syncAllHighlights();
  renderMatchIndicator();
  renderFormatsList();
  renderPayslip();
});
showEmployerToggle.addEventListener('change', () => { state.editor.showEmployerSection = showEmployerToggle.checked; renderPayslip(); });
showLogoToggle.addEventListener('change', () => { state.editor.showLogo = showLogoToggle.checked; renderPayslip(); });
showDesignationToggle.addEventListener('change', () => { state.editor.showDesignation = showDesignationToggle.checked; renderPayslip(); });
showPanToggle.addEventListener('change', () => { state.editor.showPan = showPanToggle.checked; renderPayslip(); });
showUanToggle.addEventListener('change', () => { state.editor.showUan = showUanToggle.checked; renderPayslip(); });
showDojToggle.addEventListener('change', () => { state.editor.showDoj = showDojToggle.checked; renderPayslip(); });
showCompanyAddressToggle.addEventListener('change', () => { state.editor.showCompanyAddress = showCompanyAddressToggle.checked; renderPayslip(); });
showLocationToggle.addEventListener('change', () => { state.editor.showLocation = showLocationToggle.checked; renderPayslip(); });

newFormatBtn.addEventListener('click', () => { newFormat(); renderFormatsList(); });

duplicateBtn.addEventListener('click', () => {
  const copy = cloneEditor(state.editor);
  copy.id = null;
  copy.name = state.editor.name + ' (copy)';
  state.editor = copy;
  state.editingExistingId = null;
  renderEditor();
  renderFormatsList();
  showToast('Duplicated — edit and save as a new format');
});

deleteBtn.addEventListener('click', () => {
  if (!state.editingExistingId) return;
  const f = state.formats.find(x => x.id === state.editingExistingId);
  if (!f) return;
  if (!confirm(`Delete "${f.name}"?`)) return;
  state.formats = state.formats.filter(x => x.id !== state.editingExistingId);
  newFormat();
  renderFormatsList();
  renderMatchIndicator();
  showToast('Format deleted');
  persistFormats();
});

saveBtn.addEventListener('click', () => {
  const ed = state.editor;
  if (!ed.name.trim()){ showToast('Give this format a name first'); return; }

  // guard against duplicate exact-scope formats (excluding itself)
  const clash = state.formats.find(f =>
    f.id !== state.editingExistingId &&
    f.company === ed.company && f.branch === ed.branch &&
    f.team === ed.team && (f.role || 'All') === (ed.role || 'All') && f.designation === ed.designation
    && (f.employee || '') === (ed.employee || '')
  );
  if (clash){
    showToast(`Scope already used by "${clash.name}" — adjust branch/team/role/designation/employee`);
    return;
  }

  if (state.editingExistingId){
    const idx = state.formats.findIndex(f => f.id === state.editingExistingId);
    ed.id = state.editingExistingId;
    state.formats[idx] = cloneEditor(ed);
  } else {
    ed.id = uid('fmt');
    state.editingExistingId = ed.id;
    state.formats.push(cloneEditor(ed));
  }
  renderFormatsList();
  renderMatchIndicator();
  syncAllHighlights();
  showToast(`Saved "${ed.name}"`);
  persistFormats();
});

/* ===================== Preview toolbar events ===================== */

empName.addEventListener('input', () => { state.employeeName = empName.value; renderPayslip(); });
empId.addEventListener('input', () => { state.employeeId = empId.value; renderPayslip(); });
payPeriod.addEventListener('input', () => { state.payPeriod = payPeriod.value; renderPayslip(); });
ctcLpaInput.addEventListener('input', () => {
  if (!state.editor.employee) state.previewCtcLpa = ctcLpaInput.value;
  scheduleCalc();
});
printBtn.addEventListener('click', () => window.print());

/* ===================== Boot ===================== */

function boot(){
  const persisted = loadPersistedFormats();
  if (persisted) state.formats = persisted;

  // Opens the most specific saved format (state.formats is already ordered
  // most-specific-first, the same order the server matches a real payslip
  // with) so there is something concrete in "Applies to company…" the moment
  // the screen loads, rather than an empty draft nobody asked for.
  if (window.__PF.editId) {
    const opened = state.formats.find(f => String(f.id) === String(window.__PF.editId));
    if (opened) { loadFormat(opened); } else if (state.formats.length) { loadFormat(state.formats[0]); } else { newFormat(); }
  } else if (state.formats.length) {
    loadFormat(state.formats[0]);
  } else {
    newFormat();
  }

  renderFormatsList();
  renderMatchIndicator();
  syncAllHighlights();
}

boot();

</script>

