  <script>
    // Captured checkboxes: name="captured[...]" and not disabled (the always-on ones are disabled and stay ticked).
    function efBoxes(scope) { return Array.prototype.filter.call(scope.querySelectorAll('input[type=checkbox][name^="captured["]'), function (c) { return !c.disabled; }); }
    function efSection(head) { var card = head.closest('[data-ef-section]'); efBoxes(card).forEach(function (c) { c.checked = head.checked; }); efSync(); }
    function efAll(on) { document.querySelectorAll('.ef-section').forEach(function (h) { h.checked = on; efBoxes(h.closest('[data-ef-section]')).forEach(function (c) { c.checked = on; }); }); }
    function efSync() {
      var all = true;
      document.querySelectorAll('[data-ef-section]').forEach(function (card) { var b = efBoxes(card); var every = b.length > 0 && b.every(function (c) { return c.checked; }); card.querySelector('.ef-section').checked = every; card.querySelector('.ef-section').indeterminate = !every && b.some(function (c) { return c.checked; }); if (!every) { all = false; } });
      var top = document.getElementById('ef-all'); top.checked = all; top.indeterminate = !all && efBoxes(document).some(function (c) { return c.checked; });
    }
    document.querySelectorAll('input[type=checkbox][name^="captured["]').forEach(function (c) { c.addEventListener('change', efSync); });
    efSync();
  </script>

