      <div class="problem" style="margin:0;display:none" data-um-noemail>This employee has <b>no email on file</b>. A login signs in with an email, so add it first, then reset here.
        <div style="margin-top:8px"><a class="btn btn-outline btn-sm" data-um-edit href="#"><i class="fas fa-pen"></i> Add the email in the Directory</a></div></div>
      <form method="post" style="margin:0;display:grid;gap:6px" data-um-opt><input type="hidden" name="csrf" value="<?= e($session->token()) ?>"><input type="hidden" name="action" value="reset-employee-password"><input type="hidden" name="id" value="">
        <b style="font-size:13px">1. Email them a link</b>
        <span class="note" data-um-mail></span>
        <button class="btn btn-outline" type="submit" data-um-mail-btn><i class="fas fa-envelope"></i> Email a set-password link</button></form>
      <form method="post" style="margin:0;display:grid;gap:6px" data-um-opt><input type="hidden" name="csrf" value="<?= e($session->token()) ?>"><input type="hidden" name="action" value="reset-employee-password"><input type="hidden" name="id" value="">
        <b style="font-size:13px">2. Or set a password now</b>
        <span class="note">At least <?= (int) Session::PASSWORD_FLOOR ?> characters. Tell the employee yourself; they can change it later from My Space.</span>
        <div style="display:flex;gap:8px"><input type="password" name="password" required minlength="<?= Session::PASSWORD_FLOOR ?>" placeholder="New password" autocomplete="new-password" style="flex:1">
          <button type="button" class="btn btn-outline" title="Show / hide" onclick="var i=this.closest('form').querySelector('input[name=password]');i.type=i.type==='password'?'text':'password'"><i class="fas fa-eye"></i></button></div>
        <button class="go" type="submit"><i class="fas fa-check"></i> Set password</button></form>
    </div>
    <div style="padding:12px 20px;border-top:1px solid var(--border);display:flex;justify-content:flex-end"><button type="button" class="btn btn-outline" onclick="this.closest('dialog').close()">Cancel</button></div>
  </dialog>
  <script>(function(){var d=document.getElementById('um-reset-dlg');if(!d){return;}
    document.addEventListener('click',function(ev){var b=ev.target.closest('[data-um-reset]');if(!b){return;}
      d.querySelectorAll('input[name=id]').forEach(function(i){i.value=b.getAttribute('data-um-reset');});
      d.querySelector('[data-um-who]').textContent=b.getAttribute('data-um-who');
      var mail=b.getAttribute('data-um-email')||'';
      d.querySelector('[data-um-mail]').textContent='Sent to '+mail+' — works once, for 72 hours.';
      // NO EMAIL = NO LOGIN: say so and offer the Directory record, instead of two choices the server would refuse.
      d.querySelector('[data-um-noemail]').style.display=mail===''?'':'none';
      d.querySelector('[data-um-intro]').style.display=mail===''?'none':'';
      d.querySelectorAll('[data-um-opt]').forEach(function(f){f.style.display=mail===''?'none':'grid';});
      d.querySelector('[data-um-edit]').href='?r=employees&edit='+encodeURIComponent(b.getAttribute('data-um-reset'))+'#add-employment';
      d.querySelector('input[name=password]').value='';d.showModal();});})();</script>
