<?php if ($may('leave.request.submit')): ?>
  <div class="card" id="apply-leave">
    <h2 style="margin-top:0">Apply for leave</h2>
    <form method="post" id="lv-form">
      <input type="hidden" name="csrf" value="<?= e($session->token()) ?>">
      <input type="hidden" name="action" value="leave-request">
      <input type="hidden" name="id" value="<?= e($id) ?>">
      <input type="hidden" name="employment_code" value="<?= e(Employment::code($employment)) ?>">
      <input type="hidden" name="accept_unpaid" id="lv-unpaid" value="0">
<?php $lvHasUnpaid = in_array(false, array_column($lvAvail, 'capped'), true);
    // A REFUSED REQUEST KEEPS WHAT WAS TYPED (owner, 6 Nov 2026: after dates, type and reason it "is going back to
    // select the leave type again"): the form re-opens with the same type, dates, half and reason, the reason why on top.
    $lvKeep = post('action') === 'leave-request' && ($problem ?? '') !== '';
    $lvIso = static fn (string $v): string => preg_match('/^\d{4}-\d{2}-\d{2}$/', $v) === 1 ? $v : ''; ?>
      <div class="row" style="align-items:flex-start">
        <div style="flex:2;min-width:230px"><label for="lv-type">Leave type <span style="color:#dc2626">*</span></label>
          <select id="lv-type" name="leave_type" required>
            <option value="">— choose —</option>
<?php foreach ($lvAvail as $lvCode => $lvT): ?>
            <option value="<?= e((string) $lvCode) ?>" data-capped="<?= $lvT['capped'] ? '1' : '0' ?>" data-available="<?= e($lvT['available']) ?>"<?= !$lvHasUnpaid && $lvT['capped'] && SmartPRS\Platform\Support\Rational::fromDecimalString((string) $lvT['available'])->compareTo(SmartPRS\Platform\Support\Rational::of(0)) <= 0 ? ' disabled' : '' ?><?= $lvKeep && post('leave_type') === (string) $lvCode ? ' selected' : '' ?>><?= e($lvT['name']) ?> — <?= $lvT['capped'] ? e($lvT['available']) . ' available' : 'unpaid' ?></option>
<?php endforeach; ?>
          </select></div>
        <div><label for="lv-from">From <span style="color:#dc2626">*</span></label>
