  <script>
  (function () {
    var hasUnpaid = <?= $lvHasUnpaid ? 'true' : 'false' ?>, unpaid = document.getElementById('lv-unpaid'),
        half = document.getElementById('lv-half');
    var form = document.getElementById('lv-form'), type = document.getElementById('lv-type'),
        from = document.getElementById('lv-from'), to = document.getElementById('lv-to'),
        out = document.getElementById('lv-days'), note = document.getElementById('lv-days-note'), seq = 0, lastDays = null, availOn = null;
    // Available on the From date (the server's answer); the option's figure is today's.
    function avail() { var o = type.selectedOptions[0]; return availOn !== null ? availOn : (o ? o.dataset.available : '0'); }
    // THE SAME COUNT THE REQUEST WILL BE CHARGED: asked of the server
    // (Leave::chargeableDays), not guessed here.
    function judge() {
      var o = type.selectedOptions[0], msg = '';
      if (excess() > 0) {
        msg = 'Only ' + avail() + ' day(s) of this leave are available on ' + from.value.split('-').reverse().join('-') + '; this span is ' + lastDays + '.'
          + (hasUnpaid ? ' ' + excess() + ' day(s) will be unpaid leave.' : '');
      }
      to.setCustomValidity(msg && !hasUnpaid ? msg : '');
      note.textContent = msg || note.dataset.base || '';
      note.style.color = msg ? 'var(--red,#b42318)' : '';
    }
    function count() {
      if (from.value && (!to.value || to.value < from.value || half.value !== '')) { to.value = from.value; }
      to.min = from.value;
      to.readOnly = half.value !== '';
      if (!from.value || !to.value) { out.textContent = '—'; lastDays = null; judge(); return; }
      var mine = ++seq;
      availOn = null;
      out.textContent = '…';
      fetch(location.pathname + location.search, {method: 'POST', credentials: 'same-origin', headers: {'Content-Type': 'application/x-www-form-urlencoded'},
        body: new URLSearchParams({csrf: form.elements['csrf'].value, action: 'leave-days', id: form.elements['id'].value, type: type.value, from: from.value, to: to.value})})
        .then(function (r) { return r.json(); }).then(function (j) {
          if (mine !== seq) { return; }
          lastDays = j.ok ? j.days : null;
          availOn = j.available !== undefined && j.available !== null ? String(j.available) : null;
          // A HALF DAY is half of one working date; a weekly off / holiday has no half.
          if (j.ok && half.value !== '') {
            lastDays = j.days === 1 ? 0.5 : null;
            if (j.days !== 1) { j.why = 'That date is a weekly off or a holiday — there is no half day to take.'; j.ok = false; }
          }
          out.textContent = lastDays !== null ? lastDays : '—';
          note.dataset.base = j.ok ? (j.exempt > 0 ? j.exempt + ' weekly off / holiday day(s) in the span not charged' : '') : (j.why || '');
          judge();
        }).catch(function () { if (mine === seq) { out.textContent = '—'; note.dataset.base = 'Could not count the days just now.'; judge(); } });
    }
    // DAYS BEYOND THE PAID BALANCE — whole days, as the server splits them.
    function excess() {
      var o = type.selectedOptions[0];
      if (lastDays === null || !o || o.value === '' || o.dataset.capped !== '1') { return 0; }
      var a = parseFloat(avail());
      if (half.value !== '') { return a >= 0.5 ? 0 : 0.5; }
      return Math.max(0, lastDays - Math.max(0, Math.floor(a)));
    }
    form.addEventListener('submit', function (ev) {
      var n = excess();
      unpaid.value = '0';
      if (n <= 0 || !hasUnpaid) { return; }
      if (!confirm('Available leave balance: ' + avail()
          + '\nApplied leaves: ' + lastDays
          + '\n' + n + ' day(s) will be unpaid leaves.'
          + '\n\nClick OK to continue or Cancel to change the date range to apply the leaves.')) {
        ev.preventDefault(); from.focus(); return;
      }
      unpaid.value = '1';
    });
    [type, from, to, half].forEach(function (el) { el.addEventListener('change', count); });
    count();
  })();
  </script>
<?php endif; ?>

