    <span>Every column is still in the export, and hovering a clipped cell shows it in full.</span>
  </p>
  <script>
  (function () {
    var box = document.getElementById('la-tight');
    var KEY = 'smartprs.leaveApprovals.tight';
    function apply(on) {
      Array.prototype.forEach.call(document.querySelectorAll('.la-table'), function (t) {
        t.classList.toggle('la-tight', on);
      });
    }
    var saved = null;
    // localStorage throws in a private window and comes back empty after a
    // clear, so the checkbox has to work whether or not it can be remembered.
    try { saved = localStorage.getItem(KEY); } catch (e) {}
    box.checked = saved === '1';
    apply(box.checked);
    box.addEventListener('change', function () {
      apply(box.checked);
      try { localStorage.setItem(KEY, box.checked ? '1' : '0'); } catch (e) {}
    });
  })();
  </script>
