    $laAv = leaveAvailability($store, $leave, $policy, $laE, (string) ($laR['from'] ?? ''))[$laType] ?? null;   // as of the leave's start (12 Oct)
    // What this request may use: available PLUS its own pending days (it is one of the pending).
    $laCanUse = $laAv === null ? null : SmartPRS\Platform\Support\Rational::fromDecimalString($laAv['available'])->plus(SmartPRS\Platform\Support\Rational::fromDecimalString(preg_match('/^\d+(\.\d+)?$/', trim((string) $laR['days'])) === 1 ? trim((string) $laR['days']) : '0'))->toDecimalString(1); ?>
