            <form method="post" id="<?= e($laF) ?>" class="la-form" data-emp="<?= e((string) $laE['id']) ?>" data-type="<?= e($laType) ?>" data-capped="<?= ($laAv['capped'] ?? false) ? '1' : '0' ?>" data-available="<?= e((string) ($laCanUse ?? '')) ?>">
