  <script>
  // THE DAYS ARE RECOUNTED FROM THE EDITED DATES by the same server count the
  // approval is charged with; approving beyond what is available is refused here
  // (and again by the rules on the server).
  document.querySelectorAll('.la-form').forEach(function (form) {
    var row = form.closest('tr'), from = row.querySelector('input[name=from]'), to = row.querySelector('input[name=to]'),
        out = row.querySelector('.la-days'), note = row.querySelector('.la-note'), seq = 0;
    function count() {
      if (to.value < from.value) { to.value = from.value; }
      to.min = from.value;
      var mine = ++seq;
      out.textContent = '…';
      fetch(location.pathname + location.search, {method: 'POST', credentials: 'same-origin', headers: {'Content-Type': 'application/x-www-form-urlencoded'},
        body: new URLSearchParams({csrf: form.elements['csrf'].value, action: 'leave-days', id: form.dataset.emp, type: form.dataset.type, from: from.value, to: to.value})})
        .then(function (r) { return r.json(); }).then(function (j) {
          if (mine !== seq) { return; }
          out.textContent = j.ok ? j.days : '—';
          var msg = !j.ok ? (j.why || 'Cannot count these dates.') : (form.dataset.capped === '1' && j.days > parseFloat(form.dataset.available) ? 'Only ' + form.dataset.available + ' available' : '');
          to.setCustomValidity(msg);
          note.textContent = msg;
          note.style.color = msg ? 'var(--red,#b42318)' : '';
        });
    }
    from.addEventListener('change', count);
    to.addEventListener('change', count);
  });
  </script>
