<?php
    $bulkBatches = $attendanceBulk->batches();
    $openBatch = (string) ($_GET['batch'] ?? '');

    if ($openBatch === '' && $bulkBatches !== []) {
        $openBatch = (string) $bulkBatches[0]['batch'];
    }

    $openRows = $openBatch === '' ? [] : $attendanceBulk->rows($openBatch);
    // ONLY ROWS FOR PEOPLE IN REACH, plus unmatched ones for an account that
    // sees everybody (owner, 28 Sep).
    $bulkVisible = [];
    foreach ($scope->only(liveRows($store, 'employees'), $may('employee.list')) as $bulkV) {
        $bulkVisible[Employment::code($bulkV)] = true;
    }
    $bulkAll = $scope->seesEveryone($may('employee.list'));
    $openRows = array_values(array_filter($openRows, static fn (array $r): bool
        => $bulkAll || isset($bulkVisible[(string) ($r['emp_code'] ?? '')])));
    $mayDecide = $may('attendance.bulk.decide');
    // CODE => NAME, so a matched row's Employee column reads as somebody, not
    // just a code an approver has to look up before deciding.
    $bulkNameOfCode = [];
    foreach ($store->all('employees') as $bulkEmpRow) {
        $bulkEmpCode = Employment::code($bulkEmpRow);
        $bulkEmpCode === '' || $bulkNameOfCode[$bulkEmpCode] = trim((string) ($bulkEmpRow['name'] ?? ''));
    }

    // SINGLE PUNCH — SmartPRS 2's att-manual: one employee, one punch, applies
    // immediately (unlike the sheet below, which waits for approval). A search-by-
    // name picker that SUBMITS THE CODE, never a free-text name match: two
    // employees can share a name, but codes are unique (enforced at creation), so
    // picking a suggestion can never land the punch on the wrong payslip.
    $maySinglePunch = $may('attendance.punch.create.manual');
    $todayForPunch = date('Y-m-d');
    $nowForPunch = date('H:i');
    $manualEmployeeLabels = [];

    if ($maySinglePunch) {
        foreach ($scope->only($store->all('employees'), $may('attendance.day.view.history')) as $me) {
            $meCode = Employment::code($me);
            $meCode !== '' && $manualEmployeeLabels[$meCode] = Employment::label($me);
        }
    }
?>
