<?php
    $mFrom = (string) ($_GET['from'] ?? date('Y-m-01'));
    $mTo = (string) ($_GET['to'] ?? date('Y-m-d'));
    // The period picker (month / year / MTD / custom — the muster is at most
    // config/attendance-report.json's max_range_days wide, 12 months by default) sets From and To.
    $mPeriod = reportPeriod(isset($_GET['p']) ? $_GET : ['p' => 'custom', 'from' => $mFrom, 'to' => $mTo], financialYearStart($customisation), date('Y-m-d'));
    isset($_GET['p']) && [$mFrom, $mTo] = [$mPeriod['from'], $mPeriod['to']];
    $mCode = (string) ($_GET['code'] ?? '');
    $mDate = (string) ($_GET['date'] ?? '');
    $mProblem = '';
    $muster = ['dates' => [], 'rows' => [], 'legend' => []];
    $drill = null;
    $mayReadOthers = $may('attendance.day.view.history');
    $mayRate = $may('attendance.regularisation.review') || $may('leave.request.decide');
    // WHO SEES "EDIT" ON A ROW — the same deciding-role test the rating form
    // below uses. Asked for as "Manager, HR Manager and Company Admin"; written
    // as the PERMISSION those roles hold, never as a list of their names (Law 1
    // — no business literal in code). Which roles hold it is the tenant's own
    // answer on Roles & Permissions, so a client who calls the job something
    // else, or adds a fourth role that should have it, changes nothing here.
    $mayFixDay = $mayRate;
    $mQuery = '';   // the filters, carried on every link so a drill-down keeps the view

    // THE FILTERS, from the same lists every other dropdown in the product uses
    // (orgScopes), so the report offers exactly the companies, branches,
    // departments, designations and teams this tenant has set up — and the
    // employees in the viewer's scope, nobody else.
    $mFilter = orgFilter();
    $mScoped = $scope->only($store->all('employees'), $mayReadOthers);
    $mOptions = orgFilterOptions($store, $mScoped);
    $musterEmployments = orgFilterApply($store, $mScoped, $mFilter);

    // Columns AND the configured range ceiling live in the same declared file —
    // read once, before the muster, since the ceiling gates the call below.
    $mColumns = AttendanceReport::columns(__DIR__ . '/../config/attendance-report.json', $customisation);

    try {
        $muster = $attendanceReport->muster($musterEmployments, $mFrom, $mTo,
            $calendar->shiftStart(), $calendar->shiftEnd(), date('Y-m-d'), $mColumns['max_range_days']);

        if ($mCode !== '' && $mDate !== '') {
            $drillId = (string) (employmentIdFor($store, $mCode) ?? '');

            if (!$scope->covers($drillId, $mayReadOthers)) {
                $mProblem = $scope->why($drillId);
            } else {
                $drill = $attendanceReport->day($mCode, $mDate, $calendar->shiftStart(), $calendar->shiftEnd());
            }
        }
    } catch (\Throwable $e) {
        $mProblem = $e->getMessage();
    }

    $mQuery = orgFilterQuery($mFilter);

    // THE DAILY VIEW — SmartPRS 2's shape, one row per employee-day — in the
    // columns this tenant chose under Configuration → Attendance report.
    $mView = (string) ($_GET['v'] ?? 'grid') === 'daily' ? 'daily' : 'grid';
    $mDaily = [];

    if ($mView === 'daily' && $muster['rows'] !== []) {
        $byIdAll = [];
        $labels = [];

        foreach ($store->all('employees') as $e) {
            $byIdAll[(string) $e['id']] = $e;
            $labels[(string) $e['id']] = Employment::label($e);
        }

        $mDaily = $attendanceReport->daily($muster, $byIdAll,
            attendanceLookups($store, $labels),
            $calendar->shiftStart() . '–' . $calendar->shiftEnd(), $mColumns['labels'],
            liveRows($store, 'late_policy'));
    }

    $mQuery .= $mView === 'daily' ? '&amp;v=daily' : '';
?>
<?php // WHICH MENU ITEM OPENED THIS. One screen, two ways in (see the alias near
      // the top of this file): Attendance Report is the grid, Attendance Logs is
      // the same settlement one row per employee-day. $rawRoute is the original,
