  <?php // ONE DIALOG FOR THE WHOLE TABLE, filled on click. A <dialog> because
        // the browser already does the modal, the backdrop, Escape and the
        // focus trap — none of which is worth reimplementing, and all of which
        // a hand-rolled div gets subtly wrong. ?>
  <dialog id="day-log-dlg" class="help-dlg" style="width:min(820px,94vw)">
    <div class="help-head">
      <div class="help-badge"><i class="fas fa-clock-rotate-left"></i></div>
      <div style="flex:1">
        <div class="help-eyebrow">Attendance log</div>
        <div class="help-title" id="day-log-title">&nbsp;</div>
      </div>
      <i class="fas fa-xmark" title="Close" onclick="document.getElementById('day-log-dlg').close()"
         style="font-size:18px;color:var(--text3);cursor:pointer;padding:4px"></i>
    </div>
    <div class="help-body" id="day-log-body"></div>
  </dialog>
<script>
(function () {
  var dlg = document.getElementById('day-log-dlg');
  if (!dlg || typeof dlg.showModal !== 'function') { return; }   // link still works
  var body = document.getElementById('day-log-body');
  var title = document.getElementById('day-log-title');
  var token = 0;

  document.addEventListener('click', function (e) {
    var link = e.target.closest('[data-daylog]');
    if (!link) { return; }
    e.preventDefault();
    // EVERY OPEN GETS A TICKET. Click three rows quickly and three fetches are
    // in flight; without this the one that answers LAST wins the dialog, which
    // is not the one anybody asked for.
    var mine = ++token;
    title.textContent = link.getAttribute('data-daylog-title') || '';
    body.innerHTML = '<p class="note">Loading&hellip;</p>';
    dlg.showModal();

    fetch(link.getAttribute('data-daylog'), {credentials: 'same-origin'})
      .then(function (r) { return r.text(); })
      .then(function (html) { if (mine === token) { body.innerHTML = html; } })
      .catch(function () {
        if (mine === token) {
          body.innerHTML = '<p class="problem" style="margin:0">That day could not be loaded. '
            + '<a href="' + link.getAttribute('href') + '">Open it on its own page</a> instead.</p>';
        }
      });
  });

  // Clicking the backdrop closes it. A <dialog> puts the backdrop on the dialog
  // element itself, so a click that lands on the element and not on its content
  // is a click outside.
  dlg.addEventListener('click', function (e) { if (e.target === dlg) { dlg.close(); } });
})();
</script>
