<?php
    $kaGroups = $kraKpi->achievableByKra();
    $kaKnown = $kraKpi->kpis();
    $kaMayRecord = $may('employee.update');
    // ONLY PEOPLE THIS ACCOUNT MAY SEE (owner, 28 Sep) — the recorded list and
    // the lookup list alike; an employee sees their own, a manager their tree.
    $kaVisibleCodes = [];
    foreach ($scope->only(liveRows($store, 'employees'), $may('employee.list')) as $kaV) {
        $kaVisibleCodes[Employment::code($kaV)] = (string) ($kaV['name'] ?? '');
    }
    $kaEntries = array_values(array_filter($kraKpi->achievements(),
        static fn (array $en): bool => isset($kaVisibleCodes[(string) ($en['employee_code'] ?? '')])));
    $kaToday = date('Y-m-d');

    // WHOSE PROFILE THIS SCREEN IS FILTERED TO. NO EMPLOYEE ID MEANS YOUR
    // OWN — the same convention the "me" self-service screen uses — so a
    // signed-in employee lands straight on their own kept KPIs, and HR can
    // still look another employee up by code.
    $kaLookup = trim((string) ($_GET['emp'] ?? ''));
    $kaEmploymentId = $kaLookup !== '' ? (string) (employmentIdFor($store, $kaLookup) ?? '') : (string) ($scope->own() ?? '');
    $kaProfile = $kaEmploymentId === '' ? null : $store->find('employees', $kaEmploymentId);
    $kaProfileFound = $kaLookup !== '' && $kaProfile === null;
    $kaMayViewProfile = $kaProfile !== null && $scope->covers($kaEmploymentId, $may('employee.list'));

    // ONLY KPIs KEPT FOR THIS EMPLOYEE'S OWN SCOPE — the same set
    // `resolveTarget()` would accept, via the one scope-matching pass
    // (`kpisEnabledFor()`/`winningRows()`) shared with it, so a KPI offered
    // here is never one `record()` then refuses as unconfigured.
    $kaEnabled = $kaMayViewProfile ? $kraKpi->kpisEnabledFor($kaToday,
        orgValueOf($store, $kaProfile, 'company'),
        orgValueOf($store, $kaProfile, 'branch'),
        orgValueOf($store, $kaProfile, 'team'),
        orgValueOf($store, $kaProfile, 'role'),
        orgValueOf($store, $kaProfile, 'designation'),
        SmartPRS\Surface\Employment::code($kaProfile)) : [];
    $kaFilteredGroups = array_values(array_filter(array_map(
        static fn (array $grp): array => ['kra' => $grp['kra'], 'items' => array_values(array_filter(
            $grp['items'], static fn (array $item): bool => in_array((string) $item['code'], $kaEnabled, true),
        ))],
        $kaGroups,
    ), static fn (array $grp): bool => $grp['items'] !== []));
?>
