    $funnel = $recruitment->funnel($openReq === '' ? null : $openReq);
    $stageLabel = static fn (string $st): string => ucwords(str_replace('_', ' ', $st));
    // "550000.0000" (a DECIMAL column) shown as 550000.
    $rcAmt = static fn (string $x): string => str_contains($x, '.') ? rtrim(rtrim($x, '0'), '.') : $x;
?>
