        <button type="button" class="btn btn-outline btn-sm" style="margin-top:6px" onclick="const w=window.open('','_blank');w.document.write('<pre style=&quot;white-space:pre-wrap;font:12pt Georgia,serif;margin:40px&quot;>'+document.getElementById('offer-letter').innerHTML+'</pre>');w.document.close();w.focus();w.print()"><i class="fas fa-print"></i> Print / save as PDF</button></details>
<?php else: ?><p class="problem" style="margin:8px 0 0">Offer letter not ready: <?= e(implode(', ', $ofLetter['missing'])) ?> missing on this candidate<?= in_array('Address', $ofLetter['missing'], true) ? ' (Address is the candidate\'s Location)' : '' ?>.</p><?php endif; ?>
