<?php elseif ($route === 'id-cards'): ?>
<?php
    $cardFilter = orgFilter();
    $cardScoped = $scope->only($store->all('employees'), $may('employee.list'));
    $cardOptions = orgFilterOptions($store, $cardScoped);
    $cardRows = orgFilterApply($store, $cardScoped, $cardFilter);
    usort($cardRows, static fn (array $a, array $b): int => strcmp(Employment::code($a), Employment::code($b)));
    $cardPick = (string) ($_GET['id'] ?? '');
    $cardVisitId = (string) ($_GET['visitor'] ?? ($_SESSION['id_card_last_visitor'] ?? ''));
    unset($_SESSION['id_card_last_visitor']);
    $cardVisit = null;

    try {
        $cardVisit = $cardVisitId !== '' ? $store->find('visitor_log', $cardVisitId) : null;
    } catch (\Throwable) {
        // gate:allow-swallow visitor_log migration not yet applied on this installation
    }
    // A TEMPLATE CARD (Visitor, or any type under ID Card Format's "Card
    // types"), picked from the same dropdown as a real employee — none of
    // $idCardExternalTypes' sentinel ids is ever a real employees.id, so it is
    // never scope-checked and never looked up in the store; the synthetic row
    // exists purely so formatFor() can match a format someone scoped to
    // "Employee: Visitor"/"Employee: Client" in the Format Designer, exactly
    // as it matches a real person. A REAL VISIT ($cardVisit, from the entry
    // form below) overlays its own entered name/mobile/phone/address/purpose
    // on top of that bare template.
    $cardTemplateLabel = $idCardExternalTypes[$cardPick] ?? null;
    $cardIsTemplate = $cardVisit !== null || $cardTemplateLabel !== null;

    if ($cardVisit !== null) {
        $cardOne = IdCardFormat::templateRowFor((string) ($cardVisit['type_id'] ?? IdCardFormat::VISITOR_ID), (string) ($cardVisit['type_label'] ?? 'Visitor'));
        $cardOne['name'] = (string) ($cardVisit['name'] ?? $cardOne['name']);
        $cardOne['mobile'] = (string) ($cardVisit['mobile'] ?? '');
        $cardOne['visit_phone'] = (string) ($cardVisit['phone'] ?? '');
        $cardOne['address'] = (string) ($cardVisit['address'] ?? '');
        $cardOne['visit_purpose'] = (string) ($cardVisit['purpose'] ?? '');
    } elseif ($cardTemplateLabel !== null) {
        $cardOne = IdCardFormat::templateRowFor($cardPick, $cardTemplateLabel);
    } else {
        $cardOne = $cardPick === '' ? null : $store->find('employees', $cardPick);
    }

    if ($cardOne !== null && !$cardIsTemplate && !$scope->covers($cardPick, $may('employee.list'))) {
        $cardOne = null;
        $problem = $scope->why($cardPick);
    }

    $cardCompany = null;

    if ($cardOne !== null) {
        try {
            // A template/visitor belongs to no company by definition; default to
            // the tenant's first one so the preview still carries a real logo/
            // name rather than falling back to the bare tenant name for no reason.
            $cardCompany = $store->find('companies', (string) ($cardOne['employer_company_id'] ?? ''))
                ?? ($cardIsTemplate ? (liveRows($store, 'companies')[0] ?? null) : null);
        } catch (\Throwable) {
            // gate:allow-swallow no companies table on the file store: the card prints the tenant's name instead
        }
    }

    // ROLE OVERLAID THE SAME WAY AS THE PDF ACTION ABOVE — never employees.role.
    $cardOneScoped = $cardOne === null ? null : ['role' => orgValueOf($store, $cardOne, 'role')] + $cardOne;
    $cardFormat = $cardOneScoped === null ? $idCardFormat->format() : $idCardFormat->formatFor($cardOneScoped)['format'];
    $cardNamed = $cardOneScoped === null ? null : $idCardFormat->formatFor($cardOneScoped)['entry'];

    // THE EMPLOYEE PICKER — only real employees are offered a card (11 Sep:
    // Visitor/Client/Guest templates removed), so this is just everybody in
    // scope, jumpable directly instead of scrolling the table below.
    $cardPickerOptions = [];
    foreach ($cardScoped as $cpE) { $cardPickerOptions[(string) $cpE['id']] = Employment::label($cpE); }
?>
