      <input type="hidden" name="r" value="id-cards">
      <div style="min-width:260px"><label for="card-pick">Employee</label>
        <?= employeePicker('card-pick', 'id', $cardPickerOptions,
            $cardVisit === null ? $cardPick : '', '— type to search —', false, 'onchange="this.form.submit()"') ?>
      </div>
      <p class="note" style="margin:0">An employee resolves the most specific format saved for their company, branch, department, designation or their own record &mdash; most specific wins.</p>
    </form>
  </div>
<?php if ($cardOne === null): ?>
  <div class="card"><?= orgFilterBar('id-cards', $cardFilter, $cardOptions) ?></div>
<?php endif; ?>
<?php if ($cardOne !== null): ?>
<?php $cardData = idCardFor($idCardFormat, $cardFormat, orgEnrich($store, $cardOne), $cardCompany, $company, __DIR__, $cardIsTemplate ? (string) $cardOne['designation'] : ''); ?>
