<?php elseif ($route === 'transfers' && !$may('employee.transfer.view')): ?>
  <div class="page-header"><div><h2>Transfers</h2></div></div>
  <div class="card"><div class="problem" style="margin:0">Denied: <?= e($access->decide(
      (string) $session->user()['role'], 'employee.transfer.view')->summary) ?></div></div>

<?php elseif ($route === 'transfers'): ?>
<?php
    // SMARTPRS 2's TRANSFERS: raise (type, destination, effective date, reason),
    // approve by somebody else, the order letter with an acknowledgement, apply
    // on the effective date, and a per-row process tracker. Rows come from
    // surface/partials/people-transfers-data.php — the Excel/CSV too.
    $params = $_GET;
    include __DIR__ . '/../surface/partials/people-transfers-data.php';
    $trNames = orgNames($store);
    $trCompanies = [];
    try { $trCompanies = liveRows($store, 'companies'); } catch (\Throwable) { /* gate:allow-swallow no companies table on a file store; the dropdown is simply empty */ }
    $trLetter = $letters->find('transfer');
    $trMayEdit = $may('employee.update');
    $trMe = (string) ($session->user()['employee_id'] ?? '');
    $trPreviewId = (string) ($_GET['letter'] ?? '');
    $trPreview = null;
    if ($trPreviewId !== '') {
        $trT = $transfers->find($trPreviewId);
        $trSubject = $trT === null ? null : ($trById[(string) $trT['employee_id']] ?? null);
        $trPreview = $trT !== null && $trSubject !== null && $trLetter !== null
            ? $letters->render($trLetter, orgEnrich($store, $trSubject), ['company' => $company] + Transfers::letterContext($trT)) : null;
    }
    // THE ORDER GOES OUT ON APPROVAL: every approved transfer whose order was never
    // issued gets its acknowledgement token now and the employee a queued message
    // with the link (nothing is transmitted until a transport exists — see
    // Notifications). Once per transfer: order_sent_at says so.
    foreach ($trRows as $trI => $trT) {
        if (in_array((string) $trT['status'], [Transfers::APPROVED, Transfers::APPLIED], true) && trim((string) ($trT['order_sent_at'] ?? '')) === '') {
            $trTok = $transfers->issueOrder((string) $trT['id'], date('Y-m-d H:i:s'));
            $trE = $trById[(string) $trT['employee_id']];
            try {
                $trTok !== null && $notifications->queue('transfer.approved', Employment::code($trE), 'transfer.approved:' . $trT['id'], ['name' => trim((string) ($trE['name'] ?? '')), 'code' => Employment::code($trE),
                    'type' => (string) ($trT['type'] ?? ''), 'to' => $trTo($trT), 'effective' => (string) $trT['effective_date'], 'reason' => (string) $trT['reason'], 'link' => '?r=transfers&ack=' . $trT['id'] . '&t=' . $trTok]);
            } catch (\InvalidArgumentException) {
                // gate:allow-swallow config/notifications.d/people.json does not declare transfer.approved on this installation; the order is still issued and the tracker says so
            }
            $trRows[$trI] = $transfers->find((string) $trT['id']) ?? $trT;
        }
    }
    $trAck = (string) ($_GET['ack'] ?? '');
    $trAckTok = (string) ($_GET['t'] ?? '');
    $trOpenCount = count(array_filter($trRows, static fn (array $t): bool => $t['status'] === Transfers::PENDING));
    $trDue = count(array_filter($trRows, static fn (array $t): bool => $t['status'] === Transfers::APPROVED && (string) $t['effective_date'] <= date('Y-m-d')));
    $trCounts = [];
    foreach ($transfers->all() as $trT) { isset($trById[(string) $trT['employee_id']]) && $trCounts[(string) $trT['status']] = ($trCounts[(string) $trT['status']] ?? 0) + 1; }
    $trBadge = ['pending' => 'badge-amber', 'approved' => 'badge-blue', 'applied' => 'badge-green', 'rejected' => 'badge-red'];
    $trStepColour = ['done' => '#16a34a', 'fail' => '#b91c1c', 'prog' => '#f59e0b', 'todo' => '#cbd5e1'];
