<?php
    // THE ARCHIVE — every day a grant put on (or a year-end lapse took off) a
    // ledger in a year before this one, read from leave_entries themselves
    // (`grant:<id>:<year>` / `lapse:<id>:<year>`), plus withdrawn grants. The
    // ledger is the record; this only lists it, so it cannot disagree with a
    // balance.
    $laYear = (string) ($_GET['a_year'] ?? '');
    $laFilter = ['company' => trim((string) ($_GET['a_company'] ?? '')), 'branch' => trim((string) ($_GET['a_branch'] ?? '')), 'department' => trim((string) ($_GET['a_department'] ?? ''))];
    $laByCode = [];
    foreach ($ltEmployments as $laE) { $laByCode[Employment::code($laE)] = $laE; }
    $laGrantsById = [];
    foreach ($ltGrants as $laG) { $laGrantsById[(string) $laG['id']] = $laG; }
    $laRows = [];
    $laYears = [];

    foreach ($store->all('leave_entries') as $laEnt) {
        if (preg_match('/^(grant|lapse):([^:]+):(\d{4})$/', (string) ($laEnt['source_reference'] ?? ''), $laM) !== 1 || $laM[3] >= $ltThisYear) {
            continue;
        }

        $laE = $laByCode[(string) ($laEnt['employment_id'] ?? '')] ?? null;

        if ($laE === null) { continue; } // not an employee this viewer may see

        $laYears[$laM[3]] = true;

        if ($laYear !== '' && $laM[3] !== $laYear) { continue; }

        foreach ($laFilter as $laK => $laV) {
            if ($laV !== '' && strcasecmp(orgValueOf($store, $laE, $laK), $laV) !== 0) { continue 2; }
        }

        $laRows[] = ['year' => $laM[3], 'what' => $laM[1], 'grant' => $laGrantsById[$laM[2]] ?? null, 'grant_id' => $laM[2], 'e' => $laE,
            'type' => (string) ($laEnt['leave_type'] ?? ''), 'days' => (string) ($laEnt['days'] ?? ''), 'on' => (string) ($laEnt['effective_on'] ?? '')];
    }

    usort($laRows, static fn (array $a, array $b): int => [$b['year'], $a['grant_id'], Employment::code($a['e'])] <=> [$a['year'], $b['grant_id'], Employment::code($b['e'])]);
    krsort($laYears);
    $laWithdrawn = array_values(array_filter($ltGrants, static fn (array $g): bool => !($g['active'] ?? true)));
?>
