        <thead><tr><th>Code</th><th>Name</th><th>Paid</th><th class="n">Opening days</th><th class="n">Accrual / month</th><th class="n">Maximum</th><th>Carry forward</th><th>Encashable</th><?php foreach (SmartPRS\Surface\LeavePolicy::SCOPE_DIMENSIONS as $ltD): ?><th><?= e(ucfirst($ltD)) ?></th><?php endforeach; ?><th>Note</th></tr></thead>
        <tbody id="lt-rows">
<?php // NO STOCK BLANK ROWS: the saved types, then ONE blank row in a <template>
      // that "Add leave type" clones with the next index (`__i__` placeholder).
      // Same pattern as the Holiday / W.OFF schedule. Blank rows are still
      // ignored on save. The org dropdowns cascade via the layout's delegated
      // ORG CASCADE listener, so cloned rows narrow like saved ones. ?>
<?php foreach (array_merge($ltTypes, ['__i__' => []]) as $i => $lt): $ltN = "types[{$i}]"; ?>
<?php if ($i === '__i__'): ?>
          <template id="lt-new">
<?php endif; ?>
          <tr>
            <td><input name="<?= $ltN ?>[code]" value="<?= e((string) ($lt['code'] ?? '')) ?>" style="width:5.5rem;text-transform:uppercase" placeholder="e.g. ML"></td>
            <td><input name="<?= $ltN ?>[name]" value="<?= e((string) ($lt['name'] ?? '')) ?>" placeholder="Maternity leave"></td>
            <td><select name="<?= $ltN ?>[paid]" style="width:auto"><option value="yes" <?= ($lt['paid'] ?? true) ? 'selected' : '' ?>>Yes</option><option value="no" <?= isset($lt['paid']) && !$lt['paid'] ? 'selected' : '' ?>>No</option></select></td>
