            <td><select name="<?= $ltN ?>[encashable]" style="width:auto"><option value="no" <?= empty($lt['encashable']) ? 'selected' : '' ?>>No</option><option value="yes" <?= !empty($lt['encashable']) ? 'selected' : '' ?>>Yes</option></select></td>
<?php // WHO THIS TYPE APPLIES TO — ALL, or one company / branch / department /
      // role / designation (every one named must match). The row's dropdowns
