<?php elseif ($route === 'setup-holidays'): ?>
<?php
    $hcConfig = $calendar->config();
    $hcAll = (array) ($hcConfig['holidays'] ?? []);
    $hcOff = array_map('strval', (array) ($hcConfig['weekly_off'] ?? []));
    $hcTypes = $calendar->holidayTypes();
    // ANY YEAR. This product outlives the years it ships with: the picker offers
    // the years that have holidays and the next few, and accepts any year typed.
    $hcYears = array_values(array_unique(array_merge(array_map(static fn (int $i): string => (string) ((int) date('Y') + $i), range(-1, 5)),
        array_map(static fn (array $h): string => substr((string) $h['on'], 0, 4), $hcAll))));
    sort($hcYears);
    $hcYear = preg_match('/^2\d{3}$/', (string) ($_GET['year'] ?? '')) === 1 ? (string) $_GET['year'] : date('Y');
    // RECURRING HOLIDAYS SHOW ON EVERY YEAR'S SCREEN — New Year's Day is not
    // "2026's holiday", it is every year's, so filtering it out for 2027 would
    // hide the very holiday this feature exists to keep off the re-entry list.
    $hcRecurring = array_values(array_filter($hcAll, static fn (array $h): bool => (bool) ($h['recurring'] ?? false)));
    $hcDated = array_values(array_filter($hcAll, static fn (array $h): bool => !($h['recurring'] ?? false) && str_starts_with((string) $h['on'], $hcYear)));
    $hcHolidays = array_merge($hcRecurring, $hcDated);
    usort($hcHolidays, static fn (array $a, array $b): int => strcmp(
        ($a['recurring'] ?? false) ? '0000-' . substr((string) $a['on'], 5) : (string) $a['on'],
        ($b['recurring'] ?? false) ? '0000-' . substr((string) $b['on'], 5) : (string) $b['on'],
    ));
    $hcOtherYears = count($hcAll) - count($hcRecurring) - count($hcDated);
    // SCOPE PICKERS — the same org lists Leave Grants and ID Cards already
    // scope by. Role is a NAME, from Role/Designation Setup, never
    // employees.role (the RBAC access tier) — see Calendar::holidayMatches().
    $hcOrgNames = orgNames($store);
    $hcRoleList = array_values(array_unique(array_filter($hcOrgNames['designation_roles'] ?? [])));
    sort($hcRoleList);
    $hcScopeOptions = [
        'company' => array_values(array_filter($hcOrgNames['companies'] ?? [])),
        'branch' => array_values(array_filter($hcOrgNames['branches'] ?? [])),
        'role' => $hcRoleList,
        'designation' => array_values(array_filter($hcOrgNames['designations'] ?? [])),
    ];
    // No `scope` key yet (every holiday shipped or saved before this feature)
    // defaults every dimension to Any, checked — matching Calendar::
    // holidayMatches()'s own "no scope key reaches everybody" rule, so opening
    // this screen and saving again does not narrow anything by accident.
    $hcScopeChecked = static fn (array $h, string $dim, string $value): bool =>
        in_array($value, (array) ($h['scope'][$dim] ?? [Calendar::ANY]), true);
    // EXTRA W.OFF SCHEDULES (owner, 30 Oct) — Applies-to choices exactly as Late Login
    // Policy offers them: ids for the org registers, names for Role, codes for Employee.
    $hcWoff = $calendar->woffSchedules();
    $hcBranchLabel = [];
    foreach (liveRows($store, 'branches') as $hcB) {
        $hcCo = (string) (($hcOrgNames['companies'] ?? [])[(string) ($hcB['employer_company_id'] ?? $hcB['company_id'] ?? '')] ?? '');
        $hcBranchLabel[(string) $hcB['id']] = trim((string) ($hcB['name'] ?? '')) . ($hcCo !== '' ? ' (' . $hcCo . ')' : '');
    }
    $hcApChoices = [
        'company' => (array) ($hcOrgNames['companies'] ?? []), 'branch' => $hcBranchLabel,
        'department' => (array) ($hcOrgNames['departments'] ?? []),
        'role' => $hcRoleList === [] ? [] : array_combine($hcRoleList, $hcRoleList),
        'designation' => (array) ($hcOrgNames['designations'] ?? []), 'team' => (array) ($hcOrgNames['teams'] ?? []),
        'employee' => [], 'staff_type' => [], 'employee_type' => [],
    ];
    foreach (['company', 'branch', 'department', 'designation', 'team'] as $hcK) { asort($hcApChoices[$hcK]); }
    // WHO FOLLOWS WHICH SCHEDULE NOW — counted with the same resolver attendance uses.
    $hcFollow = [];
    $hcRoles = (array) ($hcOrgNames['designation_roles'] ?? []);
    foreach ($scope->only($store->all('employees'), $may('employee.list')) as $hcE) {
        $hcC = SmartPRS\Surface\Employment::code($hcE);
        $hcC !== '' && $hcApChoices['employee'][$hcC] = SmartPRS\Surface\Employment::label($hcE);
        if ($hcC === '' || trim((string) ($hcE['exit_date'] ?? '')) !== '' || (string) ($hcE['is_active'] ?? '1') === '0') { continue; }
        $hcN = $calendar->scheduleFor($hcE, $hcRoles)['name'];
        $hcFollow[$hcN] = ($hcFollow[$hcN] ?? 0) + 1;
    }
    ksort($hcApChoices['employee']);
    foreach ((array) (json_decode((string) @file_get_contents(__DIR__ . '/../config/employee-fields.json'), true)['sections'] ?? []) as $hcSec) {
        foreach ((array) ($hcSec['fields'] ?? []) as $hcF) {
            $hcSlot = ['type' => 'staff_type', 'employment_type' => 'employee_type'][(string) ($hcF['code'] ?? '')] ?? null;
            $hcSlot !== null && $hcApChoices[$hcSlot] = array_combine((array) $hcF['options'], (array) $hcF['options']) ?: [];
        }
    }
    $hcPresets = ['Sun' => 'Every Sunday', 'Sat,Sun' => 'Every Saturday and Sunday', 'Sun|Sat:1,4' => 'Every Sunday + 1st and 4th Saturday',
        'Sun|Sat:2,4' => 'Every Sunday + 2nd and 4th Saturday', 'Sun|Sat:1,3,5' => 'Every Sunday + 1st, 3rd and 5th Saturday',
        'Sun|Sat:2,3,4,5' => 'Every Sunday + all but the 1st Saturday', 'Fri' => 'Every Friday', '-' => 'No weekly off (7-day roster)'];
    // ONE EXTRA SCHEDULE BLOCK: name, Applies to, quick pattern, the tick grid.
    $hcBlock = static function (string $i, int $n, array $sc) use ($hcApChoices, $hcPresets, $hcFollow, $calendar): string {
        $ap = (array) ($sc['applies_to'] ?? []);
        $every = array_map('strval', (array) ($sc['weekly_off'] ?? []));
        $nth = (array) ($sc['weekly_off_nth'] ?? []);
        $new = $i === 'new';
        $o = '<div class="hc-sched" data-org-scope' . ($new ? ' id="hc-new" hidden' : '') . '>'
            . '<input type="hidden" name="woff[' . $i . '][on]" value="' . ($new ? '0' : '1') . '"' . ($new ? ' id="hc-new-on"' : '') . '>'
            . '<div class="hc-sched-h"><b>W.OFF Schedule ' . $n . '</b>'
            . '<input type="text" name="woff[' . $i . '][name]" value="' . e((string) ($sc['name'] ?? '')) . '" placeholder="Name, e.g. Field staff" style="width:16rem">'
            . ($new ? '' : '<span class="note">now: <b>' . e($calendar->weeklyOffLabel($sc)) . '</b> &middot; ' . (int) ($hcFollow[(string) ($sc['name'] ?? '')] ?? 0) . ' active employee(s) follow it</span>'
                . '<label class="note hc-rm"><input type="checkbox" name="woff[' . $i . '][remove]" value="1"> Remove this schedule</label>')
            . '</div><div class="hc-sec">Applies to <small>(ALL = no restriction on that field; pick at least one)</small></div>'
            . '<div class="table-wrap"><table class="hc-ap"><tr>';
        foreach (SmartPRS\Surface\LatePolicy::APPLIES_TO as $k => $label) { $o .= '<th>' . e($label) . '</th>'; }
        $o .= '</tr><tr>';
        foreach (SmartPRS\Surface\LatePolicy::APPLIES_TO as $k => $label) {
            $sel = (string) ($ap[$k] ?? '');
            if ($k === 'employee') {
                $o .= '<td>' . employeePicker('hc_emp_' . $i, 'woff[' . $i . '][ap][employee]', $hcApChoices['employee'], $sel, 'ALL') . '</td>';
                continue;
            }
            $o .= '<td><select name="woff[' . $i . '][ap][' . $k . ']"' . (in_array($k, ['company', 'branch', 'department', 'designation', 'role', 'team'], true) ? ' data-org="' . $k . '"' : '') . '><option value="">ALL</option>';
            foreach ($hcApChoices[$k] as $val => $lab) { $o .= '<option value="' . e((string) $val) . '"' . (strcasecmp((string) $val, $sel) === 0 ? ' selected' : '') . '>' . e((string) $lab) . '</option>'; }
            $sel !== '' && !isset($hcApChoices[$k][$sel]) && $o .= '<option value="' . e($sel) . '" selected>' . e($sel) . '</option>';
            $o .= '</select></td>';
        }
        $o .= '</tr></table></div><div class="row" style="align-items:flex-end;margin:8px 0"><div><label>Quick pattern</label>'
            . '<select onchange="hcPreset(this.value, this.closest(\'.hc-sched\').querySelector(\'.hc-off-t\'))" style="width:auto"><option value="">choose a common pattern, or tick below…</option>';
        foreach ($hcPresets as $pv => $pl) { $o .= '<option value="' . e($pv) . '">' . e($pl) . '</option>'; }
        $o .= '</select></div></div><div class="table-wrap"><table class="hc-off-t" style="max-width:640px"><thead><tr><th>Day</th><th>Every week</th>';
        foreach (['1st', '2nd', '3rd', '4th', '5th'] as $ord) { $o .= '<th>' . $ord . '</th>'; }
        $o .= '</tr></thead><tbody>';
        foreach (['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] as $d) {
            $isEvery = in_array($d, $every, true);
            $weeks = array_map('intval', (array) ($nth[$d] ?? []));
            $o .= '<tr data-day="' . $d . '" style="' . ($isEvery || $weeks !== [] ? 'background:#fff7ed' : '') . '"><td><b>' . $d . '</b></td>'
                . '<td><input type="checkbox" class="hc-every" name="woff[' . $i . '][weekly_off][]" value="' . $d . '"' . ($isEvery ? ' checked' : '') . ' onchange="hcRow(this)"></td>';
            foreach ([1, 2, 3, 4, 5] as $w) {
                $o .= '<td><input type="checkbox" class="hc-nth" name="woff[' . $i . '][weekly_off_nth][' . $d . '][]" value="' . $w . '"'
                    . (in_array($w, $weeks, true) ? ' checked' : '') . ($isEvery ? ' disabled' : '') . ' onchange="hcRow(this)"></td>';
            }
            $o .= '</tr>';
        }

        return $o . '</tbody></table></div></div>';
    };
?>
