<?php foreach (['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] as $hcD): $hcEvery = in_array($hcD, $hcOff, true); ?>
        <tr data-day="<?= $hcD ?>" style="<?= $hcEvery || ($hcNth[$hcD] ?? []) !== [] ? 'background:#fff7ed' : '' ?>">
          <td><b><?= $hcD ?></b></td>
          <td><input type="checkbox" class="hc-every" name="weekly_off[]" value="<?= $hcD ?>" <?= $hcEvery ? 'checked' : '' ?> onchange="hcRow(this)"></td>
<?php foreach ([1, 2, 3, 4, 5] as $hcW): ?>
          <td><input type="checkbox" class="hc-nth" name="weekly_off_nth[<?= $hcD ?>][]" value="<?= $hcW ?>" <?= in_array($hcW, $hcNth[$hcD] ?? [], true) ? 'checked' : '' ?> <?= $hcEvery ? 'disabled' : '' ?> onchange="hcRow(this)"></td>
<?php endforeach; ?>
        </tr>
<?php endforeach; ?>
      </tbody></table></div>
<?php foreach ($hcWoff as $hcI => $hcSc): ?><?= $hcBlock((string) $hcI, $hcI + 2, $hcSc) ?><?php endforeach; ?>
