        .hc-ap select, .hc-ap .emp-pick-text { min-width: 0 !important; width: 100% !important; max-width: 100% !important; }
      </style>
      <script>
        function hcRow(el) { var tr = el.closest('tr'); var every = tr.querySelector('.hc-every').checked; tr.querySelectorAll('.hc-nth').forEach(function (c) { c.disabled = every; if (every) { c.checked = false; } }); var any = every || Array.prototype.some.call(tr.querySelectorAll('.hc-nth'), function (c) { return c.checked; }); tr.style.background = any ? '#fff7ed' : ''; }
        function hcPreset(v, t) {
          t = t || document.getElementById('hc-off');
          t.querySelectorAll('input[type=checkbox]').forEach(function (c) { c.checked = false; c.disabled = false; });
          if (v && v !== '-') { v.split('|').forEach(function (part) { var day = part.split(':')[0]; var weeks = part.split(':')[1]; day.split(',').forEach(function (d) { var tr = t.querySelector('tr[data-day="' + d + '"]'); if (!tr) { return; } if (!weeks) { tr.querySelector('.hc-every').checked = true; } else { weeks.split(',').forEach(function (w) { var c = tr.querySelector('.hc-nth[value="' + w + '"]'); if (c) { c.checked = true; } }); } }); }); }
          t.querySelectorAll('.hc-every').forEach(hcRow);
        }
      </script>
      <h2 style="margin-top:18px">Holidays <?= e($hcYear) ?> <span class="note"><?= count($hcHolidays) ?> shown for <?= e($hcYear) ?> (<?= count($hcRecurring) ?> repeat every year) &middot; <?= $hcOtherYears ?> other dated holiday(s), untouched by this save</span></h2>
