            <td class="hc-day" style="font-weight:700;color:#1e3a5f"><?= ($hcH['on'] ?? '') !== '' ? e(date('l', strtotime((string) $hcH['on']))) : '' ?></td>
            <td><input name="holidays[<?= $i ?>][name]" value="<?= e((string) ($hcH['name'] ?? '')) ?>" placeholder="Holiday name"></td>
