            <td class="note"><label><input type="checkbox" class="hc-recurring" name="holidays[<?= $i ?>][recurring]" value="1" <?= $hcIsRecurring ? 'checked' : '' ?>> e.g. New Year's Day</label></td>
            <td>
              <input type="hidden" name="holidays[<?= $i ?>][scope_submitted]" value="1">
              <details>
