                        $hcVals = (array) ($hcH['scope'][$hcDim] ?? [Calendar::ANY]);
                        $hcParts[] = ucfirst($hcDim) . ': ' . (in_array(Calendar::ANY, $hcVals, true) ? 'any' : ($hcVals === [] ? 'none' : count($hcVals) . ' picked'));
                    }

                    echo e(implode(' · ', $hcParts));
                ?></summary>
                <div style="padding:8px 0 4px;display:grid;gap:10px;min-width:16rem">
<?php foreach (Calendar::HOLIDAY_SCOPES as $hcDim): ?>
                  <div>
                    <b class="note" style="text-transform:capitalize"><?= e($hcDim) ?></b><br>
                    <label class="note"><input type="checkbox" class="hc-scope-any" data-dim="<?= $hcDim ?>-<?= $i ?>" name="holidays[<?= $i ?>][scope][<?= $hcDim ?>][]" value="<?= Calendar::ANY ?>" <?= $hcScopeChecked($hcH, $hcDim, Calendar::ANY) ? 'checked' : '' ?>> <i>Any <?= e($hcDim) ?></i></label>
<?php if ($hcScopeOptions[$hcDim] === []): ?>
                    <span class="note" style="display:block;margin-left:10px">Nothing set up yet under Organization Setup.</span>
<?php endif; ?>
<?php foreach ($hcScopeOptions[$hcDim] as $hcOpt): ?>
                    <label class="note" style="display:block;margin-left:10px"><input type="checkbox" class="hc-scope-one" data-dim="<?= $hcDim ?>-<?= $i ?>" name="holidays[<?= $i ?>][scope][<?= $hcDim ?>][]" value="<?= e($hcOpt) ?>" <?= $hcScopeChecked($hcH, $hcDim, $hcOpt) ? 'checked' : '' ?>> <?= e($hcOpt) ?></label>
<?php endforeach; ?>
                  </div>
<?php endforeach; ?>
                </div>
              </details>
            </td>
          </tr>
<?php if ($i === '__i__'): ?>
