      <datalist id="br-states"><option>Telangana</option><option>Andhra Pradesh</option><option>Maharashtra</option><option>Karnataka</option><option>Delhi</option><option>Haryana</option><option>West Bengal</option><option>Tamil Nadu</option><option>Gujarat</option><option>Uttar Pradesh</option></datalist>
