        <button class="btn btn-primary"><i class="fas fa-save"></i> Save</button>
      </div>
      <p class="note">Hints in each field show the expected form; latitude/longitude are decimal degrees, used by field attendance and the Geo-Fence Map. <b>Delete</b> retires a branch (its history, attendance and transfers keep naming it) and is written on Save. A branch with staff cannot be deleted &mdash; transfer them first.</p>
    </form>
  </div>
  <script>
    function brEdit(b) { var tr = b.closest('tr'); tr.querySelectorAll('input[readonly]').forEach(function (i) { i.removeAttribute('readonly'); }); tr.querySelectorAll('select[disabled]').forEach(function (s) { s.removeAttribute('disabled'); }); tr.style.background = '#fff7ed'; tr.querySelector('input[name$="[code]"]').focus(); }
    function brDelete(b) {
      var tr = b.closest('tr'); var staff = parseInt(tr.querySelector('td.n').textContent, 10) || 0;
      if (staff > 0) { alert('This branch has ' + staff + ' staff. Transfer them first.'); return; }
      if (!confirm('Remove this branch? It is kept in history and stops being offered.')) { return; }
      tr.querySelector('.br-del').value = '1'; tr.style.opacity = '.4'; tr.style.textDecoration = 'line-through';
      tr.querySelectorAll('input:not([type=hidden])').forEach(function (i) { i.removeAttribute('required'); });
    }
    function brAdd() {
      var tb = document.querySelector('#br-table tbody'); var n = tb.querySelectorAll('tr').length;
      var tr = document.createElement('tr'); tr.style.background = '#fff7ed';
      tr.innerHTML = '<input type="hidden" name="rows[' + n + '][id]" value=""><input type="hidden" name="rows[' + n + '][delete]" value="" class="br-del">'
        + '<td><input name="rows[' + n + '][code]" placeholder="HYD1, Pune1" style="text-transform:uppercase"></td>'
        + '<td><input name="rows[' + n + '][name]" placeholder="Mindspace, Kondapur, Secunderabad" required></td>'
        + '<td><input name="rows[' + n + '][city]" placeholder="Hyderabad, Pune, Mumbai, Chennai, Bengaluru" list="br-cities"></td>'
        + '<td><input name="rows[' + n + '][state]" placeholder="Telangana, Maharashtra, Karnataka" list="br-states"></td>'
        + '<td><select name="rows[' + n + '][employer_company_id]"><option value="">—</option><?= implode('', array_map(static fn ($k, $v): string => '<option value="' . e((string) $k) . '">' . e($v) . '</option>', array_keys($brCompanies), $brCompanies)) ?></select></td>'
        + '<td><input name="rows[' + n + '][lat]" placeholder="17.4485" inputmode="decimal"></td><td><input name="rows[' + n + '][lng]" placeholder="78.3908" inputmode="decimal"></td>'
        + '<td class="n">0</td><td><button type="button" class="btn btn-outline" onclick="this.closest(\'tr\').remove()"><i class="fas fa-xmark"></i> Remove</button></td>';
      tb.appendChild(tr); tr.querySelector('input').focus();
    }
    // Latitude / Longitude follow the branch location: looked up (OpenStreetMap) from Branch Name, City and State
    // when blank on load, and again whenever one of those three changes. A value typed by hand is kept.
    (function () {
      var queue = [], busy = false;
      function v(tr, k) { var i = tr.querySelector('[name$="[' + k + ']"]'); return i ? i.value.trim() : ''; }
      function look(tr) {
        var lat = tr.querySelector('[name$="[lat]"]'), lng = tr.querySelector('[name$="[lng]"]');
        if (!lat || !lng || lat.dataset.manual === '1') { return; }
        var name = v(tr, 'name'), city = v(tr, 'city'), state = v(tr, 'state');
        if (!city && !state) { return; }
        queue.push({ lat: lat, lng: lng, tries: [[name, city, state, 'India'], [city, state, 'India']].map(function (a) { return a.filter(Boolean).join(', '); }) });
        next();
      }
      function next() { // ponytail: one request a second, the OpenStreetMap usage limit; fine for a branch list
        if (busy || !queue.length) { return; } busy = true;
        var job = queue.shift(), q = job.tries.shift();
        fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=in&q=' + encodeURIComponent(q)).then(function (r) { return r.json(); }).then(function (d) {
          if (d && d[0]) { job.lat.value = (+d[0].lat).toFixed(6); job.lng.value = (+d[0].lon).toFixed(6); job.lat.title = job.lng.title = 'Found for ' + q + ' — Save to keep'; job.lat.style.background = job.lng.style.background = '#ecfdf5'; }
          else if (job.tries.length) { queue.unshift(job); }
        }).catch(function () {}).then(function () { setTimeout(function () { busy = false; next(); }, 1100); });
      }
      var tb = document.querySelector('#br-table tbody');
      tb.addEventListener('change', function (ev) {
        var n = ev.target.name || '', tr = ev.target.closest('tr');
        if (/\[(lat|lng)\]$/.test(n)) { var m = ev.target.value.trim() !== '' ? '1' : ''; tr.querySelector('[name$="[lat]"]').dataset.manual = m; return; }
        if (/\[(name|city|state)\]$/.test(n)) { look(tr); }
      });
      tb.querySelectorAll('tr').forEach(function (tr) { var lat = tr.querySelector('[name$="[lat]"]'); if (lat && lat.value.trim() === '') { look(tr); } });
    })();
  </script>

