        $plPeriod ?? ($plMonth !== '' ? reportPeriod(['p' => 'month', 'month' => $plMonth], financialYearStart($customisation), date('Y-m-d')) : allPeriod()), PERIOD_MODES_ALL) ?></div>
  <div class="kpi-strip">
    <div class="kpi green"><h3><?= e($plFmt($plCredit)) ?></h3><p>earned</p><div class="sub">salary lines + commissions</div></div>
    <div class="kpi red"><h3><?= e($plFmt($plDebit)) ?></h3><p>paid out / deducted</p><div class="sub">payments + deductions</div></div>
    <div class="kpi blue"><h3><?= e($plFmt($plCredit - $plDebit)) ?></h3><p>balance</p><div class="sub">earned minus paid</div></div>
    <div class="kpi orange"><h3><?= count($plRows) ?></h3><p>entries</p><div class="sub">in this view</div></div>
  </div>
  <div class="card" style="padding:0">
<?php if ($plRows === []): ?><div class="empty"><i class="fas fa-book"></i>Nothing in the ledger for this view. Payslips appear when a period is generated; commissions and payments from their own screens.</div><?php else: ?>
    <div class="table-wrap"><table>
      <thead><tr><th>Date / month</th><th>Employee</th><th>Kind</th><th>Entry</th><th class="n">Credit</th><th class="n">Debit</th><th>Status</th><th>Source</th></tr></thead><tbody>
<?php foreach ($plRows as $r): ?>
      <tr><td><?= e($r['on']) ?></td><td><?= e(Employment::label($plById[$r['employee_id']])) ?></td>
        <td><span class="badge <?= in_array($r['kind'], ['salary', 'commission', 'incentive'], true) ? 'badge-green' : 'badge-amber' ?>"><?= e($r['kind']) ?></span></td>
        <td><?= e($r['label']) ?></td>
        <td class="n" style="font-family:var(--mono);color:#15803d"><?= $r['credit'] === '' ? '' : e($r['credit']) ?></td>
        <td class="n" style="font-family:var(--mono);color:#b91c1c"><?= $r['debit'] === '' ? '' : e($r['debit']) ?></td>
