    $fyDeclared = json_decode((string) file_get_contents(__DIR__ . '/../config/financial-year.json'), true) ?: [];
    $fySaved = (array) ($customisation->live()[(string) ($fyDeclared['customisation_key'] ?? 'financial-year')] ?? []);
    $fyStart = (int) ($fySaved['start_month'] ?? $fyDeclared['defaults']['start_month'] ?? 4);
    $fyLabel = static fn (int $startYear): string => $fyStart === 1 ? (string) $startYear : $startYear . '-' . substr((string) ($startYear + 1), 2);
    $fyCurrentStart = (int) date('n') >= $fyStart ? (int) date('Y') : (int) date('Y') - 1;
    $fyActive = (string) $fyCurrentStart; // only the current FY is ever active (owner, 22 Oct 2026)
    $fyRange = static fn (int $y): array => [sprintf('%04d-%02d-01', $y, $fyStart), $fyStart === 1 ? sprintf('%04d-12-31', $y) : date('Y-m-t', mktime(0, 0, 0, $fyStart - 1, 1, $y + 1))];
    // The years this company has data in, from the earliest joining to a few years ahead — never a fixed list.
    $fyFirst = $fyCurrentStart;
    foreach ($store->all('employees') as $fyE) { $fyJ = Employment::joinedOn($fyE); if ($fyJ !== '' && (int) substr($fyJ, 0, 4) < $fyFirst) { $fyFirst = (int) substr($fyJ, 0, 4); } }
    $fyYears = range(min($fyFirst, (int) $fyActive) - 1, max($fyCurrentStart, (int) $fyActive) + 3);
    $fyRuns = $register->runs();
    $fyCount = static function (int $y) use ($fyRange, $fyRuns): array {
        [$a, $b] = $fyRange($y); $n = 0; $paise = 0;
        foreach ($fyRuns as $r) { $p = (string) $r['period']; if ($p . '-01' >= $a && $p . '-01' <= $b) { $n++; $paise += (int) $r['net_minor']; } }
        return [$n, $paise];
    };
    $fyMonths = ['', 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
?>
  <div class="page-header">
    <div><h2>Financial Year</h2><p>When this company's year starts, and the active year for statutory and reporting screens &mdash; always the current financial year</p></div>
