      <div><label>Active financial year (starting year)</label><input type="number" name="active" value="<?= e($fyActive) ?>" min="2000" max="2199" step="1" list="fy-years" style="width:8rem"><datalist id="fy-years"><?php foreach ($fyYears as $y): ?><option value="<?= $y ?>"><?= e($fyLabel($y)) ?></option><?php endforeach; ?></datalist></div>
      <div><span class="note">Active: <b>FY <?= e($fyLabel((int) $fyActive)) ?></b> (<?= e(implode(' to ', $fyRange((int) $fyActive))) ?>) &middot; today falls in FY <?= e($fyLabel($fyCurrentStart)) ?></span></div>
      <div><button class="btn btn-primary">Save</button></div>
