        <td class="note"><?= e($fa) ?></td><td class="note"><?= e($fb) ?></td><td class="n"><?= $fyN ?></td><td class="n" style="font-family:var(--mono)"><?= e(Money::ofMinor($fyP)->format()) ?></td>
        <td></td></tr>
<?php endforeach; ?>
      </tbody></table></div>
