    // SMARTPRS 2's TEAMS: name, function, company, manager, team leader, status —
    // with the members counted from the employees that name the team.
    $tmVisible = $scope->only($store->all('employees'), $may('employee.list'));
    $tmById = [];
    foreach ($tmVisible as $tmE) { $tmById[(string) $tmE['id']] = $tmE; }
    $tmRows = array_values(array_filter($store->all('teams'), static fn (array $t): bool => (string) ($t['deleted_at'] ?? '') === ''));
    // MEMBERS: the employees whose record names the team (team_id, or the team's
    // name in the text column) — plus, per team leader, everybody reporting to them.
    $tmMembers = [];
    $tmReports = [];
    foreach ($tmVisible as $tmE) {
        $tmTid = (string) ($tmE['team_id'] ?? '');
        $tmK = strtolower(trim((string) ($tmE['team'] ?? '')));
        $tmTid !== '' && $tmMembers['id:' . $tmTid][] = $tmE;
        $tmK !== '' && $tmMembers[$tmK][] = $tmE;
        $tmMgr = (string) ($tmE['reporting_manager_id'] ?? '');
        $tmMgr !== '' && $tmReports[$tmMgr][] = $tmE;
    }
    $tmMembersOf = static function (array $tm) use ($tmMembers): array {
        $byId = $tmMembers['id:' . (string) $tm['id']] ?? [];
        $byName = $tmMembers[strtolower(trim((string) $tm['name']))] ?? [];
        $seen = [];
        $out = [];
        foreach (array_merge($byId, $byName) as $e) { if (!isset($seen[(string) $e['id']])) { $seen[(string) $e['id']] = true; $out[] = $e; } }
        return $out;
    };
    usort($tmRows, static fn (array $a, array $b): int => strcmp((string) $a['name'], (string) $b['name']));
    $tmCompanies = [];
    try { foreach (liveRows($store, 'companies') as $tmC) { $tmCompanies[(string) $tmC['id']] = (string) ($tmC['name'] ?? ''); } } catch (\Throwable) { /* gate:allow-swallow no companies table on a file store */ }
    $tmEdit = (string) ($_GET['edit'] ?? '') === '' ? null : $store->find('teams', (string) $_GET['edit']);
    $tmOpen = (string) ($_GET['open'] ?? '');
    $tmMayEdit = $may('employee.update');
    $tmWho = static fn ($id): string => isset($tmById[(string) $id]) ? Employment::label($tmById[(string) $id]) : ((string) $id === '' ? '—' : '#' . $id);
?>
