    $dtGaps = count(array_filter($dtMissing, static fn (array $m): bool => $m !== []));
    $dtBadge = static fn (string $exp) => $exp === '' ? '<span class="note">—</span>' : ($exp < $dtToday ? '<span class="badge badge-red">expired ' . e($exp) . '</span>' : ($exp <= $dtSoon ? '<span class="badge badge-amber">expires ' . e($exp) . '</span>' : '<span class="badge badge-green">till ' . e($exp) . '</span>'));
    $dtStatusBadge = ['approved' => 'badge-green', 'rejected' => 'badge-red', 'pending' => 'badge-amber'];
    $dtKeep = orgFilterKeep($dtFilter) + array_filter(['q' => $dtQ, 'missing' => $dtShowMissing ? '1' : '']);
    $peopleExport = ['screen' => 'documents', 'keep' => $dtKeep];
?>
