  <script>
  (function () {
    // ONE EMPLOYEE, MANY DOCUMENTS: "Add another document" clones the template
    // row and renumbers its fields (docs[0][…] -> docs[N][…], doc_0 -> doc_N) so
    // each row's file lands in its own $_FILES entry; the remove button (event-
    // delegated, so it works on clones too) never drops the last row.
    var rows = document.getElementById('dt-rows');
    var addBtn = document.getElementById('dt-add-row');
    var n = 1;
    addBtn && addBtn.addEventListener('click', function () {
      var clone = rows.querySelector('.dt-row').cloneNode(true);
      clone.querySelectorAll('[name]').forEach(function (el) {
        el.name = el.name.replace(/docs\[0\]/, 'docs[' + n + ']').replace(/^doc_0$/, 'doc_' + n);
        if (el.tagName === 'SELECT') { el.selectedIndex = 0; } else { el.value = ''; }
      });
      rows.appendChild(clone);
      n++;
    });
    rows.addEventListener('click', function (e) {
      var btn = e.target.closest('.dt-row-remove');
      if (btn && rows.querySelectorAll('.dt-row').length > 1) { btn.closest('.dt-row').remove(); }
    });
    // OPENED MORE THAN ONCE WITHOUT A PAGE RELOAD (Cancel, then the per-row +
    // for a DIFFERENT employee): the dialog is plain DOM, so leftover extra
    // rows or typed values from the last attempt would otherwise still be
    // there — and now attributed to whichever employee this open is for. Every
    // open goes through here so it always starts from exactly one blank row.
    window.dtOpenDialog = function (employeeId, kind) {
      Array.prototype.slice.call(rows.querySelectorAll('.dt-row'), 1).forEach(function (r) { r.remove(); });
      rows.querySelector('.dt-row').querySelectorAll('[name]').forEach(function (el) {
        if (el.tagName === 'SELECT') { el.selectedIndex = 0; } else { el.value = ''; }
      });
      n = 1;
      var idField = document.getElementById('dt-dialog').querySelector('[name=id]');
      if (idField) { idField.value = employeeId === undefined ? '' : employeeId; }
      if (kind) { rows.querySelector('[name="docs[0][kind]"]').value = kind; }
      document.getElementById('dt-dialog').showModal();
    };
  })();
  </script>
<?php endif; ?>
  <div class="card">
    <?= orgFilterBar('document-tracker', $dtFilter, $dtOptions, array_filter(['missing' => $dtShowMissing ? '1' : ''])) ?>
    <?php // ONE FILTER BAR (owner, 13 Oct): the Employee filter above is the search; the second box is gone. ?>
