<?php // ONE EMPLOYEE IN THE SELECTION = THEIR DOCUMENTS (owner, 13 Oct): picking an employee in the
      // filter (or narrowing to one person any other way) opens the gallery, not a one-row table.
      if ($dtOpen === '' && count($dtVisible) === 1) { $dtOpen = (string) (array_values($dtVisible)[0]['id'] ?? ''); }
      $dtOpenE = $dtOpen === '' ? null : ($dtById[$dtOpen] ?? null); ?>
<?php if ($dtOpenE !== null):
    // ONE EMPLOYEE'S FILES AS A GALLERY (owner, 13 Oct): reached from the Directory's
    // "View documents" link. Each file is a thumbnail with its title and Edit, Replace, Remove.
    $dtG = $dtGroups[$dtOpen] ?? [];
    usort($dtG, static fn (array $a, array $b): int => [(string) ($a['expiry'] ?? '') === '' ? 1 : 0, (string) ($a['expiry'] ?? ''), (string) $a['kind']] <=> [(string) ($b['expiry'] ?? '') === '' ? 1 : 0, (string) ($b['expiry'] ?? ''), (string) $b['kind']]);
    $dtThumb = static function (string $path): string {
        $ext = strtolower(pathinfo($path, PATHINFO_EXTENSION));
        if ($path === '') { return '<div class="dg-ph"><i class="fas fa-file-circle-question"></i><span>no file</span></div>'; }
        if (in_array($ext, ['jpg', 'jpeg', 'png', 'webp', 'gif'], true)) { return '<img src="' . e($path) . '" alt="" loading="lazy">'; }
        if ($ext === 'pdf') { return '<iframe src="' . e($path) . '#toolbar=0&amp;navpanes=0&amp;scrollbar=0&amp;view=FitH" loading="lazy" tabindex="-1" title=""></iframe>'; }
        return '<div class="dg-ph"><i class="fas fa-file-word"></i><span>.' . e($ext) . '</span></div>';
    };
?>
