  <style>
    .prob-dlg{border:0;border-radius:14px;padding:20px 22px;width:min(640px,94vw);box-shadow:0 20px 60px rgba(0,0,0,.25);background:var(--surface,#fff);color:var(--text,#0f172a)}
    .prob-dlg::backdrop{background:rgba(15,23,42,.45)}
    .prob-dlg-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}
    .prob-facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:6px 16px;margin:0;padding:10px 12px;border-radius:10px;background:var(--surface-2,#f6f7f9)}
    .prob-facts div{min-width:0}.prob-facts dt{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--text3,#64748b)}
    .prob-facts dd{margin:0;font-weight:600;overflow-wrap:anywhere}
    .prob-stat{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px 12px}
    .prob-stat select{width:100%}
    .prob-stat select.prob-auto{background:var(--surface-2,#f1f5f9)!important;color:var(--text1,#0f172a);border-color:var(--border,#e2e8f0)!important;appearance:none;-webkit-appearance:none;background-image:none!important}
  </style>
  <script>
  (function () {
    var dlg = document.getElementById('prob-dlg');
    if (!dlg) { return; }
    var $ = function (id) { return document.getElementById(id); };
    var fact = function (k, v) { return '<div><dt>' + k + '</dt><dd>' + (v === '' || v === null ? '—' : String(v).replace(/[&<>"]/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; })) + '</dd></div>'; };
    document.querySelectorAll('[data-prob-open]').forEach(function (b) {
      b.addEventListener('click', function () {
        var d = JSON.parse(b.getAttribute('data-prob'));
        var extend = b.getAttribute('data-prob-open') === 'extend';
        $('prob-form').reset();
        $('prob-id').value = d.id;
        $('prob-action').value = extend ? 'probation-extend' : 'probation-confirm';
        $('prob-dlg-title').textContent = (extend ? 'Extend probation — ' : 'Confirm probation — ') + d.code + ' · ' + d.name;
        $('prob-submit').textContent = extend ? 'Extend' : 'Confirm';
        var days = d.days === null ? '' : (d.days < 0 ? Math.abs(d.days) + ' day(s) overdue' : (d.days === 0 ? 'last day today' : d.days + ' day(s) left'));
        $('prob-facts').innerHTML = fact('Employee', d.code + ' · ' + d.name) + fact('Company', d.company) + fact('Branch', d.branch)
          + fact('Role', d.role) + fact('Designation', d.designation) + fact('Reporting Manager', d.manager) + fact('Joined', d.joined) + fact('Probation ends', d.end) + fact('Status', days)
          + fact('Extensions so far', d.extensions);
        $('prob-confirm-fields').hidden = extend;
        $('prob-extend-fields').hidden = !extend;
        $('prob-on').required = !extend; $('prob-on').disabled = extend;
        $('prob-new-end').required = extend; $('prob-new-end').disabled = !extend;
        dlg.querySelectorAll('[data-prob-head]').forEach(function (sel) {
          sel.required = !extend; sel.disabled = extend;
          sel.value = (d.statutory && d.statutory[sel.getAttribute('data-prob-head')]) || '';
          // FROM THE CURRENT CTC (owner, 26 Oct): a worked-out answer is shown, not chosen
          var auto = !extend && sel.value !== '';
          sel.style.pointerEvents = auto ? 'none' : ''; sel.tabIndex = auto ? -1 : 0; sel.classList.toggle('prob-auto', auto);
        });
        if (extend) {
          $('prob-new-end').min = d.min_end || '';
          $('prob-new-end').value = '';
          $('prob-new-end-note').textContent = d.end ? 'Must be after the current end, ' + d.end + '.' : '';
        } else {
          var today = new Date().toISOString().slice(0, 10);
          $('prob-on').value = d.end && d.end <= today ? d.end : today;
        }
        dlg.showModal();
        (extend ? $('prob-new-end') : $('prob-on')).focus();
      });
    });
    dlg.querySelectorAll('[data-prob-close]').forEach(function (b) { b.addEventListener('click', function () { dlg.close(); }); });
  })();
  </script>
<?php endif; ?>

