<?php elseif ($route === 'attendance-corrections' && !$may('attendance.day.view')): ?>
  <div class="page-header"><div><h2>Attendance Regularization</h2></div></div>
  <div class="card"><div class="problem" style="margin:0">Denied: <?= e($access->decide(
      (string) $session->user()['role'], 'attendance.day.view')->summary) ?></div></div>

<?php elseif ($route === 'attendance-corrections'): ?>
<?php
    // THE QUEUE: every regularisation request in the viewer's scope, pending
    // first, decided in place. The per-person screen keeps its own list; this is
    // the approver's view across people — SmartPRS 2's attendance-corrections.
    //
    // VISIBLE TO: yourself; anybody who reports to you (the same rule every
    // other screen scopes by); anybody whose Team Lead you are; and, for an
    // administrator-tier role, everybody — because Scope already reaches the
    // whole tenant for that role. Never the whole company for anyone else.
    $corrState = (string) ($_GET['state'] ?? Regularisation::PENDING);
    $corrState = in_array($corrState, [Regularisation::PENDING, Regularisation::APPROVED, Regularisation::REJECTED, 'all'], true) ? $corrState : Regularisation::PENDING;
    // WHO MAY BE DECIDED / ASKED FOR BY THIS PERSON: the reporting hierarchy
    // below them (all levels) plus, for Admin/HR, their scope — and their own
    // only when their role self-approves (regularisationDecidable()).
    $corrDecidable = regularisationDecidable($store, $regularisation, $scope, $may, (string) ($session->user()['role'] ?? ''));
    $corrMayDecide = $corrDecidable !== [];
    $corrScoped = [];
    $corrNames = [];
    $corrPeople = [];

    foreach ($regularisation->visibleTo($scope, $may('attendance.day.view.history')) as $ce) {
        $corrScoped[Employment::code($ce)] = (string) $ce['id'];
        $corrNames[Employment::code($ce)] = trim((string) ($ce['name'] ?? ''));
        $corrPeople[] = $ce;
    }

    // COMPANY / BRANCH / … / EMPLOYEE + PERIOD (owner, 16 Oct): the same bar every
    // other register uses. Narrows the LIST only — $corrScoped stays whole so the
    // raise form and the decide buttons are unaffected by what is being viewed.
    $corrFilter = orgFilter();
    $corrOptions = orgFilterOptions($store, $corrPeople);
    $corrPeriod = isset($_GET['p']) ? reportPeriod($_GET, financialYearStart($customisation), date('Y-m-d')) : null;
    $corrShown = [];

    foreach (orgFilterApply($store, $corrPeople, $corrFilter) as $ce) {
        $corrShown[Employment::code($ce)] = true;
    }

    // GROUPED BY EMPLOYEE + DAY: the new form raises check-in and check-out
    // together, but the schema is still one row per direction (SmartPRS 2's
    // shape) — grouped back here so the approver sees and decides ONE card,
    // not two independent ones that could end up half-approved. A night
    // shift's check-out lands on the next calendar day, so it is its own
    // group in that case — the one case this does not fold back together.
    $corrGroupOf = static function (array $rows): array {
        $groups = [];

        foreach ($rows as $cr) {
            $key = (string) $cr['employment_id'] . '|' . (string) $cr['date'];
            $groups[$key] ??= ['employment_id' => (string) $cr['employment_id'], 'date' => (string) $cr['date'],
                'in' => null, 'out' => null, 'reason' => (string) ($cr['reason'] ?? ''),
                'requested_at' => (string) ($cr['requested_at'] ?? ''), 'state' => (string) $cr['state'],
                'ids' => [], 'decided_by' => $cr['decided_by'] ?? null, 'decided_at' => $cr['decided_at'] ?? null,
                'note' => $cr['note'] ?? null];
            $groups[$key]['ids'][] = (string) $cr['id'];
            $groups[$key][(string) $cr['direction']] = substr((string) $cr['at'], 11, 5);
            $groups[$key]['requested_at'] = min($groups[$key]['requested_at'], (string) ($cr['requested_at'] ?? ''));

            if ($groups[$key]['state'] !== (string) $cr['state']) {
                $groups[$key]['state'] = 'mixed'; // legacy rows decided independently before this screen grouped them
            }
        }

        return array_values($groups);
    };

    $corrAllScopedRows = array_values(array_filter($regularisation->all(),
        static fn (array $r): bool => isset($corrShown[(string) $r['employment_id']])
            && ($corrPeriod === null || ((string) $r['date'] >= $corrPeriod['from'] && (string) $r['date'] <= $corrPeriod['to']))));
    $corrCounts = ['pending' => 0, 'approved' => 0, 'rejected' => 0];

    foreach ($corrGroupOf($corrAllScopedRows) as $g) {
        isset($corrCounts[$g['state']]) && $corrCounts[$g['state']]++;
    }

    $corrGroups = $corrGroupOf($corrState === 'all' ? $corrAllScopedRows
        : array_values(array_filter($corrAllScopedRows, static fn (array $r): bool => (string) $r['state'] === $corrState)));
    usort($corrGroups, static fn (array $a, array $b): int => strcmp($b['requested_at'], $a['requested_at']));
?>
  <div class="page-header">
    <div><h2>Attendance Regularization</h2><p>Check-in/check-out corrections across your reporting hierarchy &mdash; a missing punch is ADDED on approval, the device's punch is never edited</p></div>
    <a class="btn btn-outline" href="?r=attendance"><i class="fas fa-fingerprint"></i> Attendance</a>
  </div>
<?php
    $crOwnId = $scope->own();
    $crOwnRow = $crOwnId === null ? null : $store->find('employees', $crOwnId);
    $crSelectedRow = $crOwnRow;

    if ($corrMayDecide && $crOwnRow === null && $corrDecidable !== []) {
        $crFirstCode = array_key_first($corrDecidable);
        $crSelectedRow = $store->find('employees', (string) ($corrScoped[$crFirstCode] ?? ''));
    }

    // ARRIVING FROM A ROW: ?emp=<code>&date=<Y-m-d>, which the Edit button on
    // Attendance Logs uses. Somebody who has just read that a day is wrong
    // should not then retype who and when — that is the step where the wrong
    // date gets raised against the right person.
    //
    // THE CODE IS NOT TRUSTED FROM THE URL. It is only honoured when it is in
    // $corrDecidable — the same list the picker itself offers — so a code typed
    // into the address bar selects nobody the viewer could not already choose.
    $crFromCode = trim((string) ($_GET['emp'] ?? ''));
    $crFromDate = trim((string) ($_GET['date'] ?? ''));
    $crFromDate = preg_match('/^\d{4}-\d{2}-\d{2}$/', $crFromDate) === 1 ? $crFromDate : '';

    if ($crFromCode !== '' && isset($corrDecidable[$crFromCode], $corrScoped[$crFromCode])) {
        $crSelectedRow = $store->find('employees', (string) $corrScoped[$crFromCode]) ?? $crSelectedRow;
    }

    $corrShifts = new Shifts($store);
    // THE SHIFT OF THE DAY BEING FIXED, not of today: somebody regularising a
    // day three weeks back needs the window that applied THEN, and it is the
    // window the prefilled times below are built from.
    $crShiftOn = $crFromDate !== '' ? $crFromDate : date('Y-m-d');
    $crShift = $crSelectedRow === null ? null : $corrShifts->for($crSelectedRow, $crShiftOn);
    // PREFILLED, NOT SUBMITTED. The times are the shift's own start and end so
    // the common correction ("I was here, the device missed me") is two clicks;
    // anything else is typed over. Nothing is raised until Request is pressed.
    $crInAt = $crFromDate === '' ? '' : $crFromDate . 'T' . substr((string) ($crShift['start_time'] ?? $calendar->shiftStart()), 0, 5);
    $crOutAt = $crFromDate === '' ? '' : $crFromDate . 'T' . substr((string) ($crShift['end_time'] ?? $calendar->shiftEnd()), 0, 5);
?>
  <details class="card" id="raise-correction" style="border-top:3px solid #1e3a5f"<?= (string) ($_GET['raise'] ?? '') === '1' ? ' open' : '' ?>>
    <summary style="cursor:pointer;font-weight:700;color:#1e3a5f"><i class="fas fa-plus"></i> Request a regularization</summary>
<?php if ($crOwnRow === null): ?>
    <?= linkSelfCard('attendance-corrections', (string) ($session->user()['id'] ?? ''), $session->token(), employeeChoices(liveRows($store, 'employees')),
        $may('access.user.update'), $may('employee.create'),
        'So it has no attendance of its own to regularize' . ($corrMayDecide ? ' &mdash; you can still raise one for someone in your hierarchy below' : '') . '.', leaveSelfApproves((string) ($session->user()['role'] ?? '')), (string) ($session->user()['role'] ?? '')) ?>
<?php endif; ?>
<?php if ($crOwnRow === null && !$corrMayDecide): ?>
<?php else: ?>
    <form method="post" class="row" style="align-items:flex-end;margin-top:10px">
      <input type="hidden" name="csrf" value="<?= e($session->token()) ?>"><input type="hidden" name="action" value="correction-raise">
<?php if ($corrMayDecide): ?>
      <div><label for="corr-emp">Emp. ID &amp; Name</label>
<?php $corrChoices = []; if ($crOwnRow !== null) { $corrChoices[Employment::code($crOwnRow)] = Employment::label($crOwnRow) . ' (me)'; } foreach ($corrNames as $crC => $crN) { isset($corrDecidable[$crC]) && $corrChoices[$crC] = $crC . ' · ' . $crN; } ?>
        <?= employeePicker('corr-emp', 'employment_code', $corrChoices,
            $crSelectedRow !== null ? Employment::code($crSelectedRow) : '', '— type to search —', false, 'onchange="this.form.submit()"') ?></div>
<?php else: ?>
