        <td class="note"><?= $g['decided_by'] ? e((string) $g['decided_by'] . ' · ' . substr((string) $g['decided_at'], 0, 16) . ($g['note'] ? ' · ' . $g['note'] : '')) : '&mdash;' ?></td>
