  <div class="card"><div class="problem" style="margin:0">Denied: <?= e($access->decide(
      (string) $session->user()['role'], 'tenant.settings.view')->summary) ?></div></div>

<?php elseif ($route === 'configure-id-card'): ?>
<?php
    $icDeclared = $idCardFormat->declared();
    $icFormat = $idCardFormat->format();
    $icMayEdit = $may('tenant.settings.update');
    // NAMED, SCOPED FORMATS (10 Sep): editing one loads its format into the same form.
    $icEntries = $idCardFormat->entries();
    $icEntry = null;
    foreach ($icEntries as $icE) { if ($icE['id'] === (string) ($_GET['entry'] ?? '')) { $icEntry = $icE; } }
    $icEntry !== null && $icFormat = $icEntry['format'];
    $icNames = orgNames($store);
    // ROLE HAS NO ID OF ITS OWN — Role/Designation Setup's Role column is free
    // text on each designation, not a separate register — so its "options"
    // list is keyed by the text itself, exactly like the Payslip Format
    // Designer's Role scope reads the same source.
    $icRoleList = array_values(array_unique(array_filter($icNames['designation_roles'] ?? [])));
    sort($icRoleList);
    $icScopeOptions = ['company' => $icNames['companies'] ?? [], 'branch' => $icNames['branches'] ?? [], 'department' => $icNames['departments'] ?? [],
        'role' => array_combine($icRoleList, $icRoleList), 'designation' => $icNames['designations'] ?? []];
    // designation NAME => its Role, so the Designation dropdown can narrow to
    // whichever Role is picked (same link every other Role/Designation screen
    // this session already reads through).
    $icDesigRoleOf = [];
    foreach ($icNames['designations'] ?? [] as $icDId => $icDName) { $icDesigRoleOf[$icDId] = $icNames['designation_roles'][$icDId] ?? ''; }
    // ONLY REAL EMPLOYEES (11 Sep) — Visitor/Client/Guest template cards were
    // removed at the owner's request, so this picker (and every screen that
    // shares $idCardExternalTypes, which is now always empty) offers nothing
    // but people who actually have a row in `employees`.
    $icEmployeeOptions = [];
    foreach ($idCardExternalTypes as $icTId => $icTLabel) { $icEmployeeOptions[$icTId] = $icTLabel . ' (template only — no employee record)'; }
    foreach ($scope->only(liveRows($store, 'employees'), true) as $icE) { $icEmployeeOptions[(string) $icE['id']] = Employment::label($icE); }
    $icScopeLabel = static function (array $entry) use ($icScopeOptions, $icEmployeeOptions): string {
        $parts = [];
        foreach (['company' => 'Company', 'branch' => 'Branch', 'department' => 'Department', 'role' => 'Role', 'designation' => 'Designation'] as $k => $l) { $entry['scope'][$k] !== '' && $parts[] = $l . ': ' . ($icScopeOptions[$k][$entry['scope'][$k]] ?? '#' . $entry['scope'][$k]); }
        $entry['scope']['employee'] !== '' && $parts[] = 'Employee: ' . ($icEmployeeOptions[$entry['scope']['employee']] ?? '#' . $entry['scope']['employee']);
        return implode(' · ', $parts);
    };
    // A REAL EMPLOYMENT FOR THE PREVIEW when there is one in scope, else a sample
    // that is plainly a sample — never a customer's name typed into a file.
    $icSampleRows = $scope->only($store->all('employees'), true);
    $icSample = $icSampleRows[0] ?? ['emp_code' => 'EMP-0001', 'name' => 'Sample Employee', 'designation' => 'Designation',
        'department' => 'Department', 'branch' => 'Branch', 'doj' => date('Y-m-d'), 'dob' => '1990-01-01', 'blood_group' => 'O+',
        'mobile' => '9000000000', 'email' => 'sample@example.com', 'address' => 'Address line', 'emergency_phone' => '9000000001',
        'device_user_id' => '1', 'pan' => 'AAAAA0000A', 'uan' => '100000000000', 'esic_no' => '0000000000'];

    // Editing a format scoped to a template sentinel: preview that template,
    // not whichever real employee happened to sort first — a name on a
    // visitor/client/guest badge preview is exactly the mix-up this sentinel
    // exists to avoid. Also drives the PHP-rendered card below: a template has
    // no photo, so the photo box prints its type's label instead (see
    // idCardFor()/idCardHtml()).
    $icTemplateLabel = $icEmployeeOptions[$icEntry['scope']['employee'] ?? ''] ?? null;
    $icIsVisitor = $icTemplateLabel !== null && IdCardFormat::isTemplateId((string) ($icEntry['scope']['employee'] ?? ''));

    if ($icIsVisitor) {
        $icTypeLabel = $idCardExternalTypes[(string) $icEntry['scope']['employee']] ?? 'Visitor';
        $icSample = IdCardFormat::templateRowFor((string) $icEntry['scope']['employee'], $icTypeLabel);
        $icSample['branch'] = (string) ($icSample['branch'] ?? '');
        $icSample['employer_company_id'] = (string) ($icSampleRows[0]['employer_company_id'] ?? '');
    }

    $icCompanyRow = null;

    try {
        $icCompanyRow = $store->find('companies', (string) ($icSample['employer_company_id'] ?? '')) ?? (liveRows($store, 'companies')[0] ?? null);
    } catch (\Throwable) {
        // gate:allow-swallow no companies table on the file store: the tenant's name is used
    }

    $icCard = idCardFor($idCardFormat, $icFormat, orgEnrich($store, $icSample), $icCompanyRow, $company, __DIR__, $icIsVisitor ? (string) $icSample['designation'] : '');
    $icOrder = array_values(array_unique(array_merge($icFormat['fields'], array_keys($icDeclared['fields']))));
    $icHistory = $customisation->history((string) $icDeclared['customisation_key']);
    // VISIT PURPOSES LIVE HERE, NOT AS ITS OWN SCREEN (11 Sep) -- the owner
    // asked for it folded into the format page itself, since it means
    // nothing outside the context of an ID card. Still the same NamedList-
    // backed config as before; only the screen it renders on changed.
    // (Card Types, the sibling list for Visitor/Client/Guest templates, was
    // removed outright the same day — only real employee ID cards remain.)
    $icNlSection = static function (string $title, string $hint, NamedList $list, string $saveAction, string $placeholder, bool $mayEdit, Session $session): string {
        $rows = $list->all();
        $html = '<div class="card"><h2>' . e($title) . ' <span class="note">' . e($hint) . '</span></h2>';
        $html .= $mayEdit ? '' : '<p class="note">Changing this list needs <code>tenant.settings.update</code>.</p>';
        $html .= '<form method="post"><input type="hidden" name="csrf" value="' . e($session->token()) . '"><input type="hidden" name="action" value="' . e($saveAction) . '">';
        $html .= '<div class="table-wrap"><table><thead><tr><th>Label</th><th></th></tr></thead><tbody>';

        foreach (array_merge($rows, [[], [], []]) as $i => $r) {
            $id = e((string) ($r['id'] ?? ''));
            $label = e((string) ($r['label'] ?? ''));
            $html .= '<tr><td><input type="hidden" name="items[' . $i . '][id]" value="' . $id . '">'
                . '<input class="nl-label" name="items[' . $i . '][label]" value="' . $label . '" placeholder="' . e($placeholder) . '" ' . ($mayEdit ? '' : 'readonly') . '></td>'
                . '<td class="n">' . ($mayEdit ? "<button type=\"button\" class=\"btn btn-outline btn-sm\" onclick=\"this.closest('tr').querySelector('.nl-label').value=''\">Clear</button>" : '') . '</td></tr>';
        }

        $html .= '</tbody></table></div>';
        $html .= $mayEdit ? '<p style="margin-top:10px"><button class="btn btn-primary">Save ' . e(strtolower($title)) . '</button>'
            . ' <span class="note">Blank rows are ignored; clear a label to remove that option. A saved format or a past entry already using one keeps its own recorded label even if renamed here.</span></p>' : '';

        return $html . '</form></div>';
    };
?>
