          <div><label for="ic-scope-<?= $icK ?>"><?= $icL ?></label><select id="ic-scope-<?= $icK ?>" name="scope[<?= $icK ?>]" <?= $icK === 'role' ? 'data-cascade="role"' : ($icK === 'designation' ? 'data-cascade="designation"' : '') ?>><option value="">ALL</option><?php foreach ($icScopeOptions[$icK] as $icId => $icN): ?><option value="<?= e((string) $icId) ?>" <?= $icK === 'designation' && isset($icDesigRoleOf[(string) $icId]) ? 'data-role="' . e($icDesigRoleOf[(string) $icId]) . '"' : '' ?><?= (string) ($icEntry['scope'][$icK] ?? '') === (string) $icId ? ' selected' : '' ?>><?= e((string) $icN) ?></option><?php endforeach; ?></select></div>
<?php endforeach; ?>
          <div><label for="ic-scope-employee">Employee</label><?= employeePicker('ic-scope-employee', 'scope[employee]', $icEmployeeOptions, (string) ($icEntry['scope']['employee'] ?? '')) ?></div>
        </div>
      </fieldset>
      <script>(function(){
        var fs = document.currentScript.previousElementSibling;
        var roleSel = fs.querySelector('select[data-cascade=role]');
        var desigSel = fs.querySelector('select[data-cascade=designation]');
        if (!roleSel || !desigSel) { return; }
        function apply(){
          var role = roleSel.value, kept = desigSel.value, keepable = false;
          Array.prototype.forEach.call(desigSel.options, function(o){
            var show = o.value === '' || role === '' || o.getAttribute('data-role') === role;
            o.hidden = !show;
            if (show && o.value === kept) { keepable = true; }
          });
          if (!keepable) { desigSel.value = ''; }
        }
        roleSel.addEventListener('change', apply);
        apply();
      })();</script>
