      <h3>Start from a template <span class="note">optional &mdash; fills in the colours, header style and photo shape/border below; every field stays editable after, including the colours</span></h3>
      <div class="row" style="align-items:flex-end;margin-bottom:6px">
        <div style="flex:1;min-width:220px"><label for="ic-template">Template</label>
          <select id="ic-template">
            <option value="">— pick a template to fill in the look below —</option>
<?php foreach ($icDeclared['templates'] ?? [] as $icTpl): ?>
            <option value="<?= e((string) $icTpl['id']) ?>" data-json="<?= e((string) json_encode($icTpl)) ?>"><?= e((string) $icTpl['name']) ?></option>
<?php endforeach; ?>
          </select></div>
      </div>
      <script>(function(){
        var sel = document.getElementById('ic-template'), form = document.getElementById('ic-form');
        if (!sel || !form) { return; }
        sel.addEventListener('change', function () {
          if (!sel.value) { return; }
          var t = JSON.parse(sel.selectedOptions[0].getAttribute('data-json'));
          function set(name, value) {
            var el = form.querySelector('[name="' + name + '"]');
            if (!el) { return; }
            el.value = value;
            el.dispatchEvent(new Event('input'));
            el.dispatchEvent(new Event('change'));
          }
          set('header_style', t.header_style);
          set('photo_shape', t.photo_shape);
          set('photo_border', t.photo_border);
          Object.keys(t.colors || {}).forEach(function (k) { set('colors[' + k + ']', t.colors[k]); });
          sel.value = '';
        });
      })();</script>
