        <div style="flex:1"><label>Card title (e.g. STAFF, VISITOR)</label><input name="title" class="ic-live" value="<?= e((string) $icFormat['title']) ?>" maxlength="30"></div>
        <div style="flex:2"><label>Footer &mdash; <code>{company}</code> is replaced</label><input name="footer" class="ic-live" value="<?= e((string) $icFormat['footer']) ?>" maxlength="120"></div>
        <div><label>Valid till <span class="note">(printed when the field below is ticked)</span></label>
          <div class="row" style="gap:6px;align-items:center">
            <select name="valid_till_mode" id="ic-vt-mode" class="ic-live" style="width:auto">
              <option value="text"<?= ($icFormat['valid_till_mode'] ?? 'text') === 'text' ? ' selected' : '' ?>>Fixed text</option>
              <option value="days"<?= ($icFormat['valid_till_mode'] ?? 'text') === 'days' ? ' selected' : '' ?>>Auto: N days from print date</option>
            </select>
            <input name="valid_till" id="ic-vt-text" class="ic-live" value="<?= e((string) $icFormat['valid_till']) ?>" placeholder="e.g. 31-03-2027" pattern="(0[1-9]|[12][0-9]|3[01])-(0[1-9]|1[0-2])-[0-9]{4}" title="A date as dd-mm-yyyy, e.g. 31-03-2027" maxlength="10" style="width:120px">
            <input name="valid_till_days" id="ic-vt-days" class="ic-live" type="number" min="1" max="3650" value="<?= e((string) ($icFormat['valid_till_days'] ?? 365)) ?>" style="width:70px" title="days from the date the card is printed">
          </div></div>
      </div>
      <script>(function(){
        var mode = document.getElementById('ic-vt-mode'), text = document.getElementById('ic-vt-text'), days = document.getElementById('ic-vt-days');
        function apply(){ text.style.display = mode.value === 'days' ? 'none' : ''; days.style.display = mode.value === 'days' ? '' : 'none'; }
        mode.addEventListener('change', apply); apply();
      })();</script>
      <h3 style="margin-top:14px">Fields <span class="note">tick to print; choose Front or Back for each; order with the arrows</span></h3>
      <table id="ic-fields" style="width:100%;font-size:.95em">
        <tbody>
<?php foreach ($icOrder as $code): $fd = $icDeclared['fields'][$code];
        // A VISITOR HAS NO EMPLOYEE ID — lock the Emp ID row off, same as the JS
        // below does the moment the Employee scope is changed to Visitor on-screen.
        $icLocked = $icIsVisitor && $code === 'emp_code';
        $on = !$icLocked && in_array($code, $icFormat['fields'], true); ?>
        <tr data-code="<?= e($code) ?>"<?= $icLocked ? ' style="opacity:.5"' : '' ?>>
          <td style="width:30px"><input type="checkbox" name="fields[<?= e($code) ?>]" value="1" class="ic-live"<?= $on ? ' checked' : '' ?><?= $icLocked ? ' disabled title="A visitor has no employee ID"' : '' ?>></td>
          <td><?= e((string) $fd['label']) ?> <span class="note"><?= isset($fd['column']) ? 'employees.' . e((string) $fd['column']) : e((string) ($fd['kind'] ?? '')) ?></span></td>
<?php $icBack = in_array($code, (array) ($icFormat['back_fields'] ?? []), true); ?>
          <td style="white-space:nowrap;width:150px"><label style="display:inline-flex;gap:4px;align-items:center;font-weight:400;margin:0 10px 0 0"><input type="radio" class="ic-live" name="side[<?= e($code) ?>]" value="front"<?= $icBack ? '' : ' checked' ?>> Front</label><label style="display:inline-flex;gap:4px;align-items:center;font-weight:400;margin:0"><input type="radio" class="ic-live" name="side[<?= e($code) ?>]" value="back"<?= $icBack ? ' checked' : '' ?>> Back</label></td>
          <td class="n" style="width:90px;white-space:nowrap"><button type="button" class="btn btn-outline ic-up" title="up" style="padding:2px 8px">&uarr;</button> <button type="button" class="btn btn-outline ic-down" title="down" style="padding:2px 8px">&darr;</button></td>
        </tr>
<?php endforeach; ?>
        </tbody>
      </table>
      <h3 style="margin-top:14px">Colours</h3>
      <div class="row" style="flex-wrap:wrap;gap:8px 18px">
<?php foreach (['header' => 'Header band', 'header_text' => 'Header text', 'accent' => 'Accent stripe', 'background' => 'Background', 'text' => 'Text', 'label' => 'Labels'] as $ck => $cl): ?>
        <label class="note"><?= $cl ?><br><input type="color" name="colors[<?= $ck ?>]" class="ic-live" value="<?= e((string) $icFormat['colors'][$ck]) ?>"></label>
<?php endforeach; ?>
      </div>
      <h3 style="margin-top:14px">Back of card <span class="note">optional &mdash; leave blank for no back side</span></h3>
      <div class="row" style="align-items:flex-end;margin-bottom:6px">
        <div style="flex:1;min-width:220px"><label for="ic-back-sample">Start from a draft</label>
          <select id="ic-back-sample" onchange="if(this.value){document.getElementById('ic-back-text').value=this.value;document.getElementById('ic-back-text').dispatchEvent(new Event('input'));this.value='';}">
            <option value="">— pick a draft to fill the box below —</option>
<?php foreach (IdCardFormat::backSideSamples() as $bsLabel => $bsText): ?>
            <option value="<?= e($bsText) ?>"><?= e($bsLabel) ?></option>
<?php endforeach; ?>
          </select></div>
      </div>
      <textarea id="ic-back-text" name="back_text" class="ic-live" rows="4" maxlength="600" placeholder="e.g. terms of use, return-if-found, emergency contact&hellip;" style="width:100%"><?= e((string) ($icFormat['back_text'] ?? '')) ?></textarea>
<?php if ($icMayEdit): ?>
      <div style="margin-top:14px"><button class="go" type="submit"><?= $icEntry === null ? 'Save format' : 'Save "' . e($icEntry['name']) . '"' ?></button>
        <span class="note">Saved as a new version; the ID Cards screen and the PDF use it at once.</span></div>
<?php endif; ?>
    </form>
  </div>
  <div class="card" style="flex:0 0 auto;max-width:420px">
    <h2>Preview <span class="note">live</span></h2>
    <div id="ic-preview-wrap"><?= idCardHtml($icCard, 'ic-preview') ?></div>
    <p class="note" id="ic-dims" style="margin-top:8px"><?= (int) ($icCard['w_mm'] / 10) ?> × <?= (int) ($icCard['h_mm'] / 10) ?> mm</p>
    <p class="note">Previewed on <?= e(Employment::label($icSample)) ?>. The PDF uses the same layout; a JPEG logo and photo are embedded there.</p>
  </div>
  </div>
  <div class="card"><h2>Saved formats <span class="note"><?= count($icEntries) ?> named format(s) · the default applies to everyone else</span></h2>
<?php if ($icEntries === []): ?><p class="note">None yet. Give the format above a name, pick who it is for, and save.</p><?php else: ?>
    <div class="table-wrap"><table><thead><tr><th>Name</th><th>Applies to</th><th>Size</th><th>Fields</th><th></th></tr></thead><tbody>
<?php foreach ($icEntries as $icE): ?>
      <tr><td><b><?= e($icE['name']) ?></b></td><td><?= e($icScopeLabel($icE)) ?></td><td class="note"><?= e((string) $icE['format']['size']) ?> <?= e((string) $icE['format']['orientation']) ?></td><td class="note"><?= e(implode(', ', array_map(static fn (string $f): string => (string) ($icDeclared['fields'][$f]['label'] ?? $f), $icE['format']['fields']))) ?></td>
        <td style="white-space:nowrap"><?php if ($icMayEdit): ?><a class="btn btn-outline btn-sm" href="?r=configure-id-card&amp;entry=<?= e($icE['id']) ?>" title="Edit"><i class="fas fa-pen"></i></a>
          <form method="post" style="display:inline" onsubmit="return confirm(this.dataset.ask)" data-ask="Delete the format &quot;<?= e($icE['name']) ?>&quot;? The people it covered fall back to the default."><input type="hidden" name="csrf" value="<?= e($session->token()) ?>"><input type="hidden" name="action" value="id-card-format-delete"><input type="hidden" name="entry_id" value="<?= e($icE['id']) ?>"><button class="btn btn-outline btn-sm" type="submit" title="Delete" style="color:#dc2626"><i class="fas fa-trash"></i></button></form><?php endif; ?></td></tr>
<?php endforeach; ?>
    </tbody></table></div>
<?php endif; ?>
  </div>
<?php // Visit Purposes section removed (owner, 22 Oct 2026). ?>
<?php if ($icHistory !== []): ?>
  <div class="card"><h2>History <span class="note">of the default format</span></h2>
    <div class="table-wrap"><table><thead><tr><th class="n">Version</th><th>By</th><th>When</th><th>Fields</th></tr></thead><tbody>
<?php foreach ($icHistory as $h): $pl = json_decode((string) ($h['payload'] ?? ''), true); ?>
      <tr><td class="n"><?= (int) $h['version'] ?></td><td class="note"><?= e((string) ($h['changed_by'] ?? '')) ?></td><td class="note"><?= e((string) ($h['created_at'] ?? '')) ?></td>
        <td class="note"><?= e(implode(', ', (array) ($pl['fields'] ?? []))) ?> &middot; <?= e((string) ($pl['size'] ?? '')) ?> <?= e((string) ($pl['orientation'] ?? '')) ?></td></tr>
<?php endforeach; ?>
    </tbody></table></div></div>
<?php endif; ?>
<script>
// THE PREVIEW FOLLOWS THE FORM. It redraws the card from the inputs alone, with
// the same proportions the server draws, so what is saved is what was seen.
(function () {
  var form = document.getElementById('ic-form'); if (!form) { return; }
  var sample = <?= json_encode(array_map(static fn (array $l): array => ['code' => $l['code'], 'label' => $l['label'], 'value' => $l['value'], 'kind' => $l['kind']],
      $idCardFormat->lines(array_merge($icFormat, ['fields' => array_keys($icDeclared['fields'])]), $icSample)), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var labels = <?= json_encode(array_map(static fn (array $f): string => (string) $f['label'], $icDeclared['fields']), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var company = <?= json_encode($icCard['company'], JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var tagline = <?= json_encode(trim((string) ($icCompanyRow['address'] ?? $icCompanyRow['website'] ?? '')), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var logo = <?= json_encode(trim((string) ($icCompanyRow['logo_path'] ?? '')), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var photo = <?= json_encode(trim((string) ($icSample['photo_path'] ?? '')), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var templateLabels = <?= json_encode($idCardExternalTypes, JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  // THE BARS THEMSELVES ARE NOT RE-ENCODED IN JS (11 Sep) -- their data is
  // always the previewed sample's own Emp. ID, which nothing in this form
  // changes, so they are rendered once, server-side, by the real Barcode
  // class -- one Code 128 encoder in the codebase, not two that could
  // quietly drift apart. The caption under them still uses the live Labels
  // colour, same as every other field caption in this preview.
  var barcodeBars = <?= json_encode(barcodeBarsHtml(Barcode::code128(Employment::codeOrSay($icSample)), 20), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); };
  var byCode = {}; sample.forEach(function (l) { byCode[l.code] = l; });
  function val(n) { var el = form.querySelector('[name="' + n + '"]'); return el ? (el.type === 'checkbox' ? el.checked : el.value) : ''; }
  function order() { return Array.prototype.map.call(document.querySelectorAll('#ic-fields tr'), function (tr) { return tr.getAttribute('data-code'); }); }
  // A TEMPLATE (Visitor, or any type the owner has added) HAS NO EMPLOYEE ID:
  // the moment the Employee scope is set to one of them, lock the Emp ID row
  // off (unchecked, non-interactive) — there is nothing to print. Any other
  // Employee scope leaves it exactly as toggleable as every other field.
  // Re-checked live on every change, same as the rest of this preview.
  function lockEmpIdForVisitor(isVisitor) {
    var cb = form.querySelector('[name="fields[emp_code]"]'); if (!cb) { return; }
    cb.disabled = isVisitor;
    if (isVisitor) { cb.checked = false; }
    var tr = cb.closest('tr'); if (tr) { tr.style.opacity = isVisitor ? '.5' : ''; }
  }
  function draw() {
    var templateLabel = templateLabels[val('scope[employee]')] || '';
    var isVisitor = templateLabel !== '';
    lockEmpIdForVisitor(isVisitor);
    var sz = document.getElementById('ic-size'); var opt = sz.options[sz.selectedIndex];
    var w = sz.value === 'custom' ? parseFloat(document.getElementById('ic-cw').value) || 85.6 : parseFloat(opt.getAttribute('data-w'));
    var h = sz.value === 'custom' ? parseFloat(document.getElementById('ic-ch').value) || 54 : parseFloat(opt.getAttribute('data-h'));
    var portrait = val('orientation') === 'portrait';
    if ((portrait && w > h) || (!portrait && h > w)) { var t = w; w = h; h = t; }
    document.getElementById('ic-custom').style.display = sz.value === 'custom' ? 'flex' : 'none';
    document.getElementById('ic-order').value = order().join(',');
    var c = {}; ['header','header_text','accent','background','text','label'].forEach(function (k) { c[k] = val('colors[' + k + ']'); });
    var allFields = order().filter(function (f) { return val('fields[' + f + ']'); });
    var onBack = function (f) { var r = form.querySelector('input[name="side[' + f + ']"]:checked'); return !!r && r.value === 'back'; };
    var fields = allFields.filter(function (f) { return !onBack(f); });
    var backFields = allFields.filter(onBack);
    var name = fields.indexOf('name') >= 0 ? (byCode.name || {}).value || '' : '';
    var desig = fields.indexOf('designation') >= 0 ? (byCode.designation || {}).value || '' : '';
    var title = val('title'), footer = val('footer').replace('{company}', company);
    var validTill = val('valid_till_mode') === 'days' ? (function () {
      var d = new Date(); d.setDate(d.getDate() + (parseInt(val('valid_till_days'), 10) || 365));
      function two(n) { return (n < 10 ? '0' : '') + n; }
      return two(d.getDate()) + '-' + two(d.getMonth() + 1) + '-' + d.getFullYear();
    })() : val('valid_till');
    var scale = 3.2, W = Math.round(w * scale), H = Math.round(h * scale);
    // 11 Sep -- see idCardHtml()'s own comment (public/app.php): height+overflow:hidden
    // used to silently clip or overlap once a long name/value needed more than 1 line;
    // min-height lets the preview grow instead, and clamp2 wraps up to 2 lines before
    // ellipsizing rather than cropping a single line mid-word.
    var clamp2 = 'white-space:normal;overflow-wrap:anywhere'; // wraps in full, never clipped (owner, 23 Oct)
    var hs = val('header_style') || 'solid';
    var chromed = hs !== 'stripe' && hs !== 'badge';
    var headerFg = chromed ? c.header_text : c.text;
    var headerBg = chromed ? c.header : 'transparent';
    var headerClip = hs === 'diagonal' ? 'clip-path:polygon(0 0,100% 0,100% 55%,0 100%);'
      : hs === 'arc' ? 'clip-path:ellipse(80% 100% at 50% 0%);' : '';
    var stripeW = 14;
    var html = '<div id="ic-preview" style="width:' + W + 'px;min-width:' + W + 'px;min-height:' + H + 'px;background:' + c.background + ';color:' + c.text + ';border:1px solid ' + c.header + ';border-radius:10px;position:relative;box-sizing:border-box;display:flex;flex-direction:column">';
    if (hs === 'stripe') { html += '<div style="position:absolute;left:0;top:0;bottom:0;width:' + stripeW + 'px;background:' + c.header + '"></div>'; }
    html += '<div style="background:' + headerBg + ';color:' + headerFg + ';' + headerClip + 'padding:8px 12px 8px ' + (hs === 'stripe' ? stripeW + 10 : 12) + 'px;display:flex;gap:8px;align-items:' + ((hs === 'diagonal' || hs === 'arc') ? 'flex-start' : 'center') + ';min-height:' + (portrait ? 46 : 38) + 'px">';
    if (val('show_logo') && logo) { html += '<img src="' + esc(logo) + '" alt="" style="height:26px;max-width:60px;object-fit:contain">'; }
    html += '<div style="flex:1;min-width:0">' + (val('show_company_name') ? '<div style="font-weight:700;font-size:13px;' + clamp2 + '">' + esc(company) + '</div>' : '')
      + (val('show_company_address') && tagline ? '<div style="font-size:8px;opacity:.85;' + clamp2 + '">' + esc(tagline) + '</div>' : '') + '</div>';
    if (title) { html += '<div style="font-size:8px;font-weight:700;letter-spacing:1px">' + esc(title) + '</div>'; }
    html += '</div>';
    var ph = '';
    if (val('show_photo')) {
      var pw = portrait ? 76 : 66, phh = portrait ? 92 : 84;
      var shape = val('photo_shape');
      if (shape === 'circle') { pw = phh = Math.min(pw, phh); }
      var radius = shape === 'rounded' ? '16px' : (shape === 'oval' || shape === 'circle') ? '50%' : '4px';
      var bStyle = val('photo_border'), bAmt = Math.max(0, Math.min(100, parseInt(val('photo_border_amount'), 10) || 0));
      var badgeRing = hs === 'badge' ? ('box-shadow:0 0 0 6px ' + c.header + ';') : '';
      var bCss = bStyle === 'double' ? ('border:2px solid ' + c.header + ';box-shadow:0 0 0 3px ' + c.background + ',0 0 0 5px ' + c.accent + ';')
        : bStyle === 'blur' ? ('border:none;box-shadow:inset 0 0 ' + Math.round(bAmt * 0.3) + 'px ' + Math.round(bAmt * 0.15) + 'px rgba(255,255,255,' + (bAmt / 100).toFixed(2) + ');')
        : 'border:1px solid #ccc;' + badgeRing;
      ph = '<div style="width:' + pw + 'px;height:' + phh + 'px;' + bCss + 'border-radius:' + radius + ';background:#f3f4f6;display:flex;align-items:center;justify-content:center;overflow:hidden;flex:none;' + (portrait ? 'margin:8px auto 4px' : '') + '">'
        + (isVisitor ? '<span style="font-size:15px;font-weight:800;letter-spacing:.5px;color:#374151">' + esc(templateLabel.toUpperCase()) + '</span>'
          : (photo ? '<img src="' + esc(photo) + '" style="width:100%;height:100%;object-fit:cover">' : '<span style="font-size:8px;color:#888">photo on file</span>')) + '</div>';
    }
    var body = '<div style="flex:1;min-width:0;font-size:9px;line-height:1.35">' + (name ? '<div style="font-weight:700;font-size:13px;color:' + c.header + '">' + esc(name) + '</div>' : '')
      + (desig ? '<div style="color:' + c.label + ';font-size:9px;margin-bottom:4px">' + esc(desig) + '</div>' : '');
    function lineHtml(f) {
      var l = byCode[f] || {label: labels[f] || f, value: '', kind: 'value'};
      if (l.kind === 'line') { return '<div style="margin-top:12px;border-top:1px solid #999;width:' + (portrait ? '100%' : '120px') + ';font-size:6.5px;color:' + c.label + '">' + esc(l.label) + '</div>'; }
      if (l.kind === 'barcode') {
        return (l.value && barcodeBars) ? '<div style="margin-top:6px">' + barcodeBars + '<div style="font-size:6px;letter-spacing:1px;color:' + c.label + ';margin-top:1px">' + esc(l.value) + '</div></div>' : '';
      }
      var v = f === 'valid_till' ? validTill : l.value;
      if (!v) { return ''; }
      return '<div style="display:flex;gap:6px"><span style="color:' + c.label + ';font-size:7px;text-transform:uppercase;max-width:' + (portrait ? 88 : 74) + 'px;flex:0 0 auto;padding-top:1px;white-space:normal;overflow-wrap:anywhere">' + esc(l.label) + '</span><span style="flex:1;min-width:0;' + clamp2 + '">' + esc(v) + '</span></div>';
    }
    fields.forEach(function (f) { if (f !== 'name' && f !== 'designation') { body += lineHtml(f); } });
    body += '</div>';
    html += '<div style="display:flex;' + (portrait ? 'flex-direction:column;' : 'gap:10px;') + 'padding:8px 12px 12px;flex:1;min-height:0">' + ph + body + '</div>';
    if (footer) { html += '<div style="font-size:6.5px;color:' + c.label + ';padding:0 12px 8px">' + esc(footer) + '</div>'; }
    html += '<div style="background:' + c.accent + ';height:6px;flex:none"></div></div>';
    var backText = val('back_text').replace('{company}', company);
    if (backText || backFields.length) {
      html += '<div style="width:' + W + 'px;min-width:' + W + 'px;min-height:' + H + 'px;background:' + c.background + ';border:1px solid ' + c.header + ';border-radius:10px;position:relative;box-sizing:border-box;display:flex;flex-direction:column;margin-top:10px">'
        + '<div style="background:' + c.header + ';height:6px;flex:none"></div>'
        + (backFields.length ? '<div style="font-size:9px;line-height:1.35;color:' + c.text + ';padding:10px 12px 0">' + backFields.map(lineHtml).join('') + '</div>' : '')
        + '<div style="flex:1;min-width:0;font-size:8px;line-height:1.5;color:' + c.text + ';padding:10px 12px;white-space:pre-line;overflow-wrap:anywhere">' + esc(backText) + '</div>'
        + '<div style="background:' + c.accent + ';height:6px;flex:none"></div></div>';
    }
    document.getElementById('ic-preview-wrap').innerHTML = html;
    document.getElementById('ic-dims').textContent = w + ' × ' + h + ' mm · ' + (portrait ? 'portrait' : 'landscape');
  }
  form.addEventListener('input', draw); form.addEventListener('change', draw);
  document.getElementById('ic-fields').addEventListener('click', function (ev) {
    var b = ev.target.closest('button'); if (!b) { return; }
    var tr = b.closest('tr');
    if (b.classList.contains('ic-up') && tr.previousElementSibling) { tr.parentNode.insertBefore(tr, tr.previousElementSibling); }
    if (b.classList.contains('ic-down') && tr.nextElementSibling) { tr.parentNode.insertBefore(tr.nextElementSibling, tr); }
    draw();
  });
  draw();
})();
</script>

<?php elseif ($route === 'attendance' && !$may('attendance.day.view')): ?>
  <div class="page-header"><div><h2>Employee Attendance</h2>
    <p>Settled days derived from raw punches</p></div></div>
  <div class="card">
    <div class="problem"><?= e($access->decide((string) $session->user()['role'],
      'attendance.day.view')->summary) ?></div>
  </div>

<?php elseif ($route === 'attendance' && (string) ($_GET['id'] ?? '') !== ''
    && !$scope->covers((string) $_GET['id'], $may('attendance.day.view.history'))): ?>
  <div class="page-header"><div><h2>Employee Attendance</h2></div></div>
  <div class="card">
    <div class="problem" style="margin:0"><?= e($scope->why((string) $_GET['id'])) ?></div>
    <p class="note" style="margin-top:10px">Reading somebody else's needs
       <code>attendance.punch.view.other</code>. Tenant isolation is structural here and always has been; this is the
       second lock &mdash; which rows, not which screen &mdash; and until recently there was no
       such lock at all.</p>
  </div>

<?php elseif ($route === 'attendance'): ?>
<?php
    $id = (string) ($_GET['id'] ?? '');
    $employment = $id === '' ? null : $store->find('employees', $id);
    // THE SHIFT IS PICKED FROM ORGANIZATION SETUP → SHIFTS, NOT TYPED (28 Sep).
    // No pick: the employee's own shift (scope ladder / roster), else the
    // calendar's default day.
    $attShifts = liveRows($store, 'shifts');
    $attShiftId = (string) ($_GET['shift_id'] ?? '');
    $attShiftRow = null;
    foreach ($attShifts as $attS) { (string) ($attS['id'] ?? '') === $attShiftId && $attShiftRow = $attS; }
    [$shiftStart, $shiftEnd] = $attShiftRow !== null && (string) ($attShiftRow['start_time'] ?? '') !== '' && (string) ($attShiftRow['end_time'] ?? '') !== ''
        ? [substr((string) $attShiftRow['start_time'], 0, 5), substr((string) $attShiftRow['end_time'], 0, 5)]
        : ($employment !== null
            ? (new SmartPRS\Surface\Shifts($store))->times($employment, $calendar->shiftStart(), $calendar->shiftEnd())
            : [$calendar->shiftStart(), $calendar->shiftEnd()]);
?>
<?php
