<script>
// THE SIDEBAR KEEPS ITS PLACE. Every click is a full page load, so a menu with
// sixteen sections snapped back to the top on each one and the person scrolled
// down again to find where they were. The scroll offset is kept per browser tab
// and restored before the first paint; with nothing kept, the active item is
// brought into view.
(function () {
  var nav = document.querySelector('.sidebar-nav');
  if (!nav) { return; }
  var key = 'smartprs.sidebar.scroll';
  try {
    var kept = sessionStorage.getItem(key);
    if (kept !== null) {
      nav.scrollTop = parseInt(kept, 10) || 0;
    } else {
      var active = nav.querySelector('.nav-item.active');
      if (active && active.scrollIntoView) { active.scrollIntoView({ block: 'center' }); }
    }
    nav.addEventListener('scroll', function () { sessionStorage.setItem(key, String(nav.scrollTop)); }, { passive: true });
    nav.addEventListener('click', function () { sessionStorage.setItem(key, String(nav.scrollTop)); }, true);
  } catch (e) {
    // sessionStorage can be unavailable (private mode, blocked storage); the menu still works, it just starts at the top.
  }
})();
</script>
<script>
// PHOTO CROPPING ON UPLOAD (11 Sep) -- every "photo" file input (marked
// data-crop="photo": the employee photo field wherever it's rendered, the ID
// Cards quick-attach picker, and the Account settings photo picker) gets a
// plain canvas crop step before the file is actually submitted. No library:
// drag a rectangle over the picked image, Apply re-encodes just that
// rectangle as a JPEG and swaps it into the input via DataTransfer -- the
// crop is baked into the STORED photo once, exactly like an already-cropped
// photo uploaded from anywhere else, so idCardHtml(), its JS mirror and
// IdCardPdf all keep working unchanged; none of them need to know a crop
// happened. Present on every page (most have no matching input, a no-op).
(function () {
  var inputs = document.querySelectorAll('input[type=file][data-crop="photo"]');
  if (!inputs.length) { return; }

  function openCropper(file, onDone) {
    var reader = new FileReader();
    reader.onload = function () {
      var img = new Image();
      img.onload = function () {
        var maxW = Math.min(480, window.innerWidth - 60);
        var scale = Math.min(1, maxW / img.width);
        var dispW = Math.round(img.width * scale), dispH = Math.round(img.height * scale);

        var overlay = document.createElement('div');
        overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center';
        var panel = document.createElement('div');
        panel.style.cssText = 'background:#fff;border-radius:10px;padding:16px;max-width:96vw;box-shadow:0 10px 40px rgba(0,0,0,.3)';
        panel.innerHTML = '<div style="font:600 14px/1.3 inherit;margin-bottom:8px;color:#1F2937">Drag to select the crop area</div>';

        var stage = document.createElement('div');
        stage.style.cssText = 'position:relative;width:' + dispW + 'px;height:' + dispH + 'px;overflow:hidden;cursor:crosshair;user-select:none;touch-action:none;background-image:url(' + reader.result + ');background-size:' + dispW + 'px ' + dispH + 'px';

        var sel = document.createElement('div');
        sel.style.cssText = 'position:absolute;border:2px dashed #fff;box-shadow:0 0 0 2000px rgba(0,0,0,.45);pointer-events:none';
        var pad = Math.round(Math.min(dispW, dispH) * 0.1);
        var box = { x: pad, y: pad, w: Math.min(dispW, dispH) - pad * 2, h: Math.min(dispW, dispH) - pad * 2 };

        function paint() { sel.style.left = box.x + 'px'; sel.style.top = box.y + 'px'; sel.style.width = box.w + 'px'; sel.style.height = box.h + 'px'; }
        paint();
        stage.appendChild(sel);

        var dragging = null;
        stage.addEventListener('mousedown', function (ev) {
          var r = stage.getBoundingClientRect();
          dragging = { x0: ev.clientX - r.left, y0: ev.clientY - r.top };
        });
        function move(ev) {
          if (!dragging) { return; }
          var r = stage.getBoundingClientRect();
          var x1 = Math.max(0, Math.min(dispW, ev.clientX - r.left));
          var y1 = Math.max(0, Math.min(dispH, ev.clientY - r.top));
          box = { x: Math.min(dragging.x0, x1), y: Math.min(dragging.y0, y1), w: Math.abs(x1 - dragging.x0), h: Math.abs(y1 - dragging.y0) };
          paint();
        }
        window.addEventListener('mousemove', move);
        window.addEventListener('mouseup', function () { dragging = null; });

        var actions = document.createElement('div');
        actions.style.cssText = 'margin-top:12px;display:flex;gap:8px;justify-content:flex-end';
        var skip = document.createElement('button'); skip.type = 'button'; skip.className = 'btn btn-outline btn-sm'; skip.textContent = 'Use original, uncropped';
        var apply = document.createElement('button'); apply.type = 'button'; apply.className = 'btn btn-primary btn-sm'; apply.textContent = 'Apply crop';
        actions.appendChild(skip);
        actions.appendChild(apply);
        panel.appendChild(stage);
        panel.appendChild(actions);
        overlay.appendChild(panel);
        document.body.appendChild(overlay);

        function close() {
          window.removeEventListener('mousemove', move);
          document.body.removeChild(overlay);
        }
        skip.addEventListener('click', close);
        apply.addEventListener('click', function () {
          if (box.w < 10 || box.h < 10) { close(); return; }
          var canvas = document.createElement('canvas');
          canvas.width = Math.round(box.w / scale);
          canvas.height = Math.round(box.h / scale);
          var ctx = canvas.getContext('2d');
          ctx.drawImage(img, box.x / scale, box.y / scale, box.w / scale, box.h / scale, 0, 0, canvas.width, canvas.height);
          canvas.toBlob(function (blob) {
            onDone(new File([blob], file.name.replace(/\.[^.]+$/, '') + '.jpg', { type: 'image/jpeg' }));
            close();
          }, 'image/jpeg', 0.9);
        });
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  }

  inputs.forEach(function (input) {
    input.addEventListener('change', function () {
      var file = input.files && input.files[0];
      if (!file || file.type.indexOf('image/') !== 0) { return; }
      openCropper(file, function (cropped) {
        var dt = new DataTransfer();
        dt.items.add(cropped);
        input.files = dt.files;
      });
    });
  });
})();
</script>
<script>
// FIELD-LEVEL VALIDATION, EVERY PAGE (owner request, 18 Sep 2026, generalising
// the Salary structure slab builder's own field-by-field checking: "This rule
// should be followed in the entire application — any where, any page"). One
// listener, attached once here rather than once per screen, because every
// field this application renders through the config-driven engine
// (surface/Modules.php::fields()) already carries its rules as native HTML
// attributes — required, pattern, min, max, type=email/number/tel/... — and
// so does most hand-built markup elsewhere in this file. The browser has
// always been ABLE to say a field is wrong the moment it is wrong; this only
// makes it SAY SO, in this application's own red-border-and-note style
// instead of a silent internal flag nobody sees until Save is clicked.
//
// Nothing here re-implements a validation rule. It reads field.validationMessage
// — the browser's own verdict from the attributes already on the element — so
// a field whose rule changes in config/modules.json (a min raised, an option
// added) is correct here with no matching JS to keep in step.
(function () {
  function isField(t) {
    return !!(t && t.matches && t.matches('input, select, textarea'));
  }

  // THE MESSAGE SITS RIGHT AFTER THE FIELD, not in a shared banner — so on a
  // form with several problems, each one is read next to the box it is
  // about, the same convention the Salary structure screen's slab ranges and
  // its "Row N (CODE): ..." banner both already use.
  function noteFor(field) {
    var note = field.nextElementSibling;

    if (!note || !note.classList || !note.classList.contains('field-live-error')) {
      note = document.createElement('div');
      note.className = 'field-live-error note no';
      note.style.marginTop = '4px';
      field.insertAdjacentElement('afterend', note);
    }

    return note;
  }

  function paint(field) {
    if (!field.willValidate) { return; } // disabled/readonly/no constraints: nothing to say
    // validity.valid, NOT checkValidity(): checkValidity() fires `invalid`,
    // whose listener below calls paint() again — an endless loop that died
    // with "Maximum call stack size exceeded" before a single message was
    // drawn, so every invalid field on every screen stayed silent (found
    // 21 Sep chasing the owner's "field-level validation" complaint).
    var ok = field.validity.valid;
    field.style.borderColor = ok ? '' : '#b42318';
    field.style.background = ok ? '' : '#fef2f2';
    var next = field.nextElementSibling;
    if (ok && !(next && next.classList && next.classList.contains('field-live-error'))) { return; } // nothing to say: add no empty note that shifts the layout under the pointer
    noteFor(field).textContent = ok ? '' : field.validationMessage;
  }

  // LIVE — every keystroke and every choice, not only a click on Save, which
  // was the original complaint. `focusout` catches the other half: a
  // required field left blank turns red the moment it is tabbed past, not
  // only once the whole form is submitted.
  ['input', 'change', 'focusout'].forEach(function (type) {
    document.addEventListener(type, function (ev) {
      if (isField(ev.target)) { paint(ev.target); }
    }, true);
  });

  // THE SAME TREATMENT AT SAVE TIME. The browser fires `invalid` on every
  // field that is blocking a submit, right before it refuses to submit and
  // focuses the first one — this only paints that moment the same red-and-note
  // way, so Save behaves exactly like typing does, everywhere, rather than
  // this page's forms getting one behaviour and another page's getting the
  // browser's own unstyled tooltip.
  document.addEventListener('invalid', function (ev) {
    if (isField(ev.target)) { paint(ev.target); }
  }, true);
})();
</script>
<script>
// MISSING FIELDS, LISTED IN THE MIDDLE OF THE PAGE (owner, 5 Nov 2026): the browser's own bubble named one field, often
// one hidden under the pinned bar or behind a custom dropdown. On a Save that the browser refuses, every field blocking it
// is listed by name in one centred popup, and OK puts the cursor on the first one from the top. App-wide, every form.
(function () {
  var tried = 0, bad = [], timer = null;
  var mark = function () { tried = Date.now(); };
  var rs = HTMLFormElement.prototype.requestSubmit;
  if (rs) { HTMLFormElement.prototype.requestSubmit = function () { mark(); return rs.apply(this, arguments); }; }
  document.addEventListener('click', function (ev) { var b = ev.target.closest && ev.target.closest('button, input[type=submit], input[type=image]');
    if (b && b.form && (b.type === 'submit' || b.type === 'image')) { mark(); } }, true);
  document.addEventListener('keydown', function (ev) { if (ev.key === 'Enter' && ev.target.form && ev.target.tagName !== 'TEXTAREA') { mark(); } }, true);
  var shown = function (el) { if (!el) { return false; } var cs = getComputedStyle(el), r = el.getBoundingClientRect();
    return el.offsetParent !== null && cs.visibility !== 'hidden' && parseFloat(cs.opacity) > 0.05 && r.width > 4 && r.height > 4; };
  var labelOf = function (el) {
    var l = el.id ? document.querySelector('label[for="' + CSS.escape(el.id) + '"]') : null;
    if (!l) { var c = el.closest('div'); l = c ? c.querySelector('label') : null; }
    var t = (l ? l.textContent : (el.getAttribute('aria-label') || el.name || 'A field')).replace(/\*/g, '').replace(/\s+/g, ' ').trim();
    var box = el.closest('fieldset'), lg = box ? box.querySelector('legend') : null;
    return lg && lg.textContent.trim() !== '' && lg.textContent.trim().toLowerCase() !== t.toLowerCase() ? t + ' (' + lg.textContent.trim() + ')' : t;
  };
  var target = function (el) { if (shown(el)) { return el; }
    var p = el.parentNode, alt = p ? [].find.call(p.querySelectorAll('input:not([type=hidden]), select, textarea, button'), shown) : null;
    return alt || el; };
  var show = function () {
    timer = null; var list = bad.slice(); bad = [];
    if (!list.length) { return; }
    list.sort(function (a, b) { var p = a.compareDocumentPosition(b); return p & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1; });
    var d = document.getElementById('sp-missing');
    if (!d) { d = document.createElement('dialog'); d.id = 'sp-missing';
      d.style.cssText = 'position:fixed;inset:0;margin:auto;height:fit-content;max-height:86vh;border:0;border-radius:14px;padding:0;width:min(480px,92vw);box-shadow:0 24px 60px -12px rgba(15,23,42,.5);z-index:10050';
      document.body.appendChild(d); }
    var rows = list.map(function (el) { var why = el.validity.valueMissing ? 'required' : el.validationMessage;
      return '<li style="margin:4px 0"><b>' + labelOf(el).replace(/[&<>]/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]; }) + '</b>'
        + (why && why !== 'required' ? ' &mdash; <span style="color:#64748b">' + why.replace(/[&<>]/g, '') + '</span>' : '') + '</li>'; }).join('');
    d.innerHTML = '<div style="padding:18px 22px 6px;border-bottom:1px solid #e2e8f0;display:flex;gap:10px;align-items:center">'
      + '<i class="fas fa-circle-exclamation" style="color:#dc2626;font-size:20px"></i><h3 style="margin:0;font-size:16px">Not saved &mdash; fill ' + (list.length === 1 ? 'this field' : 'these ' + list.length + ' fields') + ' first</h3></div>'
      + '<ol style="margin:12px 0;padding:0 22px 0 42px;max-height:50vh;overflow:auto;font-size:14px">' + rows + '</ol>'
      + '<div style="padding:12px 22px 16px;display:flex;justify-content:flex-end"><button type="button" class="go" data-ok><i class="fas fa-arrow-right"></i> Go to ' + labelOf(list[0]).replace(/[&<>]/g, '') + '</button></div>';
    var first = target(list[0]);
    d.querySelector('[data-ok]').onclick = function () { d.close(); };
    // after the dialog hands focus back to the button that opened it — then the cursor goes to the first missing field
    d.onclose = function () { var go = function () { var dt = first.closest('details'); if (dt) { dt.open = true; }
      try { first.focus({preventScroll: true}); } catch (x) { first.focus(); } first.scrollIntoView({block: 'center'}); };
      setTimeout(go, 30); setTimeout(go, 250); };
    d.open || d.showModal();
  };
  document.addEventListener('invalid', function (ev) {
    if (Date.now() - tried > 1500 || !ev.target.form) { return; } // a script's own silent check, not a Save
    ev.preventDefault(); // no browser bubble — the popup says it all
    bad.indexOf(ev.target) < 0 && bad.push(ev.target);
    timer || (timer = setTimeout(show, 0));
  }, true);
})();
</script>
<?php
// ORG CASCADE DATA — orgGraph() once per page, for every Company / Branch /
// Department / Designation / Role / Team dropdown the script below finds.
try {
    $orgGraphJson = (string) json_encode(orgGraph($store), JSON_HEX_TAG | JSON_HEX_AMP | JSON_UNESCAPED_UNICODE);
} catch (\Throwable) {
    // A page rendered before a tenant's store is readable (sign-in, set-password)
    // has no org registers, so the dropdowns simply do not cascade there.
    //
    // NOT a swallow, and therefore carrying no allow-annotation: the line below is
    // the answer — an empty graph — not the absence of one. It used to be annotated
    // anyway, and the gate was right to call that unnecessary. An annotation on a
    // catch that actually handles is how a real swallowed exception later hides in
    // plain sight, one careless edit after somebody stops reading them.
    $orgGraphJson = '{"p":[],"k":{}}';
}
