  .row > div:has(> select, > input:not([type=checkbox]):not([type=radio]):not([type=hidden]), > textarea, > div > select, > div > input:not([type=checkbox]):not([type=radio]):not([type=hidden])) { min-width:min-content !important; flex-basis:160px; }
  .row > div[style*="min-width:210px"]:has(> select, > input, > textarea, > div > select, > div > input) { flex-basis:210px; }
  form[style*="display:flex"] > div, div[style*="display:flex"] > div { min-width:min-content; }
