<script>
window.SPRS_ORG = <?= $orgGraphJson ?>;
(function () {
  'use strict';
  var KEYS = ['company', 'city', 'branch', 'department', 'designation', 'role', 'team', 'shift'];
  var PAIR = {}, REL = {}, KNOWN = {};
  (window.SPRS_ORG.p || []).forEach(function (p) {
    PAIR[p] = 1;
    var s = p.split('|');
    REL[s[0] + '|' + s[1] + '|' + s[2]] = 1;
  });
  Object.keys(window.SPRS_ORG.k || {}).forEach(function (k) {
    (window.SPRS_ORG.k[k] || []).forEach(function (n) { KNOWN[k + '|' + String(n)] = 1; });
  });
  function norm(v) { return String(v == null ? '' : v).trim().toLowerCase().replace(/\|/g, '/'); }
  // The register name an option stands for. Some lists add context to the label —
  // "KONDAPUR (Ametecs India Pvt Ltd)" on Late Login Policy (17 Oct) — so a label the
  // registers do not know is tried again without its trailing "(…)".
  function oname(k, o) {
    var t = norm(o.text);
    if (!KNOWN[k + '|' + t]) { var b = t.replace(/\s*\([^()]*\)\s*$/, ''); if (KNOWN[k + '|' + b]) { return b; } }
    return t;
  }

  // ORG CASCADE — ONE BEHAVIOUR, EVERY SCREEN. A <select> is a Company /
  // Branch / Department / Designation / Role / Team dropdown when its name
  // says so (f_branch, branch_id, to_branch, scope[branch], employer_company_id
  // …) or it carries data-org="<key>", AND it offers at least one name the org
  // registers know (so an unrelated "role" access-tier select is never
  // touched; a bare name="role" is skipped for the same reason). Dropdowns in
  // the same row / form narrow each other in ANY order: pick a Branch first
  // and Company, Department, Designation and Team shrink to what sits with
  // it. A name with no recorded link either way is never hidden — a branch
  // with no company set up still shows under every company.
  function keyOf(sel) {
    if (sel._orgKey !== undefined) { return sel._orgKey; }
    var k = null, d = sel.getAttribute('data-org'), n = sel.name || '';
    if (d) {
      k = KEYS.indexOf(d) >= 0 ? d : null;
    } else if (n !== 'role') {
      var m = n.match(/\[([^\]]+)\]$/);
      if (m) { n = m[1]; }
      n = n.replace(/^(f|to|from|new|scope)_/, '').replace(/^employer_/, '').replace(/_id$/, '');
      // City only by data-org: an address "city" dropdown must never narrow a Branch.
      if (KEYS.indexOf(n) >= 0 && n !== 'city') {
        for (var i = 0; i < sel.options.length; i++) {
          if (sel.options[i].value !== '' && KNOWN[n + '|' + oname(n, sel.options[i])]) { k = n; break; }
        }
      }
    }
    sel._orgKey = k;
    return k;
  }
  function scopeOf(el) {
    return el.closest('[data-org-scope]') || el.closest('tr') || el.closest('form') || el.closest('fieldset') || document.body;
  }
  function orgSelects(scope) {
    return Array.prototype.filter.call(scope.querySelectorAll('select'), function (s) { return keyOf(s) !== null && scopeOf(s) === scope; });
  }
  function picked(list) {
    var out = {};
    list.forEach(function (s) {
      var o = s.options[s.selectedIndex];
      if (o && o.value !== '') { out[s._orgKey] = oname(s._orgKey, o); }
    });
    return out;
  }
  function fits(k, x, sel) {
    for (var j in sel) {
      if (j === k) { continue; }
      var v = sel[j];
      // A shift set up for a company belongs to THAT company only, even when the company picked has no
      // shift of its own (17 Oct: ABC Recoveries was offered Ametecs' "General").
      if (REL[k + '|' + x + '|' + j] && (k === 'shift' || REL[j + '|' + v + '|' + k]) && !PAIR[k + '|' + x + '|' + j + '|' + v]) { return false; }
    }
    return true;
  }
  // The "ALL / none" choice of a list: value "" — or, on screens that store the word, an option reading "All".
  function allOf(s) {
    for (var i = 0; i < s.options.length; i++) { if (s.options[i].value === '' || /^all$/i.test(s.options[i].value)) { return s.options[i]; } }
