  // the WHOLE list (scrollable), typing narrows it by any part of the code or
  // name, arrows + Enter or a click choose.
  function initPicker(w) {
    if (w._ep) { return; }
    w._ep = 1;
    var box = w.querySelector('.emp-pick-text'), hid = w.querySelector('input[type=hidden]');
    var list = w.querySelector('.emp-pick-list'), meta = w.querySelector('.emp-pick-meta');
    var raw = [];
    try { raw = JSON.parse(w.querySelector('.emp-pick-data').textContent) || []; } catch (e) { raw = []; }
    var items = raw.map(function (d) {
      return {v: String(d[0]), l: String(d[1]), m: String(d[2] || ''), o: d[3] || null, s: norm(d[1] + ' ' + (d[2] || ''))};
    });
    var orgSel = {}, shown = [], active = -1, LIMIT = 400;
    function allowed(it) {
      if (!it.o) { return true; }
      for (var j in orgSel) { if (norm(it.o[j]) !== orgSel[j]) { return false; } }
