        list.style.bottom = (window.innerHeight - r.top + 2) + 'px';
        list.style.maxHeight = Math.min(300, r.top - 12) + 'px';
      } else {
        list.style.bottom = '';
        list.style.top = (r.bottom + 2) + 'px';
