    // match, is taken; anything else stays as typed (a filter box still
    // accepts a code) but a REQUIRED picker refuses to submit it.
    function settle() {
      var t = box.value.trim();
      if (t === '') { choose(null); return; }
      var cur = byValue(hid.value);
      if (cur && cur.l === box.value) { return; }
      var n = norm(t), hit = null;
      items.forEach(function (it) { if (!hit && allowed(it) && (norm(it.v) === n || norm(it.l) === n)) { hit = it; } });
      if (!hit) {
        var m = items.filter(function (it) { return allowed(it) && n.split(/\s+/).every(function (x) { return it.s.indexOf(x) >= 0; }); });
        if (m.length === 1) { hit = m[0]; }
