    window.addEventListener('resize', function () { if (!list.hidden) { place(); } });
    document.addEventListener('mousedown', function (ev) { if (!list.hidden && !w.contains(ev.target)) { close(); } });
    w._set = function (v) { choose(byValue(v) || (v === '' ? null : {v: v, l: v, m: ''}), true); };
    w._orgFilter = function (sel, byPerson) {
      orgSel = sel;
      var cur = byValue(hid.value);
