  css.textContent = '.flash-pop{position:absolute;z-index:1200;max-width:min(460px,92vw);padding:12px 34px 12px 14px;border-radius:10px;font-size:13.5px;line-height:1.45;box-shadow:0 14px 34px -10px rgba(15,23,42,.45);border:1px solid}'
    + '.flash-pop.bad{background:#fef2f2;color:#991b1b;border-color:#fca5a5}.flash-pop.ok{background:#f0fdf4;color:#166534;border-color:#86efac}'
    + '.flash-pop:before{content:"";position:absolute;top:-7px;left:18px;width:12px;height:12px;background:inherit;border-left:1px solid;border-top:1px solid;border-color:inherit;transform:rotate(45deg)}'
    + '.flash-pop button{position:absolute;top:6px;right:8px;background:none;border:0;font-size:18px;line-height:1;color:inherit;cursor:pointer;padding:2px}';
  document.head.appendChild(css);
