    close.onclick = function () { pop.remove(); };
    pop.appendChild(close);
    pop.style.left = Math.max(8, Math.min(x, maxLeft)) + 'px';
    pop.style.top = (y + 10 + k * 6) + 'px';
    document.body.appendChild(pop);
    m.style.display = 'none';
    if (!bad) { setTimeout(function () { pop.style.transition = 'opacity .6s'; pop.style.opacity = '0'; setTimeout(function () { pop.remove(); }, 700); }, 7000); }
    k === 0 && pop.scrollIntoView({ block: 'center' });
  });
})();
</script>
<style>
  .ms-wrap{position:relative;display:block;width:100%;min-width:0;max-width:100%}
  .ms-btn{width:100%;min-width:0;box-sizing:border-box;display:flex;justify-content:space-between;align-items:center;gap:4px;text-align:left;background:var(--card);border:1px solid var(--border);border-radius:8px;padding:6px 8px;font:inherit;font-size:13px;color:var(--text1);cursor:pointer;min-height:34px}
  .ms-btn span{white-space:normal;overflow-wrap:anywhere}
  .ms-btn:disabled{opacity:.55;cursor:not-allowed}
  .ms-pan{position:fixed;z-index:1000;min-width:240px;max-width:360px;background:var(--card);border:1px solid var(--border);border-radius:10px;box-shadow:0 12px 30px -10px rgba(15,23,42,.35);padding:8px}
  .ms-pan input[type=search]{width:100%;margin-bottom:6px}
  .ms-acts{display:flex;justify-content:space-between;font-size:12px;margin:0 2px 6px}
  .ms-list{max-height:240px;overflow:auto}
  .ms-list label{display:flex;gap:8px;align-items:center;padding:5px 6px;border-radius:6px;font-size:13px;cursor:pointer;margin:0;font-weight:400;color:var(--text1)}
  .ms-list label:hover{background:var(--accent-soft)}
</style>
<script>
// A MULTI-SELECT IS A DROPDOWN WITH CHECKBOXES, EVERYWHERE (owner, 13 Oct). Every <select multiple> —
// including ones a screen builds in the browser, like Salary Structure's Designation — becomes a
// button that opens a ticked list. The real <select> stays (hidden) and is what the form submits;
// the list is rebuilt from its current options each time it opens, so cascades that hide options
// still apply. Opt out with data-native.
(function () {
  var done = new WeakSet();
  var label = function (sel) {
    var on = [].filter.call(sel.options, function (o) { return o.selected; });
    return on.length === 0 ? (sel.getAttribute('data-placeholder') || 'All') : (on.length === 1 ? on[0].textContent.trim() : on.length + ' selected');
  };
  var enhance = function (sel) {
    if (done.has(sel) || sel.hasAttribute('data-native')) { return; }
    done.add(sel);
    // a cloned row carries the old widget beside its select: drop it
    if (sel.parentNode && sel.parentNode.classList && sel.parentNode.classList.contains('ms-wrap')) {
      var stale = sel.parentNode.querySelectorAll('.ms-btn, .ms-pan'); [].forEach.call(stale, function (n) { n.remove(); });
    } else {
      var w = document.createElement('span'); w.className = 'ms-wrap'; sel.parentNode.insertBefore(w, sel); w.appendChild(sel);
    }
    var wrap = sel.parentNode;
    sel.style.display = 'none';
    var btn = document.createElement('button'); btn.type = 'button'; btn.className = 'ms-btn';
    btn.innerHTML = '<span></span><i class="fas fa-chevron-down" style="font-size:10px;color:var(--text3)"></i>';
    var pan = document.createElement('div'); pan.className = 'ms-pan'; pan.hidden = true;
    pan.innerHTML = '<input type="search" placeholder="Type to narrow"><div class="ms-acts"><a href="#" data-a="all">Tick all shown</a><a href="#" data-a="none">Clear</a></div><div class="ms-list"></div>';
    // as tall as the ordinary dropdowns beside it, so a row of filters lines up
    var ref = (wrap.closest('form, tr, .row, [class*="row"]') || document).querySelector('select:not([multiple])');
    ref && ref.offsetHeight > 0 && (btn.style.height = ref.offsetHeight + 'px');
    wrap.appendChild(btn); wrap.appendChild(pan);
    var list = pan.querySelector('.ms-list'), q = pan.querySelector('input');
    var sync = function () { btn.firstChild.textContent = label(sel); btn.disabled = sel.disabled; btn.title = [].filter.call(sel.options, function (o) { return o.selected; }).map(function (o) { return o.textContent.trim(); }).join(', '); };
    var build = function () {
      list.innerHTML = '';
      [].forEach.call(sel.options, function (o, i) {
        if (o.hidden || o.disabled || o.value === '') { return; }
        var l = document.createElement('label');
        l.innerHTML = '<input type="checkbox"> <span></span>';
        l.querySelector('span').textContent = o.textContent.trim();
        l.querySelector('input').checked = o.selected;
        l.querySelector('input').addEventListener('change', function (e) { o.selected = e.target.checked; sel.dispatchEvent(new Event('change', { bubbles: true })); sync(); });
        list.appendChild(l);
      });
      q.value = '';
    };
    q.addEventListener('input', function () { var t = q.value.toLowerCase(); [].forEach.call(list.children, function (l) { l.style.display = l.textContent.toLowerCase().indexOf(t) >= 0 ? '' : 'none'; }); });
    pan.addEventListener('click', function (e) {
      var a = e.target.getAttribute && e.target.getAttribute('data-a'); if (!a) { return; } e.preventDefault();
      [].forEach.call(list.children, function (l) { if (l.style.display !== 'none') { var c = l.querySelector('input'); if (c.checked !== (a === 'all')) { c.checked = a === 'all'; c.dispatchEvent(new Event('change')); } } });
    });
    btn.addEventListener('click', function () {
      if (sel.disabled) { return; }
      if (pan.hidden) {
        build();
        // FLOATS ABOVE THE PAGE (a grid row's overflow would clip it), under its button, inside the screen.
        var r = btn.getBoundingClientRect(), w = Math.max(240, r.width);
        pan.style.position = 'fixed'; pan.style.width = Math.min(w, 360) + 'px';
        pan.style.left = Math.max(8, Math.min(r.left, window.innerWidth - Math.min(w, 360) - 8)) + 'px';
        pan.hidden = false;
        var below = window.innerHeight - r.bottom - 8, h = pan.offsetHeight;
        pan.style.top = (below >= h || r.top < h ? r.bottom + 4 : r.top - h - 4) + 'px';
        q.focus();
      } else { pan.hidden = true; }
    });
    window.addEventListener('scroll', function (e) { if (!pan.contains(e.target)) { pan.hidden = true; } }, true);
    document.addEventListener('click', function (e) { if (!wrap.contains(e.target)) { pan.hidden = true; } });
    sel.addEventListener('change', sync);
    new MutationObserver(sync).observe(sel, { attributes: true, attributeFilter: ['disabled'] });
    sync();
  };
  var scan = function (root) { (root.querySelectorAll ? root : document).querySelectorAll('select[multiple]').forEach(enhance); if (root.matches && root.matches('select[multiple]')) { enhance(root); } };
  var start = function () {
    scan(document);
    new MutationObserver(function (ms) { ms.forEach(function (m) { [].forEach.call(m.addedNodes, function (n) { n.nodeType === 1 && scan(n); }); }); }).observe(document.body, { childList: true, subtree: true });
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', start) : start();
})();
</script>
