<script>
// COMPANY NAMES WEAR THEIR BRAND COLOUR, EVERYWHERE (owner, 13 Oct): any table cell, badge or tag
// whose whole text is a company's name gets a dot and text in that company's colour, as set at
// Organization Configuration → Companies (companyColor()). Exact matches only — nothing else changes.
(function () {
  var map = <?= json_encode(array_filter(companyColors($store), static fn ($c): bool => str_starts_with((string) $c, '#')), JSON_HEX_TAG | JSON_HEX_AMP | JSON_UNESCAPED_UNICODE) ?>;
  if (!Object.keys(map).length) { return; }
  var paint = function (root) {
    (root || document).querySelectorAll('td, .badge, .pe-facts span, .hy-sub, .note b, li').forEach(function (el) {
      if (el.dataset.coPainted || el.children.length > 1) { return; }
      var c = map[(el.textContent || '').trim().toLowerCase()];
      if (!c) { return; }
      el.dataset.coPainted = '1';
      el.style.color = c; el.style.fontWeight = '600';
      el.insertAdjacentHTML('afterbegin', '<span aria-hidden="true" style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + c + ';margin-right:6px;vertical-align:1px"></span>');
    });
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', function () { paint(); }) : paint();
})();
</script>
<?php endif; ?>
<script>
// ONE SUBMIT, ONE ACTION (owner, 16 Oct): every POST form gets a fresh `_once` token as it is
// submitted; the server refuses a token it has already seen (double-click, F5 resubmit). The
// token is replaced 1.5 s later, so a form that stays on the page (a download) can be used again.
(function () {
  var mint = function () { return Date.now().toString(36) + Math.random().toString(36).slice(2, 12); };
  document.addEventListener('submit', function (e) {
    var f = e.target;
    if (!f || (f.getAttribute('method') || '').toLowerCase() !== 'post') { return; }
    var t = f.querySelector('input[name=_once]');
    if (!t) { t = document.createElement('input'); t.type = 'hidden'; t.name = '_once'; t.value = mint(); f.appendChild(t); }
    clearTimeout(f._onceTimer);
    f._onceTimer = setTimeout(function () { t.value = mint(); }, 1500);
  }, true);
})();
</script>
<script>
// DEEP LINKS LAND ON THE FIELD (owner, 12 Oct: "the page should go to that particular
// module, respective tab inside that and cursor should be focussed there ... application
// wide"). Any link ending #<element id> opens the collapsed sections holding it, scrolls
// it to the middle of the screen and puts the cursor in it (or in its first field).
(function () {
  var id = '';
  try { id = decodeURIComponent(location.hash.slice(1)); } catch (e) { return; }
  var el = id ? document.getElementById(id) : null;
  if (!el) { return; }
  for (var p = el; p; p = p.parentElement) { if (p.tagName === 'DETAILS') { p.open = true; } }
  var F = 'input:not([type=hidden]):not([disabled]):not([readonly]),select:not([disabled]),textarea:not([disabled]):not([readonly])';
  var B = 'button:not([disabled]),a[href]';
  // A VISIBLE FIELD (owner, 29 Oct: "New Advance … the cursor is moving somewhere else; it should be at the employee
  // ID field; do not scroll the page"): a select hidden behind its searchable picker is skipped for the picker's box.
  var seen = function (n) { return n.offsetParent !== null && getComputedStyle(n).visibility !== 'hidden'; };
  var first = function (sel) { return [].filter.call(el.querySelectorAll(sel), seen)[0] || null; };
  var target = el;
  window.addEventListener('load', function () {
    target = el.matches(F + ',' + B) ? el : (first(F) || first(B) || el);
    if (el.matches(F + ',' + B)) {
      el.scrollIntoView({ block: 'center' });
    } else {
      // A FORM OR BOX: the page stays at the top when the box already starts on the first screen (the browser's own
      // jump to #id is undone); only a box further down is brought to just under the top bar.
      var bar = (document.querySelector('.topbar') || { offsetHeight: 0 }).offsetHeight;
      var abs = el.getBoundingClientRect().top + window.scrollY;
      abs < window.innerHeight - 160 ? window.scrollTo(0, 0) : window.scrollTo(0, abs - bar - 8);
    }
    if (target === el && !el.hasAttribute('tabindex')) { el.setAttribute('tabindex', '-1'); }
    target.focus({ preventScroll: true });
    var box = target.closest('label, .row > div, td') || target;
    box.style.outline = '3px solid #f59e0b';
    box.style.outlineOffset = '2px';
    setTimeout(function () { box.style.outline = ''; box.style.outlineOffset = ''; }, 2500);
  });
})();
</script>
<style>
/* THE FIRST ROW OF CARDS STAYS IN VIEW (owner, 29 Oct 2026: "even in the Dashboards, the top 1st block cards of
   dashboard should be visible while scrolling the rest of the page"): Dashboard, Directory and every screen whose
   first block is a row of figure cards. Not on a phone width, not when printing. */
.tiles-fixed{position:sticky;z-index:40;background:var(--bg, #f1f5f9);padding-top:6px;padding-bottom:6px;margin-top:-6px}
.tiles-fixed.stuck{box-shadow:0 8px 14px -10px rgba(15,23,42,.35)}
@media print{.tiles-fixed{position:static !important;box-shadow:none !important}}
</style>
<script>
(function () {
  var start = function () {
    if (window.innerWidth < 760) { return; }
    var c = document.querySelector('.content');
    if (!c) { return; }
    var t = c.querySelector('.dash-kpis, .dc-grid, .kpi-strip, .stats-grid');
    // THE FIRST BLOCK ONLY: a card row further down the page is a section of it, not its header.
    if (!t || t.getBoundingClientRect().top + window.scrollY > 520 || t.closest('table, dialog, details:not([open])')) { return; }
    for (var p = t.parentElement; p && p !== document.body; p = p.parentElement) {
      if (getComputedStyle(p).overflow === 'hidden') { p.style.overflow = 'clip'; }   // hidden would hold the row inside its box
    }
    var bar = (document.querySelector('.topbar') || { offsetHeight: 0 }).offsetHeight;
    t.classList.add('tiles-fixed');
    t.style.top = bar + 'px';
    window.__tilesH = t.offsetHeight;
    var mark = function () { t.classList.toggle('stuck', t.getBoundingClientRect().top <= bar + 1 && window.scrollY > 0); };
    window.addEventListener('scroll', mark, { passive: true });
    mark();
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', start) : start();
})();
</script>
<style>
/* TABLE HEADERS STAY IN VIEW (owner, 29 Oct 2026: "the table's header should be fixed while scrolling the data … across the
   application"). A table taller than the screen scrolls inside its own box and its header row stays on top; the column
   colours are the th's own, so nothing shows through. Printing lets the table run its full length. */
.th-fixed{max-height:calc(100vh - var(--header-h, 62px) - 24px);overflow:auto}
.th-fixed > table > thead th{position:sticky;top:var(--th-top, 0px);z-index:3;box-shadow:inset 0 -1px 0 var(--border, #e2e8f0)}
@media print{.th-fixed{max-height:none !important;overflow:visible !important}.th-fixed > table > thead th{position:static !important}}
</style>
<script>
// TABLE HEADERS STAY IN VIEW (owner, 29 Oct 2026), every screen: each table with a header row that is taller than the
// screen gets a scrolling box (its own .table-wrap when it has one) and a sticky header. A table inside another table,
// a payslip, or one marked .no-fixed-head is left as it is. Re-checked when rows arrive (filters, tabs, Load buttons).
(function () {
  var room = function () { return window.innerHeight - (parseInt(getComputedStyle(document.documentElement).getPropertyValue('--header-h'), 10) || 62) - (window.__tilesH || 0) - 24; };
  var fix = function (t) {
    if (!t.tHead || t.closest('.no-fixed-head, .payslip, .payslip-table') || (t.parentElement && t.parentElement.closest('table'))) { return; }
    var box = t.parentElement;
    if (!box.classList.contains('th-fixed')) {
      if (t.offsetHeight <= room() || t.offsetParent === null) { return; }
      if (!box.classList.contains('table-wrap') || box.children.length !== 1) {
        box = document.createElement('div'); box.className = 'table-wrap'; t.parentNode.insertBefore(box, t); box.appendChild(t);
      }
      box.classList.add('th-fixed');
    }
    // THE BOX FITS THE SCREEN even under the Text size zoom (a zoomed page measures 100vh in zoomed pixels).
    var z = box.offsetHeight ? box.getBoundingClientRect().height / box.offsetHeight : 1;
    box.style.maxHeight = Math.max(240, Math.floor(room() / (z || 1))) + 'px';
    // A HEADER OF SEVERAL ROWS: each row sits under the ones above it.
    var top = 0;
    [].forEach.call(t.tHead.rows, function (r) { [].forEach.call(r.cells, function (c) { c.style.setProperty('--th-top', top + 'px'); }); top += r.offsetHeight; });
  };
  var run = function () { document.querySelectorAll('table').forEach(fix); };
  var timer = null;
  var later = function () { clearTimeout(timer); timer = setTimeout(run, 150); };
  var start = function () {
    run();
    window.addEventListener('resize', later);
    new MutationObserver(function (ms) { for (var i = 0; i < ms.length; i++) { if (ms[i].addedNodes.length) { later(); return; } } }).observe(document.body, { childList: true, subtree: true });
    document.addEventListener('toggle', later, true);
    document.addEventListener('click', later, true);
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', start) : start();
})();
</script>
